-- Bucket index by price via cutpoints (index seek on (product, cut_value))
CREATE   FUNCTION dbo.fn_700_choose_bucket (
  @product NVARCHAR(50),
  @price   DECIMAL(18,10)
) RETURNS INT
AS
BEGIN
  RETURN (
    SELECT COUNT(*) 
    FROM dbo.tbl_700_bucket_boundaries WITH (READCOMMITTED)
    WHERE product = @product AND cut_value <= @price
  );
END

CREATE FUNCTION dbo.fn_800_fast_exposure_safe
(
    @product NVARCHAR(50),
    @model   NVARCHAR(64),
    @fast_side VARCHAR(4)
)
RETURNS BIT
AS
BEGIN
    DECLARE
        @max_open INT = ISNULL(
            (SELECT TRY_CONVERT(INT, config_value) FROM dbo.config WITH (NOLOCK)
             WHERE config_name = 'hybrid_fast_max_open'), 4),
        @max_risk DECIMAL(19,4) = ISNULL(
            (SELECT TRY_CONVERT(DECIMAL(19,4), config_value) FROM dbo.config WITH (NOLOCK)
             WHERE config_name = 'hybrid_fast_max_risk'), 250000.0),
        @open_count INT = 0,
        @total_risk DECIMAL(19,4) = 0.0,
        @side_prefix NVARCHAR(4) = CASE WHEN UPPER(ISNULL(@fast_side,'')) = 'SELL' THEN 'sell' ELSE 'buy' END;

    SELECT
        @open_count = COUNT(1),
        @total_risk = SUM(CONVERT(DECIMAL(19,4), ABS(ISNULL(target_loss, 0))))
    FROM dbo.vwCombined_trades_open WITH (NOLOCK)
    WHERE LOWER(product) = LOWER(@product)
      AND LOWER(model) = LOWER(@model)
      AND (
            (@side_prefix = 'buy'  AND LOWER(signal) LIKE 'buy%') OR
            (@side_prefix = 'sell' AND LOWER(signal) LIKE 'sell%')
          );

    IF @open_count >= @max_open RETURN 0;
    IF @total_risk >= @max_risk RETURN 0;
    RETURN 1;
END;

CREATE   FUNCTION dbo.fn_prev_trade_had_large_loss
(
    @model   nvarchar(100),
    @signal  nvarchar(32),
    @created datetime
)
RETURNS bit
AS
BEGIN
    DECLARE @max_open_per_model int;
    DECLARE @current_open int;
    DECLARE @prev_alt_net_return float;
    DECLARE @prev_target_profit float;
    DECLARE @breach_min_target_profit float;

    SELECT @max_open_per_model = TRY_CONVERT(int, c.config_value)
    FROM dbo.config c
    WHERE c.config_name = 'max_open_trades';

    IF @max_open_per_model IS NULL SET @max_open_per_model = 1;

    SELECT @current_open = COUNT(*)
    FROM dbo.combined_trades_open o
    WHERE o.model = @model
      AND o.tradeable > 0;

    IF @current_open >= @max_open_per_model RETURN 0;

    SELECT TOP (1)
           @prev_alt_net_return = c.alt_net_return,
           @prev_target_profit = c.target_profit
    FROM dbo.combined_trades_closed c
    WHERE c.model_ix = CONVERT(varchar(200), @model)
      AND UPPER(c.signal) = UPPER(@signal)
      AND c.created < @created
    ORDER BY c.created DESC;

    IF @prev_target_profit IS NULL RETURN 0;

    SELECT @breach_min_target_profit = TRY_CONVERT(float, c.config_value)
    FROM dbo.config c
    WHERE c.config_name = 'breach_min_target_profit';

    IF @prev_alt_net_return < (@prev_target_profit * -1)
       AND @prev_target_profit > ISNULL(@breach_min_target_profit, 300)
        RETURN 1;

    RETURN 0;
END;

CREATE PROCEDURE dbo._log_step
  @proc_name sysname,
  @step      nvarchar(64),
  @product   nvarchar(50) = NULL
AS
BEGIN
  SET NOCOUNT ON;

  INSERT dbo.proc_time_log(proc_name, step, product)
  VALUES(@proc_name, @step, @product);

  DECLARE @ts   nvarchar(24)  = CONVERT(nvarchar(24), SYSUTCDATETIME(), 121);
  DECLARE @prod nvarchar(50)  = COALESCE(@product, N'-');
  DECLARE @msg  nvarchar(400) = CONCAT(@ts, N' | ', @proc_name, N' | ', @prod, N' | ', @step);

  RAISERROR(@msg, 0, 1) WITH NOWAIT;  -- immediate flush to client
END

CREATE PROCEDURE [dbo].[_sp_loop_create_trades_v2]
