            TRY_CONVERT(DATETIME2(0), CONCAT(CONVERT(date, @Now), N' ', @cfg_trade_end))
        );

    IF @trade_start_dt IS NOT NULL AND @trade_end_dt IS NOT NULL
    BEGIN
        DECLARE @now_t   TIME(0) = CONVERT(TIME(0), @Now);
        DECLARE @start_t TIME(0) = CONVERT(TIME(0), @trade_start_dt);
        DECLARE @end_t   TIME(0) = CONVERT(TIME(0), @trade_end_dt);

        IF @start_t <= @end_t
            SET @in_window = IIF(@now_t >= @start_t AND @now_t < @end_t, 1, 0);
        ELSE
