    END

    SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
             + N' trading_window start=' + COALESCE(CONVERT(NVARCHAR(19), @trade_start_dt, 120), N'(null)')
             + N' end=' + COALESCE(CONVERT(NVARCHAR(19), @trade_end_dt, 120), N'(null)')
             + N' in_window=' + CONVERT(NVARCHAR(1), @in_window);
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    IF @in_window = 0 AND @is_sim_mode = 0 -- GEMINI: 2025-09-26 - Bypass trading window in sim mode
    BEGIN
        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' outside trading window ? exit (no inserts)';
        RAISERROR(@msg, 10, 1) WITH NOWAIT;
        RETURN;
    END

    /* ---- config: skip_001_v6 / max_open_per_trade_reason ---- */
    SELECT @skip_001_v6 = TRY_CAST(config_value AS INT)
    FROM dbo.config WHERE config_name = N'skip_001_v6';
    IF @skip_001_v6 IS NULL SET @skip_001_v6 = 0;

    SELECT @max_open_limit = TRY_CAST(config_value AS INT)
    FROM dbo.config WHERE config_name = N'max_open_per_trade_reason';

    SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
             + N' config skip_001_v6=' + CONVERT(NVARCHAR(12), @skip_001_v6)
             + N' max_open_per_trade_reason=' + COALESCE(CONVERT(NVARCHAR(16), @max_open_limit), N'(null)');
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    IF @skip_001_v6 = 1
    BEGIN
        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' skip_001_v6=1 ? bypassed (no insert)';
        RAISERROR(@msg, 10, 1) WITH NOWAIT;
        RETURN;
    END

    /* ---- live quote (for entry/latest pricing) ---- */
    SELECT TOP (1)
        @quote_bid = TRY_CONVERT(DECIMAL(18,10), q.bid),
        @quote_ask = TRY_CONVERT(DECIMAL(18,10), q.ask),
        @quote_ts  = TRY_CONVERT(DATETIME2(3), q.[timestamp])
    FROM dbo.vw_000_fx_quotes AS q WITH (READPAST)
    WHERE UPPER(q.code) = UPPER(@product) AND q.[type] = 'F'
    ORDER BY q.[timestamp] DESC;

    IF (@quote_bid IS NULL OR @quote_ask IS NULL OR @quote_bid <= 0 OR @quote_ask <= 0 OR @quote_ask <= @quote_bid)
        THROW 50000, 'Invalid bid/ask for product (vw_000_fx_quotes).', 1;

    IF (@quote_ts IS NULL OR DATEDIFF(SECOND, @quote_ts, @Now) > @MaxAgeSec)
        THROW 50000, 'Stale quote for product (vw_000_fx_quotes).', 1;

 
 
/* =========================================
   v6 TRADE CRITERIA (driven by view signal)
   Source: vw_122_zone_counts_by_update_pivoted2 (latest row)
   ========================================= */
	DECLARE
		@zc_ts        DATETIME2(3),
		@sig_bs_raw   NVARCHAR(16),
		@new_signal   NVARCHAR(4) = NULL;  -- 'buy'/'sell'/NULL

	SELECT TOP (1)
		@zc_ts      = TRY_CONVERT(DATETIME2(3), last_update),
		@sig_bs_raw = signal_final
    FROM dbo.vw_122_zone_counts_by_update_pivoted2 WITH (READPAST)
    WHERE UPPER(product) = UPPER(@product)
    ORDER BY last_update DESC;

	/* Normalize and map only BUY/SELL; HOLD/PAUSE/NULL => no trade */
	IF @sig_bs_raw IS NOT NULL
	BEGIN
		SET @sig_bs_raw = LOWER(@sig_bs_raw);
		IF @sig_bs_raw = N'buy'  SET @new_signal = N'buy';
		IF @sig_bs_raw = N'sell' SET @new_signal = N'sell';
	END

	SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
			 + N' decision(new_signal)=' + COALESCE(@new_signal, N'NULL')
			 + N' from signal_final=' + COALESCE(@sig_bs_raw, N'NULL');
	RAISERROR(@msg, 10, 1) WITH NOWAIT;

	/* ---- If no actionable signal, exit ---- */
	IF @new_signal IS NULL
	BEGIN
		SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' HOLD/PAUSE/NULL ? exit (no inserts)';
		RAISERROR(@msg, 10, 1) WITH NOWAIT;
		RETURN;
	END

        /* === Profitability Check using Helper SP === */
    DECLARE @is_profitable BIT;
    DECLARE @tradeable_flag BIT = 1;
    EXEC dbo.sp_helper_check_alt_net_return
        @product      = @product,
        @trade_reason = @reason_tag,
        @signal       = @new_signal,
        @is_profitable = @is_profitable OUTPUT;

    IF @is_profitable = 0
    BEGIN
        SET @tradeable_flag = 0;
        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' profitability check failed for signal=' + @new_signal + N' - flagging tradeable=0';
        RAISERROR(@msg, 10, 1) WITH NOWAIT;
    END

    /* ---- Find existing open trade for same reason ---- */
    DECLARE
        @cur_open_guid UNIQUEIDENTIFIER,
        @cur_open_signal NVARCHAR(4);

    SELECT TOP (1)
        @cur_open_guid   = o.guid,
        @cur_open_signal = o.signal
    FROM dbo.combined_trades_open AS o WITH (UPDLOCK, READPAST)
    WHERE o.product = @product
      AND o.trade_reason = @reason_tag
    ORDER BY o.created DESC;

    IF @cur_open_guid IS NOT NULL
    BEGIN
        IF @cur_open_signal = @new_signal
        BEGIN
            -- Same direction already open ? NOOP
            SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                     + N' existing open with same signal (' + @cur_open_signal + N') ? no action';
            RAISERROR(@msg, 10, 1) WITH NOWAIT;
            RETURN;
        END
        ELSE
        BEGIN
            -- Opposite direction ? CLOSE then OPEN
            DECLARE @close_signal NVARCHAR(4) = @cur_open_signal; -- the one to close
            SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                     + N' opposite detected: closing existing ' + @close_signal + N' before opening ' + @new_signal;
            RAISERROR(@msg, 10, 1) WITH NOWAIT;

            DECLARE @rc INT;
            EXEC @rc = dbo.sp_003_CloseTradesTargetReached_refactored
                @product         = @product,
                @signal_to_close = @close_signal,    -- 'buy' or 'sell'
                @trade_reason    = @reason_tag,      -- 'sp_001_v6'
                @close_count     = 1;                -- close most-recent ONE

            IF (@rc IS NULL) SET @rc = 0;
            IF @rc <> 0
            BEGIN
                -- close failed ? abort (do not open new)
                THROW 50001, 'sp_003_close failed (non-zero return code).', 1;
            END

            SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' close done ? proceed to open ' + @new_signal;
            RAISERROR(@msg, 10, 1) WITH NOWAIT;
        END
    END

    /* ---- max open per trade_reason gate (still enforced) ---- */
    IF @max_open_limit IS NOT NULL AND @max_open_limit > 0
    BEGIN
        SELECT @open_active = COUNT(*)
        FROM dbo.combined_trades_open WITH (NOLOCK)
        WHERE product = @product
          AND trade_reason = @reason_tag;

        IF @open_active >= @max_open_limit
        BEGIN
            SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                     + N' cap reached after close-check ? exit (no inserts)';
            RAISERROR(@msg, 10, 1) WITH NOWAIT;
            RETURN;
        END
    END

    /* ---- build BUY/SELL candidates from last closed attrs (unchanged) ---- */
    IF OBJECT_ID('tempdb..#candidates') IS NOT NULL DROP TABLE #candidates;

    ;WITH last_closed AS (
        SELECT c.product, c.model, c.signal,
               c.product_type, c.target_profit, c.target_loss,
               c.rl_signal, c.RL_Check, c.buy_count, c.sell_count,
               c.linked, c.int_profit, c.int_profit_time,
               ROW_NUMBER() OVER (
                   PARTITION BY c.product, c.signal
                   ORDER BY c.created DESC
               ) AS rn
        FROM dbo.combined_trades_closed AS c WITH (NOLOCK)
        WHERE c.product = @product
    )
    SELECT
        NEWID() AS guid,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.model
                      WHEN s.signal='sell' THEN lc_sell.model END, N'100030') AS model,
        @product                              AS product,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.product_type
                      WHEN s.signal='sell' THEN lc_sell.product_type END, N'F')  AS product_type,
        s.signal                               AS signal,

        /* prices from live */
        CASE WHEN s.signal='buy' THEN @quote_ask ELSE @quote_bid END AS entry_price,
        CASE WHEN s.signal='buy' THEN @quote_ask ELSE @quote_bid END AS latest_price,

        CASE WHEN s.signal='buy' THEN @quote_bid ELSE @quote_ask END AS entry_price2,
        CASE WHEN s.signal='buy' THEN @quote_ask ELSE @quote_bid END AS latest_price2,

        @Commission                            AS commission,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.target_profit
                      WHEN s.signal='sell' THEN lc_sell.target_profit END, 200) AS target_profit,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.target_loss
                      WHEN s.signal='sell' THEN lc_sell.target_loss END,  -100) AS target_loss,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.rl_signal
                      WHEN s.signal='sell' THEN lc_sell.rl_signal END, NULL)   AS rl_signal,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.RL_Check
                      WHEN s.signal='sell' THEN lc_sell.RL_Check END, 0)       AS RL_Check,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.buy_count
                      WHEN s.signal='sell' THEN lc_sell.buy_count END, 0)      AS buy_count,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.sell_count
                      WHEN s.signal='sell' THEN lc_sell.sell_count END, 0)     AS sell_count,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.linked
                      WHEN s.signal='sell' THEN lc_sell.linked END, 0)         AS linked,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.int_profit
                      WHEN s.signal='sell' THEN lc_sell.int_profit END, NULL)  AS int_profit,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.int_profit_time
                      WHEN s.signal='sell' THEN lc_sell.int_profit_time END, NULL) AS int_profit_time,
        @TradeQuantity                         AS trade_quantity
    INTO #candidates
    FROM (VALUES ('buy'), ('sell')) AS s(signal)
    LEFT JOIN last_closed lc_buy
      ON lc_buy.product = @product AND lc_buy.signal='buy'  AND lc_buy.rn=1
    LEFT JOIN last_closed lc_sell
      ON lc_sell.product = @product AND lc_sell.signal='sell' AND lc_sell.rn=1;

    /* ---- insert only the decided side ---- */
    DECLARE @inserted INT = 0;

    IF @new_signal = N'buy'
    BEGIN
        INSERT INTO dbo.combined_trades_open (
            guid, model, product, product_type, created, last_update, signal,
            entry_price, latest_price, entry_price2, latest_price2,
            commission, target_profit, target_loss, rl_signal, tradeable,
            net_return, alt_net_return, pos_net_return_buy, pos_net_return_sell,
            trade_diff, RL_Check, percent_profit, percent_loss,
            buy_count, sell_count, linked, int_profit, int_profit_time,
            trade_quantity, flip_trade, trade_reason
        )
        SELECT TOP (1)
            guid, model, product, product_type, @Now, @Now, N'buy',
            entry_price, latest_price, entry_price2, latest_price2,
            commission, target_profit, target_loss, rl_signal, @tradeable_flag,
            0, 0, 0, 0, 0, RL_Check, 0, 0,
            buy_count, sell_count, linked, int_profit, int_profit_time,
            trade_quantity, 0, @reason_tag
        FROM #candidates
        WHERE signal=N'buy';

        SET @inserted += @@ROWCOUNT;
    END
    ELSE IF @new_signal = N'sell'
    BEGIN
        INSERT INTO dbo.combined_trades_open (
            guid, model, product, product_type, created, last_update, signal,
            entry_price, latest_price, entry_price2, latest_price2,
            commission, target_profit, target_loss, rl_signal, tradeable,
            net_return, alt_net_return, pos_net_return_buy, pos_net_return_sell,
            trade_diff, RL_Check, percent_profit, percent_loss,
            buy_count, sell_count, linked, int_profit, int_profit_time,
            trade_quantity, flip_trade, trade_reason
        )
        SELECT TOP (1)
            guid, model, product, product_type, @Now, @Now, N'sell',
            entry_price, latest_price, entry_price2, latest_price2,
            commission, target_profit, target_loss, rl_signal, @tradeable_flag,
            0, 0, 0, 0, 0, RL_Check, 0, 0,
            buy_count, sell_count, linked, int_profit, int_profit_time,
            trade_quantity, 0, @reason_tag
        FROM #candidates
        WHERE signal=N'sell';

        SET @inserted += @@ROWCOUNT;
    END

    SET @msg = CONVERT(NVARCHAR(23), GETDATE(), 121) + N' ' + @tag
             + N' action=' + CASE 
                                WHEN @cur_open_guid IS NULL THEN N'OPEN'
                                WHEN @cur_open_signal = @new_signal THEN N'NOOP'
                                ELSE N'CLOSE?OPEN'
                              END
             + N' new_signal=' + @new_signal
             + N' inserted_rows=' + CONVERT(NVARCHAR(20), @inserted);
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    /* ---- end log ---- */
    SET @msg = CONVERT(NVARCHAR(23), GETDATE(), 121) + N' ' + @tag + N' done';
    RAISERROR(@msg, 10, 1) WITH NOWAIT;
END

CREATE PROCEDURE [dbo].[sp_001_copy_trade_as_tradeable_v7]
    @product        NVARCHAR(50)  = N'gbp',
    @TradeQuantity  BIGINT        = 100000,
    @Commission     DECIMAL(18,6) = 20
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    /* ==== locals ==== */
    DECLARE
        @Now             DATETIME2(3) = GETDATE(),
        @MaxAgeSec       INT          = 60,
        @quote_bid       DECIMAL(18,10),
        @quote_ask       DECIMAL(18,10),
        @quote_ts        DATETIME2(3),
        @ts              NVARCHAR(23),
        @skip_001_v7     INT = 0,
        @max_open_limit  INT,
        @open_active     INT;

    -- GEMINI: 2025-09-26 - Declare and call sim mode helper
    DECLARE @is_sim_mode BIT;
    EXEC dbo.sp_helper_is_sim_db @is_sim_mode = @is_sim_mode OUTPUT;

    DECLARE
        @tag        SYSNAME      = N'sp_001_v7',
        @msg        NVARCHAR(4000),
        @reason_tag NVARCHAR(64) = N'sp_001_v7';

    /* ---- start log ---- */
    SET @ts  = CONVERT(NVARCHAR(23), @Now, 121);
    SET @msg = @ts + N' ' + @tag + N' start product=' + @product
             + N' TradeQty=' + CONVERT(NVARCHAR(32), @TradeQuantity)
             + N' Commission=' + CONVERT(NVARCHAR(32), @Commission);
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    /* =========================
       Trading window (config)
       ========================= */
    DECLARE
        @cfg_trade_start NVARCHAR(64),
        @cfg_trade_end   NVARCHAR(64),
        @trade_start_dt  DATETIME2(0),
        @trade_end_dt    DATETIME2(0),
        @in_window       BIT = 1;

    SELECT @cfg_trade_start = config_value
    FROM dbo.config WHERE config_name = N'trade_start';

    SELECT @cfg_trade_end = config_value
    FROM dbo.config WHERE config_name = N'trade_end';

    SET @trade_start_dt =
        COALESCE(
            TRY_CONVERT(DATETIME2(0), @cfg_trade_start),
            TRY_CONVERT(DATETIME2(0), CONCAT(CONVERT(date, @Now), N' ', @cfg_trade_start))
        );

    SET @trade_end_dt =
        COALESCE(
            TRY_CONVERT(DATETIME2(0), @cfg_trade_end),
            TRY_CONVERT(DATETIME2(0), CONCAT(CONVERT(date, @Now), N' ', @cfg_trade_end))
        );

    IF @trade_start_dt IS NOT NULL AND @trade_end_dt IS NOT NULL
    BEGIN
        DECLARE @now_t   TIME(0) = CONVERT(TIME(0), @Now);
        DECLARE @start_t TIME(0) = CONVERT(TIME(0), @trade_start_dt);
        DECLARE @end_t   TIME(0) = CONVERT(TIME(0), @trade_end_dt);

        IF @start_t <= @end_t
            SET @in_window = IIF(@now_t >= @start_t AND @now_t < @end_t, 1, 0);
        ELSE
            SET @in_window = IIF(@now_t >= @start_t OR  @now_t < @end_t, 1, 0);
    END

    SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
             + N' trading_window start=' + COALESCE(CONVERT(NVARCHAR(19), @trade_start_dt, 120), N'(null)')
             + N' end=' + COALESCE(CONVERT(NVARCHAR(19), @trade_end_dt, 120), N'(null)')
             + N' in_window=' + CONVERT(NVARCHAR(1), @in_window);
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    IF @in_window = 0 AND @is_sim_mode = 0 -- GEMINI: 2025-09-26 - Bypass trading window in sim mode
    BEGIN
        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' outside trading window ? exit (no inserts)';
        RAISERROR(@msg, 10, 1) WITH NOWAIT;
        RETURN;
    END

    /* ---- config: skip_001_v7 / max_open_per_trade_reason ---- */
    SELECT @skip_001_v7 = TRY_CAST(config_value AS INT)
    FROM dbo.config WHERE config_name = N'skip_001_v7';
    IF @skip_001_v7 IS NULL SET @skip_001_v7 = 0;

    SELECT @max_open_limit = TRY_CAST(config_value AS INT)
    FROM dbo.config WHERE config_name = N'max_open_per_trade_reason';

    SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
             + N' config skip_001_v7=' + CONVERT(NVARCHAR(12), @skip_001_v7)
             + N' max_open_per_trade_reason=' + COALESCE(CONVERT(NVARCHAR(16), @max_open_limit), N'(null)');
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    IF @skip_001_v7 = 1
    BEGIN
        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' skip_001_v7=1 ? bypassed (no insert)';
        RAISERROR(@msg, 10, 1) WITH NOWAIT;
        RETURN;
    END

    /* ---- live quote (for entry/latest pricing) ---- */
    SELECT TOP (1)
        @quote_bid = TRY_CONVERT(DECIMAL(18,10), q.bid),
        @quote_ask = TRY_CONVERT(DECIMAL(18,10), q.ask),
        @quote_ts  = TRY_CONVERT(DATETIME2(3), q.[timestamp])
    FROM dbo.vw_000_fx_quotes AS q WITH (READPAST)
    WHERE UPPER(q.code) = UPPER(@product) AND q.[type] = 'F'
    ORDER BY q.[timestamp] DESC;

    IF (@quote_bid IS NULL OR @quote_ask IS NULL OR @quote_bid <= 0 OR @quote_ask <= 0 OR @quote_ask <= @quote_bid)
        THROW 50000, 'Invalid bid/ask for product (vw_000_fx_quotes).', 1;

    IF (@quote_ts IS NULL OR DATEDIFF(SECOND, @quote_ts, @Now) > @MaxAgeSec)
        THROW 50000, 'Stale quote for product (vw_000_fx_quotes).', 1;

 
 
                /* =========================================
       v7 TRADE CRITERIA (driven by view signal)
       Source: vw_123_zone_counts_with_prev (latest row)
       ========================================= */
    DECLARE
        @zc_ts          DATETIME2(3),
        @red_buy        INT,
        @prev_red_buy   INT,
        @red_sell       INT,
        @prev_red_sell  INT,
        @darkgreen_buy  INT,
        @darkgreen_sell INT,
        @new_signal     NVARCHAR(4) = NULL;  -- 'buy'/'sell'/NULL

    SELECT TOP (1)
        @zc_ts          = TRY_CONVERT(DATETIME2(3), last_update),
        @red_buy        = TRY_CAST(red_buy AS INT),
        @prev_red_buy   = TRY_CAST(prev_red_buy AS INT),
        @red_sell       = TRY_CAST(red_sell AS INT),
        @prev_red_sell  = TRY_CAST(prev_red_sell AS INT),
        @darkgreen_buy  = TRY_CAST(darkgreen_buy AS INT),
        @darkgreen_sell = TRY_CAST(darkgreen_sell AS INT)
    FROM dbo.vw_123_zone_counts_with_prev WITH (READPAST)
    WHERE UPPER(product) = UPPER(@product)
    ORDER BY last_update DESC;

    IF ISNULL(@prev_red_buy, 0) = 0 AND ISNULL(@red_buy, 0) > 0 AND ISNULL(@darkgreen_buy, 0) = 0
        SET @new_signal = N'buy';

    IF ISNULL(@prev_red_sell, 0) = 0 AND ISNULL(@red_sell, 0) > 0 AND ISNULL(@darkgreen_sell, 0) = 0
        SET @new_signal = N'sell';

    SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
             + N' decision(new_signal)=' + COALESCE(@new_signal, N'NULL')
             + N' from counts prev_red_buy=' + COALESCE(CONVERT(NVARCHAR(12), @prev_red_buy), N'NULL')
             + N' red_buy=' + COALESCE(CONVERT(NVARCHAR(12), @red_buy), N'NULL')
             + N' prev_red_sell=' + COALESCE(CONVERT(NVARCHAR(12), @prev_red_sell), N'NULL')
             + N' red_sell=' + COALESCE(CONVERT(NVARCHAR(12), @red_sell), N'NULL')
             + N' darkgreen_buy=' + COALESCE(CONVERT(NVARCHAR(12), @darkgreen_buy), N'NULL')
             + N' darkgreen_sell=' + COALESCE(CONVERT(NVARCHAR(12), @darkgreen_sell), N'NULL')
             + N' last_update=' + COALESCE(CONVERT(NVARCHAR(23), @zc_ts, 121), N'(null)');
    RAISERROR(@msg, 10, 1) WITH NOWAIT;
	/* ---- If no actionable signal, exit ---- */
	IF @new_signal IS NULL
	BEGIN
		SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' HOLD/PAUSE/NULL ? exit (no inserts)';
		RAISERROR(@msg, 10, 1) WITH NOWAIT;
		RETURN;
	END
    /* === Profitability Check using Helper SP === */
    DECLARE @is_profitable BIT;
    DECLARE @tradeable_flag BIT = 1;
    -- GEMINI: 2025-09-29 - Add conditional skip for profitability check
    DECLARE @skip_profit_check_config NVARCHAR(MAX);
    DECLARE @skip_profit_check_for_this_sp BIT = 0;

    SELECT @skip_profit_check_config = config_value
    FROM dbo.config WHERE config_name = N'skip_profit_check';

    -- GEMINI: 2025-09-30 - Debug log for profitability skip check
    SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
             + N' Debug: @reason_tag=' + COALESCE(@reason_tag, N'NULL')
             + N', @skip_profit_check_config=' + COALESCE(@skip_profit_check_config, N'NULL')
             + N', CHARINDEX=' + CONVERT(NVARCHAR(12), CHARINDEX(@reason_tag, @skip_profit_check_config));
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    IF @skip_profit_check_config IS NOT NULL AND CHARINDEX(@reason_tag, @skip_profit_check_config) > 0
    BEGIN
        SET @skip_profit_check_for_this_sp = 1;
        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' profitability check skipped for ' + @reason_tag + N' as per config.';
        RAISERROR(@msg, 10, 1) WITH NOWAIT;
    END

    IF @skip_profit_check_for_this_sp = 0
    BEGIN
        EXEC dbo.sp_helper_check_alt_net_return
            @product       = @product,
            @trade_reason  = @reason_tag,
            @signal        = @new_signal,
            @is_profitable = @is_profitable OUTPUT;

        IF @is_profitable = 0
        BEGIN
            SET @tradeable_flag = 0;
            SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                     + N' profitability check failed for signal=' + @new_signal + N' - flagging tradeable=0';
            RAISERROR(@msg, 10, 1) WITH NOWAIT;
        END
    END
    ELSE
    BEGIN
        -- If skipped, assume profitable for tradeable_flag
        SET @tradeable_flag = 1;
    END
/* ---- Find existing open trade for same reason ---- */
    DECLARE
        @cur_open_guid UNIQUEIDENTIFIER,
        @cur_open_signal NVARCHAR(4);

    SELECT TOP (1)
        @cur_open_guid   = o.guid,
        @cur_open_signal = o.signal
    FROM dbo.combined_trades_open AS o WITH (UPDLOCK, READPAST)
    WHERE o.product = @product
      AND o.trade_reason = @reason_tag
    ORDER BY o.created DESC;

        IF @cur_open_guid IS NOT NULL
    BEGIN
        IF @cur_open_signal = @new_signal
        BEGIN
            -- Same direction already open - no action
            SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                     + N' existing open with same signal (' + @cur_open_signal + N') - no action';
            RAISERROR(@msg, 10, 1) WITH NOWAIT;
            RETURN;
        END

        -- Opposite direction detected; close existing before opening new
        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                 + N' opposite detected: closing existing ' + @cur_open_signal + N' before opening ' + @new_signal;
        RAISERROR(@msg, 10, 1) WITH NOWAIT;

        DECLARE @rc INT;
        EXEC @rc = dbo.sp_003_CloseTradesTargetReached_refactored
            @product         = @product,
            @signal_to_close = @cur_open_signal,
            @trade_reason    = @reason_tag,
            @close_count     = 1,
            @guid_to_close = @cur_open_guid;

        IF (@rc IS NULL) SET @rc = 0;
        IF @rc <> 0
        BEGIN
            SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                     + N' sp_003_close failed (rc=' + CONVERT(NVARCHAR(12), @rc) + N') - skipping new ' + @new_signal;
            RAISERROR(@msg, 10, 1) WITH NOWAIT;
            RETURN;
        END

        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' close done ? proceed to open ' + @new_signal;
        RAISERROR(@msg, 10, 1) WITH NOWAIT;
    END
    /* ---- max open per trade_reason gate (still enforced) ---- */
    IF @max_open_limit IS NOT NULL AND @max_open_limit > 0
    BEGIN
        SELECT @open_active = COUNT(*)
        FROM dbo.combined_trades_open WITH (NOLOCK)
        WHERE product = @product
          AND trade_reason = @reason_tag;

        IF @open_active >= @max_open_limit
        BEGIN
            SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                     + N' cap reached after close-check ? exit (no inserts)';
            RAISERROR(@msg, 10, 1) WITH NOWAIT;
            RETURN;
        END
    END

    /* ---- build BUY/SELL candidates from last closed attrs (unchanged) ---- */
    IF OBJECT_ID('tempdb..#candidates') IS NOT NULL DROP TABLE #candidates;

    ;WITH last_closed AS (
        SELECT c.product, c.model, c.signal,
               c.product_type, c.target_profit, c.target_loss,
               c.rl_signal, c.RL_Check, c.buy_count, c.sell_count,
               c.linked, c.int_profit, c.int_profit_time,
               ROW_NUMBER() OVER (
                   PARTITION BY c.product, c.signal
                   ORDER BY c.created DESC
               ) AS rn
        FROM dbo.combined_trades_closed AS c WITH (NOLOCK)
        WHERE c.product = @product
    )
    SELECT
        NEWID() AS guid,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.model
                      WHEN s.signal='sell' THEN lc_sell.model END, N'100030') AS model,
        @product                              AS product,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.product_type
                      WHEN s.signal='sell' THEN lc_sell.product_type END, N'F')  AS product_type,
        s.signal                               AS signal,

        /* prices from live */
        CASE WHEN s.signal='buy' THEN @quote_ask ELSE @quote_bid END AS entry_price,
        CASE WHEN s.signal='buy' THEN @quote_ask ELSE @quote_bid END AS latest_price,

        CASE WHEN s.signal='buy' THEN @quote_bid ELSE @quote_ask END AS entry_price2,
        CASE WHEN s.signal='buy' THEN @quote_ask ELSE @quote_bid END AS latest_price2,

        @Commission                            AS commission,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.target_profit
                      WHEN s.signal='sell' THEN lc_sell.target_profit END, 200) AS target_profit,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.target_loss
                      WHEN s.signal='sell' THEN lc_sell.target_loss END,  -100) AS target_loss,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.rl_signal
                      WHEN s.signal='sell' THEN lc_sell.rl_signal END, NULL)   AS rl_signal,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.RL_Check
                      WHEN s.signal='sell' THEN lc_sell.RL_Check END, 0)       AS RL_Check,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.buy_count
                      WHEN s.signal='sell' THEN lc_sell.buy_count END, 0)      AS buy_count,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.sell_count
                      WHEN s.signal='sell' THEN lc_sell.sell_count END, 0)     AS sell_count,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.linked
                      WHEN s.signal='sell' THEN lc_sell.linked END, 0)         AS linked,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.int_profit
                      WHEN s.signal='sell' THEN lc_sell.int_profit END, NULL)  AS int_profit,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.int_profit_time
                      WHEN s.signal='sell' THEN lc_sell.int_profit_time END, NULL) AS int_profit_time,
        @TradeQuantity                         AS trade_quantity
    INTO #candidates
    FROM (VALUES ('buy'), ('sell')) AS s(signal)
    LEFT JOIN last_closed lc_buy
      ON lc_buy.product = @product AND lc_buy.signal='buy'  AND lc_buy.rn=1
    LEFT JOIN last_closed lc_sell
      ON lc_sell.product = @product AND lc_sell.signal='sell' AND lc_sell.rn=1;

    /* ---- insert only the decided side ---- */
    DECLARE @inserted INT = 0;

    IF @new_signal = N'buy'
    BEGIN
        INSERT INTO dbo.combined_trades_open (
            guid, model, product, product_type, created, last_update, signal,
            entry_price, latest_price, entry_price2, latest_price2,
            commission, target_profit, target_loss, rl_signal, tradeable,
            net_return, alt_net_return, pos_net_return_buy, pos_net_return_sell,
            trade_diff, RL_Check, percent_profit, percent_loss,
            buy_count, sell_count, linked, int_profit, int_profit_time,
            trade_quantity, flip_trade, trade_reason
        )
        SELECT TOP (1)
            guid, model, product, product_type, @Now, @Now, N'buy',
            entry_price, latest_price, entry_price2, latest_price2,
            commission, target_profit, target_loss, rl_signal, @tradeable_flag,
            0, 0, 0, 0, 0, RL_Check, 0, 0,
            buy_count, sell_count, linked, int_profit, int_profit_time,
            trade_quantity, 1, @reason_tag
        FROM #candidates
        WHERE signal=N'buy';

        SET @inserted += @@ROWCOUNT;
    END
    ELSE IF @new_signal = N'sell'
    BEGIN
        INSERT INTO dbo.combined_trades_open (
            guid, model, product, product_type, created, last_update, signal,
            entry_price, latest_price, entry_price2, latest_price2,
            commission, target_profit, target_loss, rl_signal, tradeable,
            net_return, alt_net_return, pos_net_return_buy, pos_net_return_sell,
            trade_diff, RL_Check, percent_profit, percent_loss,
            buy_count, sell_count, linked, int_profit, int_profit_time,
            trade_quantity, flip_trade, trade_reason
        )
        SELECT TOP (1)
            guid, model, product, product_type, @Now, @Now, N'sell',
            entry_price, latest_price, entry_price2, latest_price2,
            commission, target_profit, target_loss, rl_signal, @tradeable_flag,
            0, 0, 0, 0, 0, RL_Check, 0, 0,
            buy_count, sell_count, linked, int_profit, int_profit_time,
            trade_quantity, 1, @reason_tag
        FROM #candidates
        WHERE signal=N'sell';

        SET @inserted += @@ROWCOUNT;
    END

    SET @msg = CONVERT(NVARCHAR(23), GETDATE(), 121) + N' ' + @tag
             + N' action=' + CASE 
                                WHEN @cur_open_guid IS NULL THEN N'OPEN'
                                WHEN @cur_open_signal = @new_signal THEN N'NOOP'
                                ELSE N'CLOSE?OPEN'
                              END
             + N' new_signal=' + @new_signal
             + N' inserted_rows=' + CONVERT(NVARCHAR(20), @inserted);
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    /* ---- end log ---- */
    SET @msg = CONVERT(NVARCHAR(23), GETDATE(), 121) + N' ' + @tag + N' done';
    RAISERROR(@msg, 10, 1) WITH NOWAIT;
END

CREATE PROCEDURE [dbo].[sp_001_copy_trade_as_tradeable_v701]
    @product        NVARCHAR(50)  = N'gbp',
    @TradeQuantity  BIGINT        = 100000,
    @Commission     DECIMAL(18,6) = 20
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    /* ==== locals ==== */
    DECLARE
        @Now             DATETIME2(3) = GETDATE(),
        @MaxAgeSec       INT          = 60,
        @quote_bid       DECIMAL(18,10),
        @quote_ask       DECIMAL(18,10),
        @quote_ts        DATETIME2(3),
        @ts              NVARCHAR(23),
        @skip_001_v701     INT = 0,
        @max_open_limit  INT,
        @open_active     INT;

    -- GEMINI: 2025-09-26 - Declare and call sim mode helper
    DECLARE @is_sim_mode BIT;
    EXEC dbo.sp_helper_is_sim_db @is_sim_mode = @is_sim_mode OUTPUT;

    DECLARE
        @tag        SYSNAME      = N'sp_001_v701',
        @msg        NVARCHAR(4000),
        @reason_tag NVARCHAR(64) = N'sp_001_v701';

    /* ---- start log ---- */
    SET @ts  = CONVERT(NVARCHAR(23), @Now, 121);
    SET @msg = @ts + N' ' + @tag + N' start product=' + @product
             + N' TradeQty=' + CONVERT(NVARCHAR(32), @TradeQuantity)
             + N' Commission=' + CONVERT(NVARCHAR(32), @Commission);
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    /* =========================
       Trading window (config)
       ========================= */
    DECLARE
        @cfg_trade_start NVARCHAR(64),
        @cfg_trade_end   NVARCHAR(64),
        @trade_start_dt  DATETIME2(0),
        @trade_end_dt    DATETIME2(0),
        @in_window       BIT = 1;

    SELECT @cfg_trade_start = config_value
    FROM dbo.config WHERE config_name = N'trade_start';

    SELECT @cfg_trade_end = config_value
    FROM dbo.config WHERE config_name = N'trade_end';

    SET @trade_start_dt =
        COALESCE(
            TRY_CONVERT(DATETIME2(0), @cfg_trade_start),
            TRY_CONVERT(DATETIME2(0), CONCAT(CONVERT(date, @Now), N' ', @cfg_trade_start))
        );

    SET @trade_end_dt =
        COALESCE(
            TRY_CONVERT(DATETIME2(0), @cfg_trade_end),
            TRY_CONVERT(DATETIME2(0), CONCAT(CONVERT(date, @Now), N' ', @cfg_trade_end))
        );

    IF @trade_start_dt IS NOT NULL AND @trade_end_dt IS NOT NULL
    BEGIN
        DECLARE @now_t   TIME(0) = CONVERT(TIME(0), @Now);
        DECLARE @start_t TIME(0) = CONVERT(TIME(0), @trade_start_dt);
        DECLARE @end_t   TIME(0) = CONVERT(TIME(0), @trade_end_dt);

        IF @start_t <= @end_t
            SET @in_window = IIF(@now_t >= @start_t AND @now_t < @end_t, 1, 0);
        ELSE
            SET @in_window = IIF(@now_t >= @start_t OR  @now_t < @end_t, 1, 0);
    END

    SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
             + N' trading_window start=' + COALESCE(CONVERT(NVARCHAR(19), @trade_start_dt, 120), N'(null)')
             + N' end=' + COALESCE(CONVERT(NVARCHAR(19), @trade_end_dt, 120), N'(null)')
             + N' in_window=' + CONVERT(NVARCHAR(1), @in_window);
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    IF @in_window = 0 AND @is_sim_mode = 0 -- GEMINI: 2025-09-26 - Bypass trading window in sim mode
    BEGIN
        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' outside trading window ? exit (no inserts)';
        RAISERROR(@msg, 10, 1) WITH NOWAIT;
        RETURN;
    END

    /* ---- config: skip_001_v701 / max_open_per_trade_reason ---- */
    SELECT @skip_001_v701 = TRY_CAST(config_value AS INT)
    FROM dbo.config WHERE config_name = N'skip_001_v701';
    IF @skip_001_v701 IS NULL SET @skip_001_v701 = 0;

    SELECT @max_open_limit = TRY_CAST(config_value AS INT)
    FROM dbo.config WHERE config_name = N'max_open_per_trade_reason';

    SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
             + N' config skip_001_v701=' + CONVERT(NVARCHAR(12), @skip_001_v701)
             + N' max_open_per_trade_reason=' + COALESCE(CONVERT(NVARCHAR(16), @max_open_limit), N'(null)');
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    IF @skip_001_v701 = 1
    BEGIN
        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' skip_001_v701=1 ? bypassed (no insert)';
        RAISERROR(@msg, 10, 1) WITH NOWAIT;
        RETURN;
    END

    /* ---- live quote (for entry/latest pricing) ---- */
    SELECT TOP (1)
        @quote_bid = TRY_CONVERT(DECIMAL(18,10), q.bid),
        @quote_ask = TRY_CONVERT(DECIMAL(18,10), q.ask),
        @quote_ts  = TRY_CONVERT(DATETIME2(3), q.[timestamp])
    FROM dbo.vw_000_fx_quotes AS q WITH (READPAST)
    WHERE UPPER(q.code) = UPPER(@product) AND q.[type] = 'F'
    ORDER BY q.[timestamp] DESC;

    IF (@quote_bid IS NULL OR @quote_ask IS NULL OR @quote_bid <= 0 OR @quote_ask <= 0 OR @quote_ask <= @quote_bid)
        THROW 50000, 'Invalid bid/ask for product (vw_000_fx_quotes).', 1;

    IF (@quote_ts IS NULL OR DATEDIFF(SECOND, @quote_ts, @Now) > @MaxAgeSec)
        THROW 50000, 'Stale quote for product (vw_000_fx_quotes).', 1;

 
 
        /* =========================================
       v701 TRADE CRITERIA (driven by view signal)
       Source: vw_123_zone_counts_with_prev (latest row)
       ========================================= */
    DECLARE
        @zc_ts         DATETIME2(3),
        @darkgreen_buy       INT,
        @prev_darkgreen_buy  INT,
        @darkgreen_sell      INT,
        @prev_darkgreen_sell INT,
        @new_signal    NVARCHAR(4) = NULL;  -- 'buy'/'sell'/NULL

    SELECT TOP (1)
        @zc_ts         = TRY_CONVERT(DATETIME2(3), last_update),
        @darkgreen_buy       = TRY_CAST(darkgreen_buy AS INT),
        @prev_darkgreen_buy  = TRY_CAST(prev_darkgreen_buy AS INT),
        @darkgreen_sell      = TRY_CAST(darkgreen_sell AS INT),
        @prev_darkgreen_sell = TRY_CAST(prev_darkgreen_sell AS INT)
    FROM dbo.vw_123_zone_counts_with_prev WITH (READPAST)
    WHERE UPPER(product) = UPPER(@product)
    ORDER BY last_update DESC;

    	IF ISNULL(@darkgreen_sell, 0) = 0 AND ISNULL(@darkgreen_buy, 0) > 0
            SET @new_signal = N'buy';
    
        IF ISNULL(@darkgreen_buy, 0) = 0 AND ISNULL(@darkgreen_sell, 0) > 0
            SET @new_signal = N'sell';
    SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
             + N' decision(new_signal)=' + COALESCE(@new_signal, N'NULL')
             + N' from counts prev_darkgreen_buy=' + COALESCE(CONVERT(NVARCHAR(12), @prev_darkgreen_buy), N'NULL')
             + N' darkgreen_buy=' + COALESCE(CONVERT(NVARCHAR(12), @darkgreen_buy), N'NULL')
             + N' prev_darkgreen_sell=' + COALESCE(CONVERT(NVARCHAR(12), @prev_darkgreen_sell), N'NULL')
             + N' darkgreen_sell=' + COALESCE(CONVERT(NVARCHAR(12), @darkgreen_sell), N'NULL')
             + N' last_update=' + COALESCE(CONVERT(NVARCHAR(23), @zc_ts, 121), N'(null)');
    RAISERROR(@msg, 10, 1) WITH NOWAIT;
	/* ---- If no actionable signal, exit ---- */
	IF @new_signal IS NULL
	BEGIN
		SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' HOLD/PAUSE/NULL ? exit (no inserts)';
		RAISERROR(@msg, 10, 1) WITH NOWAIT;
		RETURN;
	END
    /* === Profitability Check using Helper SP === */
    DECLARE @is_profitable BIT;
    DECLARE @tradeable_flag BIT = 0;
    -- GEMINI: 2025-09-29 - Add conditional skip for profitability check
    DECLARE @skip_profit_check_config NVARCHAR(MAX);
    DECLARE @skip_profit_check_for_this_sp BIT = 0;

    SELECT @skip_profit_check_config = config_value
    FROM dbo.config WHERE config_name = N'skip_profit_check';

    -- GEMINI: 2025-09-30 - Debug log for profitability skip check
    SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
             + N' Debug: @reason_tag=' + COALESCE(@reason_tag, N'NULL')
             + N', @skip_profit_check_config=' + COALESCE(@skip_profit_check_config, N'NULL')
             + N', CHARINDEX=' + CONVERT(NVARCHAR(12), CHARINDEX(@reason_tag, @skip_profit_check_config));
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    IF @skip_profit_check_config IS NOT NULL AND CHARINDEX(@reason_tag, @skip_profit_check_config) > 0
    BEGIN
        SET @skip_profit_check_for_this_sp = 1;
        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' profitability check skipped for ' + @reason_tag + N' as per config.';
        RAISERROR(@msg, 10, 1) WITH NOWAIT;
    END

    IF @skip_profit_check_for_this_sp = 0
    BEGIN
        EXEC dbo.sp_helper_check_alt_net_return
            @product       = @product,
            @trade_reason  = @reason_tag,
            @signal        = @new_signal,
            @is_profitable = @is_profitable OUTPUT;

        IF ISNULL(@is_profitable, 0) = 1
        BEGIN
            SET @tradeable_flag = 1;
        END
        ELSE
        BEGIN
            SET @tradeable_flag = 0;
            SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                     + N' profitability check failed for signal=' + @new_signal + N' - flagging tradeable=0';
            RAISERROR(@msg, 10, 1) WITH NOWAIT;
        END
    END
    ELSE
    BEGIN
        -- If skipped, assume profitable for tradeable_flag
        SET @tradeable_flag = 1;
    END
/* ---- Find existing open trade for same reason ---- */
    DECLARE
        @cur_open_guid UNIQUEIDENTIFIER,
        @cur_open_signal NVARCHAR(4);

    SELECT TOP (1)
        @cur_open_guid   = o.guid,
        @cur_open_signal = o.signal
    FROM dbo.combined_trades_open AS o WITH (UPDLOCK, READPAST)
    WHERE o.product = @product
      AND o.trade_reason = @reason_tag
    ORDER BY o.created DESC;

    IF @cur_open_guid IS NOT NULL
    BEGIN
        IF @cur_open_signal = @new_signal
        BEGIN
            -- Same direction already open - no action
            SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                     + N' existing open with same signal (' + @cur_open_signal + N') - no action';
            RAISERROR(@msg, 10, 1) WITH NOWAIT;
            RETURN;
        END

        -- Opposite direction detected; close existing before opening new
        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                 + N' opposite detected: closing existing ' + @cur_open_signal + N' before opening ' + @new_signal;
        RAISERROR(@msg, 10, 1) WITH NOWAIT;

        DECLARE @rc INT;
        EXEC @rc = dbo.sp_003_CloseTradesTargetReached_refactored
            @product         = @product,
            @signal_to_close = @cur_open_signal,
            @trade_reason    = @reason_tag,
            @close_count     = 1,
            @guid_to_close = @cur_open_guid;

        IF (@rc IS NULL) SET @rc = 0;
        IF @rc <> 0
        BEGIN
            SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                     + N' sp_003_close failed (rc=' + CONVERT(NVARCHAR(12), @rc) + N') - skipping new ' + @new_signal;
            RAISERROR(@msg, 10, 1) WITH NOWAIT;
            RETURN;
        END

        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' close done ? proceed to open ' + @new_signal;
        RAISERROR(@msg, 10, 1) WITH NOWAIT;
    END
    /* ---- max open per trade_reason gate (still enforced) ---- */
    IF @max_open_limit IS NOT NULL AND @max_open_limit > 0
    BEGIN
        SELECT @open_active = COUNT(*)
        FROM dbo.combined_trades_open WITH (NOLOCK)
        WHERE product = @product
          AND trade_reason = @reason_tag;

        IF @open_active >= @max_open_limit
        BEGIN
            SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                     + N' cap reached after close-check ? exit (no inserts)';
            RAISERROR(@msg, 10, 1) WITH NOWAIT;
            RETURN;
        END
    END

    /* ---- build BUY/SELL candidates from last closed attrs (unchanged) ---- */
    IF OBJECT_ID('tempdb..#candidates') IS NOT NULL DROP TABLE #candidates;

    ;WITH last_closed AS (
        SELECT c.product, c.model, c.signal,
               c.product_type, c.target_profit, c.target_loss,
               c.rl_signal, c.RL_Check, c.buy_count, c.sell_count,
               c.linked, c.int_profit, c.int_profit_time,
               ROW_NUMBER() OVER (
                   PARTITION BY c.product, c.signal
                   ORDER BY c.created DESC
               ) AS rn
        FROM dbo.combined_trades_closed AS c WITH (NOLOCK)
        WHERE c.product = @product
    )
    SELECT
        NEWID() AS guid,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.model
                      WHEN s.signal='sell' THEN lc_sell.model END, N'100030') AS model,
        @product                              AS product,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.product_type
                      WHEN s.signal='sell' THEN lc_sell.product_type END, N'F')  AS product_type,
        s.signal                               AS signal,

        /* prices from live */
        CASE WHEN s.signal='buy' THEN @quote_ask ELSE @quote_bid END AS entry_price,
        CASE WHEN s.signal='buy' THEN @quote_ask ELSE @quote_bid END AS latest_price,

        CASE WHEN s.signal='buy' THEN @quote_bid ELSE @quote_ask END AS entry_price2,
        CASE WHEN s.signal='buy' THEN @quote_ask ELSE @quote_bid END AS latest_price2,

        @Commission                            AS commission,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.target_profit
                      WHEN s.signal='sell' THEN lc_sell.target_profit END, 50) AS target_profit,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.target_loss
                      WHEN s.signal='sell' THEN lc_sell.target_loss END, -200) AS target_loss,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.rl_signal
                      WHEN s.signal='sell' THEN lc_sell.rl_signal END, NULL)   AS rl_signal,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.RL_Check
                      WHEN s.signal='sell' THEN lc_sell.RL_Check END, 0)       AS RL_Check,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.buy_count
                      WHEN s.signal='sell' THEN lc_sell.buy_count END, 0)      AS buy_count,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.sell_count
                      WHEN s.signal='sell' THEN lc_sell.sell_count END, 0)     AS sell_count,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.linked
                      WHEN s.signal='sell' THEN lc_sell.linked END, 0)         AS linked,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.int_profit
                      WHEN s.signal='sell' THEN lc_sell.int_profit END, NULL)  AS int_profit,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.int_profit_time
                      WHEN s.signal='sell' THEN lc_sell.int_profit_time END, NULL) AS int_profit_time,
        @TradeQuantity                         AS trade_quantity
    INTO #candidates
    FROM (VALUES ('buy'), ('sell')) AS s(signal)
    LEFT JOIN last_closed lc_buy
      ON lc_buy.product = @product AND lc_buy.signal='buy'  AND lc_buy.rn=1
    LEFT JOIN last_closed lc_sell
      ON lc_sell.product = @product AND lc_sell.signal='sell' AND lc_sell.rn=1;

    /* ---- insert only the decided side ---- */
    DECLARE @inserted INT = 0;

    IF @new_signal = N'buy'
    BEGIN
        INSERT INTO dbo.combined_trades_open (
            guid, model, product, product_type, created, last_update, signal,
            entry_price, latest_price, entry_price2, latest_price2,
            commission, target_profit, target_loss, rl_signal, tradeable,
            net_return, alt_net_return, pos_net_return_buy, pos_net_return_sell,
            trade_diff, RL_Check, percent_profit, percent_loss,
            buy_count, sell_count, linked, int_profit, int_profit_time,
            trade_quantity, flip_trade, trade_reason
        )
        SELECT TOP (1)
            guid, model, product, product_type, @Now, @Now, N'buy',
            entry_price, latest_price, entry_price2, latest_price2,
            commission, target_profit, target_loss, rl_signal, @tradeable_flag,
            0, 0, 0, 0, 0, RL_Check, 0, 0,
            buy_count, sell_count, linked, int_profit, int_profit_time,
            trade_quantity, 1, @reason_tag
        FROM #candidates
        WHERE signal=N'buy';

        SET @inserted += @@ROWCOUNT;
    END
    ELSE IF @new_signal = N'sell'
    BEGIN
        INSERT INTO dbo.combined_trades_open (
            guid, model, product, product_type, created, last_update, signal,
            entry_price, latest_price, entry_price2, latest_price2,
            commission, target_profit, target_loss, rl_signal, tradeable,
            net_return, alt_net_return, pos_net_return_buy, pos_net_return_sell,
            trade_diff, RL_Check, percent_profit, percent_loss,
            buy_count, sell_count, linked, int_profit, int_profit_time,
            trade_quantity, flip_trade, trade_reason
        )
        SELECT TOP (1)
            guid, model, product, product_type, @Now, @Now, N'sell',
            entry_price, latest_price, entry_price2, latest_price2,
            commission, target_profit, target_loss, rl_signal, @tradeable_flag,
            0, 0, 0, 0, 0, RL_Check, 0, 0,
            buy_count, sell_count, linked, int_profit, int_profit_time,
            trade_quantity, 1, @reason_tag
        FROM #candidates
        WHERE signal=N'sell';

        SET @inserted += @@ROWCOUNT;
    END

    SET @msg = CONVERT(NVARCHAR(23), GETDATE(), 121) + N' ' + @tag
             + N' action=' + CASE 
                                WHEN @cur_open_guid IS NULL THEN N'OPEN'
                                WHEN @cur_open_signal = @new_signal THEN N'NOOP'
                                ELSE N'CLOSE?OPEN'
                              END
             + N' new_signal=' + @new_signal
             + N' inserted_rows=' + CONVERT(NVARCHAR(20), @inserted);
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    /* ---- end log ---- */
    SET @msg = CONVERT(NVARCHAR(23), GETDATE(), 121) + N' ' + @tag + N' done';
    RAISERROR(@msg, 10, 1) WITH NOWAIT;
END

CREATE PROCEDURE [dbo].[sp_001_copy_trade_as_tradeable_v702]
    @product        NVARCHAR(50)  = N'gbp',
    @TradeQuantity  BIGINT        = 100000,
    @Commission     DECIMAL(18,6) = 20
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    /* ==== locals ==== */
    DECLARE
        @Now             DATETIME2(3) = GETDATE(),
        @MaxAgeSec       INT          = 60,
        @quote_bid       DECIMAL(18,10),
        @quote_ask       DECIMAL(18,10),
        @quote_ts        DATETIME2(3),
        @ts              NVARCHAR(23),
        @skip_001_v702     INT = 0,
        @max_open_limit  INT,
        @open_active     INT;

    -- GEMINI: 2025-09-26 - Declare and call sim mode helper
    DECLARE @is_sim_mode BIT;
    EXEC dbo.sp_helper_is_sim_db @is_sim_mode = @is_sim_mode OUTPUT;

    DECLARE
        @tag        SYSNAME      = N'sp_001_v702',
        @msg        NVARCHAR(4000),
        @reason_tag NVARCHAR(64) = N'sp_001_v702';

    /* ---- start log ---- */
    SET @ts  = CONVERT(NVARCHAR(23), @Now, 121);
    SET @msg = @ts + N' ' + @tag + N' start product=' + @product
             + N' TradeQty=' + CONVERT(NVARCHAR(32), @TradeQuantity)
             + N' Commission=' + CONVERT(NVARCHAR(32), @Commission);
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    /* =========================
       Trading window (config)
       ========================= */
    DECLARE
        @cfg_trade_start NVARCHAR(64),
        @cfg_trade_end   NVARCHAR(64),
        @trade_start_dt  DATETIME2(0),
        @trade_end_dt    DATETIME2(0),
        @in_window       BIT = 1;

    SELECT @cfg_trade_start = config_value
    FROM dbo.config WHERE config_name = N'trade_start';

    SELECT @cfg_trade_end = config_value
    FROM dbo.config WHERE config_name = N'trade_end';

    SET @trade_start_dt =
        COALESCE(
            TRY_CONVERT(DATETIME2(0), @cfg_trade_start),
            TRY_CONVERT(DATETIME2(0), CONCAT(CONVERT(date, @Now), N' ', @cfg_trade_start))
        );

    SET @trade_end_dt =
        COALESCE(
            TRY_CONVERT(DATETIME2(0), @cfg_trade_end),
            TRY_CONVERT(DATETIME2(0), CONCAT(CONVERT(date, @Now), N' ', @cfg_trade_end))
        );

    IF @trade_start_dt IS NOT NULL AND @trade_end_dt IS NOT NULL
    BEGIN
        DECLARE @now_t   TIME(0) = CONVERT(TIME(0), @Now);
        DECLARE @start_t TIME(0) = CONVERT(TIME(0), @trade_start_dt);
        DECLARE @end_t   TIME(0) = CONVERT(TIME(0), @trade_end_dt);

        IF @start_t <= @end_t
            SET @in_window = IIF(@now_t >= @start_t AND @now_t < @end_t, 1, 0);
        ELSE
            SET @in_window = IIF(@now_t >= @start_t OR  @now_t < @end_t, 1, 0);
    END

    SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
             + N' trading_window start=' + COALESCE(CONVERT(NVARCHAR(19), @trade_start_dt, 120), N'(null)')
             + N' end=' + COALESCE(CONVERT(NVARCHAR(19), @trade_end_dt, 120), N'(null)')
             + N' in_window=' + CONVERT(NVARCHAR(1), @in_window);
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    IF @in_window = 0 AND @is_sim_mode = 0 -- GEMINI: 2025-09-26 - Bypass trading window in sim mode
    BEGIN
        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' outside trading window ? exit (no inserts)';
        RAISERROR(@msg, 10, 1) WITH NOWAIT;
        RETURN;
    END

    /* ---- config: skip_001_v702 / max_open_per_trade_reason ---- */
    SELECT @skip_001_v702 = TRY_CAST(config_value AS INT)
    FROM dbo.config WHERE config_name = N'skip_001_v702';
    IF @skip_001_v702 IS NULL SET @skip_001_v702 = 0;

    SELECT @max_open_limit = TRY_CAST(config_value AS INT)
    FROM dbo.config WHERE config_name = N'max_open_per_trade_reason';

    SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
             + N' config skip_001_v702=' + CONVERT(NVARCHAR(12), @skip_001_v702)
             + N' max_open_per_trade_reason=' + COALESCE(CONVERT(NVARCHAR(16), @max_open_limit), N'(null)');
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    IF @skip_001_v702 = 1
    BEGIN
        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' skip_001_v702=1 ? bypassed (no insert)';
        RAISERROR(@msg, 10, 1) WITH NOWAIT;
        RETURN;
    END

    /* ---- live quote (for entry/latest pricing) ---- */
    SELECT TOP (1)
        @quote_bid = TRY_CONVERT(DECIMAL(18,10), q.bid),
        @quote_ask = TRY_CONVERT(DECIMAL(18,10), q.ask),
        @quote_ts  = TRY_CONVERT(DATETIME2(3), q.[timestamp])
    FROM dbo.vw_000_fx_quotes AS q WITH (READPAST)
    WHERE UPPER(q.code) = UPPER(@product) AND q.[type] = 'F'
    ORDER BY q.[timestamp] DESC;

    IF (@quote_bid IS NULL OR @quote_ask IS NULL OR @quote_bid <= 0 OR @quote_ask <= 0 OR @quote_ask <= @quote_bid)
        THROW 50000, 'Invalid bid/ask for product (vw_000_fx_quotes).', 1;

    IF (@quote_ts IS NULL OR DATEDIFF(SECOND, @quote_ts, @Now) > @MaxAgeSec)
        THROW 50000, 'Stale quote for product (vw_000_fx_quotes).', 1;

 
 
        /* =========================================
       v702 TRADE CRITERIA (driven by view signal)
       Source: vw_123_zone_counts_with_prev (latest row)
       ========================================= */
    DECLARE

        @zc_ts         DATETIME2(3),
        @darkgreen_buy       INT,
        @prev_darkgreen_buy  INT,
        @darkgreen_sell      INT,
        @prev_darkgreen_sell INT,
        @new_signal    NVARCHAR(4) = NULL;  -- 'buy'/'sell'/NULL


    SELECT TOP (1)
        @zc_ts         = TRY_CONVERT(DATETIME2(3), last_update),
        @darkgreen_buy       = TRY_CAST(darkgreen_buy AS INT),
        @prev_darkgreen_buy  = TRY_CAST(prev_darkgreen_buy AS INT),
        @darkgreen_sell      = TRY_CAST(darkgreen_sell AS INT),
        @prev_darkgreen_sell = TRY_CAST(prev_darkgreen_sell AS INT)
    FROM dbo.vw_123_zone_counts_with_prev WITH (READPAST)
    WHERE UPPER(product) = UPPER(@product)
    ORDER BY last_update DESC;

    	IF ISNULL(@darkgreen_sell, 0) = 0 AND ISNULL(@darkgreen_buy, 0) > 0
            SET @new_signal = N'buy';
    
        IF ISNULL(@darkgreen_buy, 0) = 0 AND ISNULL(@darkgreen_sell, 0) > 0
            SET @new_signal = N'sell';
    SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
             + N' decision(new_signal)=' + COALESCE(@new_signal, N'NULL')
             + N' from counts prev_darkgreen_buy=' + COALESCE(CONVERT(NVARCHAR(12), @prev_darkgreen_buy), N'NULL')
             + N' darkgreen_buy=' + COALESCE(CONVERT(NVARCHAR(12), @darkgreen_buy), N'NULL')
             + N' prev_darkgreen_sell=' + COALESCE(CONVERT(NVARCHAR(12), @prev_darkgreen_sell), N'NULL')
             + N' darkgreen_sell=' + COALESCE(CONVERT(NVARCHAR(12), @darkgreen_sell), N'NULL')
             + N' last_update=' + COALESCE(CONVERT(NVARCHAR(23), @zc_ts, 121), N'(null)');
    RAISERROR(@msg, 10, 1) WITH NOWAIT;
	/* ---- If no actionable signal, exit ---- */
	IF @new_signal IS NULL
	BEGIN
		SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' HOLD/PAUSE/NULL ? exit (no inserts)';
		RAISERROR(@msg, 10, 1) WITH NOWAIT;
		RETURN;
	END
    /* === Profitability Check using Helper SP === */
    DECLARE @is_profitable BIT;
    DECLARE @tradeable_flag BIT = 0;
    -- GEMINI: 2025-09-29 - Add conditional skip for profitability check
    DECLARE @skip_profit_check_config NVARCHAR(MAX);
    DECLARE @skip_profit_check_for_this_sp BIT = 0;

    SELECT @skip_profit_check_config = config_value
    FROM dbo.config WHERE config_name = N'skip_profit_check';

    -- GEMINI: 2025-09-30 - Debug log for profitability skip check
    SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
             + N' Debug: @reason_tag=' + COALESCE(@reason_tag, N'NULL')
             + N', @skip_profit_check_config=' + COALESCE(@skip_profit_check_config, N'NULL')
             + N', CHARINDEX=' + CONVERT(NVARCHAR(12), CHARINDEX(@reason_tag, @skip_profit_check_config));
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    IF @skip_profit_check_config IS NOT NULL AND CHARINDEX(@reason_tag, @skip_profit_check_config) > 0
    BEGIN
        SET @skip_profit_check_for_this_sp = 1;
        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' profitability check skipped for ' + @reason_tag + N' as per config.';
        RAISERROR(@msg, 10, 1) WITH NOWAIT;
    END

    IF @skip_profit_check_for_this_sp = 0
    BEGIN
        EXEC dbo.sp_helper_check_alt_net_return
            @product       = @product,
            @trade_reason  = @reason_tag,
            @signal        = @new_signal,
            @is_profitable = @is_profitable OUTPUT;

        IF ISNULL(@is_profitable, 0) = 1
        BEGIN
            SET @tradeable_flag = 1;
        END
        ELSE
        BEGIN
            SET @tradeable_flag = 0;
            SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                     + N' profitability check failed for signal=' + @new_signal + N' - flagging tradeable=0';
            RAISERROR(@msg, 10, 1) WITH NOWAIT;
        END
    END
    ELSE
    BEGIN
        -- If skipped, assume profitable for tradeable_flag
        SET @tradeable_flag = 1;
    END
/* ---- Find existing open trade for same reason ---- */
    DECLARE
        @cur_open_guid UNIQUEIDENTIFIER,
        @cur_open_signal NVARCHAR(4);

    SELECT TOP (1)
        @cur_open_guid   = o.guid,
        @cur_open_signal = o.signal
    FROM dbo.combined_trades_open AS o WITH (UPDLOCK, READPAST)
    WHERE o.product = @product
      AND o.trade_reason = @reason_tag
    ORDER BY o.created DESC;

    IF @cur_open_guid IS NOT NULL
    BEGIN
        IF @cur_open_signal = @new_signal
        BEGIN
            -- Same direction already open - no action
            SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                     + N' existing open with same signal (' + @cur_open_signal + N') - no action';
            RAISERROR(@msg, 10, 1) WITH NOWAIT;
            RETURN;
        END

        -- Opposite direction detected; close existing before opening new
        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                 + N' opposite detected: closing existing ' + @cur_open_signal + N' before opening ' + @new_signal;
        RAISERROR(@msg, 10, 1) WITH NOWAIT;

        DECLARE @rc INT;
        EXEC @rc = dbo.sp_003_CloseTradesTargetReached_refactored
            @product         = @product,
            @signal_to_close = @cur_open_signal,
            @trade_reason    = @reason_tag,
            @close_count     = 1,
            @guid_to_close = @cur_open_guid;

        IF (@rc IS NULL) SET @rc = 0;
        IF @rc <> 0
        BEGIN
            SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                     + N' sp_003_close failed (rc=' + CONVERT(NVARCHAR(12), @rc) + N') - skipping new ' + @new_signal;
            RAISERROR(@msg, 10, 1) WITH NOWAIT;
            RETURN;
        END

        SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag + N' close done ? proceed to open ' + @new_signal;
        RAISERROR(@msg, 10, 1) WITH NOWAIT;
    END
    /* ---- max open per trade_reason gate (still enforced) ---- */
    IF @max_open_limit IS NOT NULL AND @max_open_limit > 0
    BEGIN
        SELECT @open_active = COUNT(*)
        FROM dbo.combined_trades_open WITH (NOLOCK)
        WHERE product = @product
          AND trade_reason = @reason_tag;

        IF @open_active >= @max_open_limit
        BEGIN
            SET @msg = CONVERT(NVARCHAR(23), @Now, 121) + N' ' + @tag
                     + N' cap reached after close-check ? exit (no inserts)';
            RAISERROR(@msg, 10, 1) WITH NOWAIT;
            RETURN;
        END
    END

    /* ---- build BUY/SELL candidates from last closed attrs (unchanged) ---- */
    IF OBJECT_ID('tempdb..#candidates') IS NOT NULL DROP TABLE #candidates;

    ;WITH last_closed AS (
        SELECT c.product, c.model, c.signal,
               c.product_type, c.target_profit, c.target_loss,
               c.rl_signal, c.RL_Check, c.buy_count, c.sell_count,
               c.linked, c.int_profit, c.int_profit_time,
               ROW_NUMBER() OVER (
                   PARTITION BY c.product, c.signal
                   ORDER BY c.created DESC
               ) AS rn
        FROM dbo.combined_trades_closed AS c WITH (NOLOCK)
        WHERE c.product = @product
    )
    SELECT
        NEWID() AS guid,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.model
                      WHEN s.signal='sell' THEN lc_sell.model END, N'100030') AS model,
        @product                              AS product,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.product_type
                      WHEN s.signal='sell' THEN lc_sell.product_type END, N'F')  AS product_type,
        s.signal                               AS signal,

        /* prices from live */
        CASE WHEN s.signal='buy' THEN @quote_ask ELSE @quote_bid END AS entry_price,
        CASE WHEN s.signal='buy' THEN @quote_ask ELSE @quote_bid END AS latest_price,

        CASE WHEN s.signal='buy' THEN @quote_bid ELSE @quote_ask END AS entry_price2,
        CASE WHEN s.signal='buy' THEN @quote_ask ELSE @quote_bid END AS latest_price2,

        @Commission                            AS commission,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.target_profit
                      WHEN s.signal='sell' THEN lc_sell.target_profit END, 50) AS target_profit,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.target_loss
                      WHEN s.signal='sell' THEN lc_sell.target_loss END, -200) AS target_loss,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.rl_signal
                      WHEN s.signal='sell' THEN lc_sell.rl_signal END, NULL)   AS rl_signal,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.RL_Check
                      WHEN s.signal='sell' THEN lc_sell.RL_Check END, 0)       AS RL_Check,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.buy_count
                      WHEN s.signal='sell' THEN lc_sell.buy_count END, 0)      AS buy_count,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.sell_count
                      WHEN s.signal='sell' THEN lc_sell.sell_count END, 0)     AS sell_count,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.linked
                      WHEN s.signal='sell' THEN lc_sell.linked END, 0)         AS linked,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.int_profit
                      WHEN s.signal='sell' THEN lc_sell.int_profit END, NULL)  AS int_profit,
        COALESCE(CASE WHEN s.signal='buy'  THEN lc_buy.int_profit_time
                      WHEN s.signal='sell' THEN lc_sell.int_profit_time END, NULL) AS int_profit_time,
        @TradeQuantity                         AS trade_quantity
    INTO #candidates
    FROM (VALUES ('buy'), ('sell')) AS s(signal)
    LEFT JOIN last_closed lc_buy
      ON lc_buy.product = @product AND lc_buy.signal='buy'  AND lc_buy.rn=1
    LEFT JOIN last_closed lc_sell
      ON lc_sell.product = @product AND lc_sell.signal='sell' AND lc_sell.rn=1;

    /* ---- insert only the decided side ---- */
    DECLARE @inserted INT = 0,
			@target_profit int=50,
			@target_loss   int=-200;

    IF @new_signal = N'buy'
    BEGIN
        INSERT INTO dbo.combined_trades_open (
            guid, model, product, product_type, created, last_update, signal,
            entry_price, latest_price, entry_price2, latest_price2,
            commission, target_profit, target_loss, rl_signal, tradeable,
            net_return, alt_net_return, pos_net_return_buy, pos_net_return_sell,
            trade_diff, RL_Check, percent_profit, percent_loss,
            buy_count, sell_count, linked, int_profit, int_profit_time,
            trade_quantity, flip_trade, trade_reason
        )
        SELECT TOP (1)
            guid, model, product, product_type, @Now, @Now, N'buy',
            entry_price, latest_price, entry_price2, latest_price2,
            commission, target_profit, target_loss, rl_signal, @tradeable_flag,
            0, 0, 0, 0, 0, RL_Check, 0, 0,
            buy_count, sell_count, linked, int_profit, int_profit_time,
            trade_quantity, 0, @reason_tag
        FROM #candidates
        WHERE signal=N'buy';

        SET @inserted += @@ROWCOUNT;
    END
    ELSE IF @new_signal = N'sell'
    BEGIN
        INSERT INTO dbo.combined_trades_open (
            guid, model, product, product_type, created, last_update, signal,
            entry_price, latest_price, entry_price2, latest_price2,
            commission, target_profit, target_loss, rl_signal, tradeable,
            net_return, alt_net_return, pos_net_return_buy, pos_net_return_sell,
            trade_diff, RL_Check, percent_profit, percent_loss,
            buy_count, sell_count, linked, int_profit, int_profit_time,
            trade_quantity, flip_trade, trade_reason
        )
        SELECT TOP (1)
            guid, model, product, product_type, @Now, @Now, N'sell',
            entry_price, latest_price, entry_price2, latest_price2,
            commission, @target_profit, @target_loss, rl_signal, @tradeable_flag,
            0, 0, 0, 0, 0, RL_Check, 0, 0,
            buy_count, sell_count, linked, int_profit, int_profit_time,
            trade_quantity, 0, @reason_tag   ----flip_trade set to 0
        FROM #candidates
        WHERE signal=N'sell';

        SET @inserted += @@ROWCOUNT;
    END

    SET @msg = CONVERT(NVARCHAR(23), GETDATE(), 121) + N' ' + @tag
             + N' action=' + CASE 
                                WHEN @cur_open_guid IS NULL THEN N'OPEN'
                                WHEN @cur_open_signal = @new_signal THEN N'NOOP'
                                ELSE N'CLOSE?OPEN'
                              END
             + N' new_signal=' + @new_signal
             + N' inserted_rows=' + CONVERT(NVARCHAR(20), @inserted);
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    /* ---- end log ---- */
    SET @msg = CONVERT(NVARCHAR(23), GETDATE(), 121) + N' ' + @tag + N' done';
    RAISERROR(@msg, 10, 1) WITH NOWAIT;
END

