END

CREATE   PROCEDURE dbo.sp_600_AutoNewTrade_OnNewClosed
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRAN;

        -- ensure single state row exists (only known cols)
        IF NOT EXISTS (SELECT 1 FROM dbo._auto_newtrade_on_close_state WITH (UPDLOCK, HOLDLOCK) WHERE id=1)
        BEGIN
            INSERT INTO dbo._auto_newtrade_on_close_state (id, last_processed_close, prev_recent_signal)
            VALUES (1, NULL, NULL);
        END

        DECLARE @lastProcessed DATETIME2(3), @prevSignal NVARCHAR(10);
        SELECT @lastProcessed = last_processed_close,
               @prevSignal    = prev_recent_signal
        FROM dbo._auto_newtrade_on_close_state WITH (UPDLOCK, HOLDLOCK)
        WHERE id = 1;

        -- step 1: newly closed trades since watermark
        DROP TABLE IF EXISTS #NewClosed;
        SELECT c.guid, c.model, c.product, c.signal, c.created, c.last_update
        INTO #NewClosed
        FROM dbo.combined_trades_closed AS c WITH (READPAST)
        WHERE (@lastProcessed IS NULL OR c.last_update > @lastProcessed);

        IF NOT EXISTS (SELECT 1 FROM #NewClosed)
        BEGIN
            COMMIT TRAN;
            RETURN;
        END

        DECLARE @recentSignal NVARCHAR(10), @recentModel NVARCHAR(50), @recentLU DATETIME2(3);
        SELECT TOP (1)
               @recentSignal = signal,
               @recentModel  = model,
               @recentLU     = last_update
        FROM #NewClosed
        ORDER BY last_update DESC, created DESC, guid DESC;

        DECLARE @distinctSignals INT;
        SELECT @distinctSignals = COUNT(DISTINCT signal) FROM #NewClosed;

        -- step 2: decision
        DECLARE @doOpen BIT = 0;
        IF @distinctSignals > 1
            SET @doOpen = 1;
        ELSE IF @distinctSignals = 1 AND (ISNULL(@prevSignal,'') <> ISNULL(@recentSignal,''))
            SET @doOpen = 1;
        ELSE
            SET @doOpen = 0;

        IF @doOpen = 1
        BEGIN
            -- seed an OPEN for model+signal if none exists so sp_001_copy can work
            IF NOT EXISTS (
                SELECT 1
                FROM dbo.vwCombined_trades_open o
                WHERE o.model=@recentModel AND LOWER(o.signal)=LOWER(@recentSignal)
            )
            BEGIN
                DECLARE @seedGuid UNIQUEIDENTIFIER = NEWID();
                ;WITH src AS (
                    SELECT TOP (1) *
                    FROM dbo.vwCombined_trades_closed
                    WHERE model=@recentModel AND LOWER(signal)=LOWER(@recentSignal)
                    ORDER BY last_update DESC, created DESC, guid DESC
                )
                INSERT INTO dbo.combined_trades_open (
                    guid, model, product, product_type, created, last_update, signal,
                    entry_price, latest_price, entry_price2, latest_price2,
                    commission, target_profit, target_loss, rl_signal, tradeable,
                    net_return, alt_net_return, pos_net_return_buy, pos_net_return_sell,
                    trade_diff, RL_Check, percent_profit, percent_loss, buy_count, sell_count,
                    linked, int_profit, int_profit_time, trade_quantity
                )
                SELECT
                    @seedGuid, s.model, s.product, s.product_type,
                    GETDATE(), GETDATE(), @recentSignal,
                    TRY_CONVERT(FLOAT, s.latest_price),
                    TRY_CONVERT(FLOAT, s.latest_price2),
                    TRY_CONVERT(FLOAT, s.entry_price2),
                    TRY_CONVERT(FLOAT, s.latest_price2),
                    TRY_CONVERT(FLOAT, s.commission),
                    TRY_CONVERT(FLOAT, s.target_profit),
                    TRY_CONVERT(FLOAT, s.target_loss),
                    s.rl_signal,
                    0,  -- seed not tradeable
                    0,0,0,0,0,
                    s.RL_Check,
                    0,0,
                    TRY_CONVERT(FLOAT, s.buy_count),
                    TRY_CONVERT(FLOAT, s.sell_count),
                    s.linked,
                    TRY_CONVERT(FLOAT, s.int_profit),
                    s.int_profit_time,
                    s.trade_quantity
                FROM src s;
            END

            -- call copy SP and capture guid (it returns a result set)
            DECLARE @t TABLE (NewGuid UNIQUEIDENTIFIER);
            INSERT INTO @t
            EXEC dbo.sp_001_copy_trade_as_tradeable
                 @model        = @recentModel,
                 @signal       = @recentSignal,
                 @trade_reason = N'auto_from_new_close';

            DECLARE @newGuid UNIQUEIDENTIFIER = (SELECT TOP (1) NewGuid FROM @t);

            -- if guarded out, force-pick newest open and set tradeable=1
            IF @newGuid IS NULL
            BEGIN
                SELECT TOP (1) @newGuid = o.guid
                FROM dbo.vwCombined_trades_open o
                WHERE o.model=@recentModel AND LOWER(o.signal)=LOWER(@recentSignal)
                ORDER BY o.created DESC, o.guid DESC;
            END

            IF @newGuid IS NOT NULL
            BEGIN
                UPDATE o
                   SET o.tradeable = 1
                FROM dbo.combined_trades_open o
                WHERE o.guid = @newGuid;
            END

            -- step 3: close previous signal using existing close SP
            EXEC dbo.sp_003_CloseTradesTargetReached_refactored;
        END

        -- advance watermark & remember latest signal
        DECLARE @maxClosed DATETIME2(3);
        SELECT @maxClosed = MAX(last_update) FROM #NewClosed;

        UPDATE s
           SET s.last_processed_close = @maxClosed,
               s.prev_recent_signal   = @recentSignal
        FROM dbo._auto_newtrade_on_close_state s
        WHERE s.id = 1;

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRAN;
        THROW;
    END CATCH
END

CREATE PROCEDURE [dbo].[sp_700_decide_open]
    @guid                UNIQUEIDENTIFIER,
    @product             NVARCHAR(50),
    @signal              NVARCHAR(10),
    @created             DATETIME2(3),
    @entry_price         DECIMAL(18,10),

    -- thresholds
    @count_min           INT            = 5,
    @hit_min             DECIMAL(9,6)   = 0.52,
    @alt_mean_min        DECIMAL(19,4)  = 0.0,     -- kept for backward-compat (not used now)

    -- risk gates
    @max_open            INT            = 3,
    @kill_level          DECIMAL(19,4)  = -750.0,
    @max_per_product     INT            = 1,

    -- optional session (NULL => no session dimension)
    @session             SMALLINT       = NULL,

    -- decision outputs
    @accept              BIT            OUTPUT,
    @reason              NVARCHAR(32)   OUTPUT,
    @entry_bucket        INT            OUTPUT,
    @time_bin            INT            OUTPUT,
    @accept_return_type  NVARCHAR(20)   OUTPUT,  -- 'net_return' | 'alt_net_return'
    @flip_trade          BIT            OUTPUT   -- 0 = net focus, 1 = alt focus
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    /* [0] Initialize keys */
    DECLARE @eb INT = dbo.fn_700_choose_bucket(@product, @entry_price);
    DECLARE @tb INT = dbo.fn_700_time_bin(@created);
    IF @eb IS NULL SET @eb = 0;
    IF @tb IS NULL SET @tb = 0;

    SET @entry_bucket = @eb;
    SET @time_bin     = @tb;

    DECLARE @today   DATE     = CONVERT(date, GETDATE());
    DECLARE @sesskey SMALLINT = CONVERT(SMALLINT, ISNULL(@session, -1));

    /* helpers */
    DECLARE @ts  VARCHAR(23);
    DECLARE @msg NVARCHAR(4000);

    /* [1] Inputs */
    SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
    SET @msg = CONCAT(
        @ts, N' sp_700 [1:inputs] ',
        N'guid=', CONVERT(varchar(36), @guid),
        N' prod=', @product,
        N' sig=', @signal,
        N' eb=', CONVERT(varchar(12), @eb),
        N' tb=', CONVERT(varchar(12), @tb),
        N' thresholds{count_min=', CONVERT(varchar(20), @count_min),
        N', hit_min=', CONVERT(varchar(32), @hit_min), N'} ',
        N'risk{max_open=', CONVERT(varchar(12), @max_open),
        N', max_per_product=', CONVERT(varchar(12), @max_per_product),
        N', kill=', CONVERT(varchar(32), @kill_level), N'}'
    );
    RAISERROR(@msg, 0, 1) WITH NOWAIT;

    /* (Removed old [2:config] skip_700 block) */

    /* [3] Bucket/timebin validity */
    IF @entry_bucket = 0 OR @time_bin = 0
    BEGIN
        SET @accept = 0; SET @reason = N'700_bucket_or_timebin_null';
        SET @accept_return_type = NULL; SET @flip_trade = NULL;

        SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
        SET @msg = CONCAT(@ts, N' sp_700 [3:bucket] FAIL: eb/tb invalid eb=', CONVERT(varchar(12),@eb),
                          N' tb=', CONVERT(varchar(12),@tb));
        RAISERROR(@msg, 0, 1) WITH NOWAIT;

        IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
        MERGE dbo.sp_700_gate_outbox AS t
        USING (SELECT @guid AS guid) s ON t.guid = s.guid
        WHEN MATCHED     THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                         entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
        WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                                  VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
        RETURN;
    END;
    SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
    SET @msg = CONCAT(@ts, N' sp_700 [3:bucket] PASS eb=', CONVERT(varchar(12),@eb),
                      N' tb=', CONVERT(varchar(12),@tb));
    RAISERROR(@msg, 0, 1) WITH NOWAIT;

    /* ========================================================================
       [4] PRIORS (STRICT per return_type)
       ======================================================================== */
    DECLARE
        @cnt_net   INT            = 0,
        @wins_net  DECIMAL(19,4)  = 0,
        @sum_net   DECIMAL(19,4)  = 0,
        @hit_net   DECIMAL(19,6)  = 0,

        @cnt_alt   INT            = 0,
        @wins_alt  DECIMAL(19,4)  = 0,
        @sum_alt   DECIMAL(19,4)  = 0,
        @hit_alt   DECIMAL(19,6)  = 0;

    ;
    WITH pri AS (
        SELECT p.return_type, p.prior_count, p.prior_win_sum, p.prior_alt_sum
        FROM dbo.tbl_700_priors AS p
        WHERE p.product      = @product
          AND p.signal       = @signal
          AND p.entry_bucket = @eb
          AND p.time_bin     = @tb
          AND p.session_key  = @sesskey
    )
    SELECT
        @cnt_net  = ISNULL(SUM(CASE WHEN return_type = N'net_return'     THEN prior_count   ELSE 0 END), 0),
        @wins_net = ISNULL(SUM(CASE WHEN return_type = N'net_return'     THEN prior_win_sum ELSE 0 END), 0),
        @sum_net  = ISNULL(SUM(CASE WHEN return_type = N'net_return'     THEN prior_win_sum ELSE 0 END), 0),

        @cnt_alt  = ISNULL(SUM(CASE WHEN return_type = N'alt_net_return' THEN prior_count   ELSE 0 END), 0),
        @wins_alt = ISNULL(SUM(CASE WHEN return_type = N'alt_net_return' THEN prior_alt_sum ELSE 0 END), 0),
        @sum_alt  = ISNULL(SUM(CASE WHEN return_type = N'alt_net_return' THEN prior_alt_sum ELSE 0 END), 0)
    FROM pri;

    SET @hit_net = CASE WHEN @cnt_net > 0 THEN CAST(@wins_net AS DECIMAL(19,6)) / NULLIF(@cnt_net,0) ELSE 0 END;
    SET @hit_alt = CASE WHEN @cnt_alt > 0 THEN CAST(@wins_alt AS DECIMAL(19,6)) / NULLIF(@cnt_alt,0) ELSE 0 END;

    SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
    SET @msg = CONCAT(
        @ts, N' sp_700 [4:priors] ',
        N'NET{cnt=', CONVERT(varchar(20),@cnt_net),
        N', wins=', CONVERT(varchar(32),@wins_net),
        N', hit=', CONVERT(varchar(32),@hit_net),
        N', sum=', CONVERT(varchar(32),@sum_net), N'} ',
        N'ALT{cnt=', CONVERT(varchar(20),@cnt_alt),
        N', wins=', CONVERT(varchar(32),@wins_alt),
        N', hit=', CONVERT(varchar(32),@hit_alt),
        N', sum=', CONVERT(varchar(32),@sum_alt), N'}'
    );
    RAISERROR(@msg, 0, 1) WITH NOWAIT;

    /* [5] Per-side gates (cnt/hit/sum) */
    DECLARE @cnt_ok_net bit = CASE WHEN @cnt_net >= @count_min THEN 1 ELSE 0 END;
    DECLARE @hit_ok_net bit = CASE WHEN @hit_net >= @hit_min   THEN 1 ELSE 0 END;
    DECLARE @sum_ok_net bit = CASE WHEN @sum_net > 0           THEN 1 ELSE 0 END;

    DECLARE @cnt_ok_alt bit = CASE WHEN @cnt_alt >= @count_min THEN 1 ELSE 0 END;
    DECLARE @hit_ok_alt bit = CASE WHEN @hit_alt >= @hit_min   THEN 1 ELSE 0 END;
    DECLARE @sum_ok_alt bit = CASE WHEN @sum_alt > 0           THEN 1 ELSE 0 END;

    DECLARE @pass_net bit = CASE WHEN @cnt_ok_net=1 AND @hit_ok_net=1 AND @sum_ok_net=1 THEN 1 ELSE 0 END;
    DECLARE @pass_alt bit = CASE WHEN @cnt_ok_alt=1 AND @hit_ok_alt=1 AND @sum_ok_alt=1 THEN 1 ELSE 0 END;

    SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
    SET @msg = CONCAT(
        @ts, N' sp_700 [5:gates] ',
        N'NET{pass=', CONVERT(varchar(6),@pass_net),
        N', cnt_ok=', CONVERT(varchar(6),@cnt_ok_net),
        N', hit_ok=', CONVERT(varchar(6),@hit_ok_net),
        N', sum_ok=', CONVERT(varchar(6),@sum_ok_net), N'} ',
        N'ALT{pass=', CONVERT(varchar(6),@pass_alt),
        N', cnt_ok=', CONVERT(varchar(6),@cnt_ok_alt),
        N', hit_ok=', CONVERT(varchar(6),@hit_ok_alt),
        N', sum_ok=', CONVERT(varchar(6),@sum_ok_alt), N'}'
    );
    RAISERROR(@msg, 0, 1) WITH NOWAIT;

    SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
    SET @msg = CONCAT(
        @ts, N' sp_700 [5:why] NET: ',
        N'cnt_ok=', CASE WHEN @cnt_ok_net=1 THEN N'Y' ELSE N'N' END,
        N' (cnt=', CONVERT(varchar(32),@cnt_net),
        N' req>=', CONVERT(varchar(32),@count_min), N'); ',
        N'hit_ok=', CASE WHEN @hit_ok_net=1 THEN N'Y' ELSE N'N' END,
        N' (hit=', CONVERT(varchar(32),@hit_net),
        N' req>=', CONVERT(varchar(32),@hit_min), N'); ',
        N'sum_ok=', CASE WHEN @sum_ok_net=1 THEN N'Y' ELSE N'N' END,
        N' (sum=', CONVERT(varchar(32),@sum_net), N' > 0)'
    );
    RAISERROR(@msg, 0, 1) WITH NOWAIT;

    SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
    SET @msg = CONCAT(
        @ts, N' sp_700 [5:why] ALT: ',
        N'cnt_ok=', CASE WHEN @cnt_ok_alt=1 THEN N'Y' ELSE N'N' END,
        N' (cnt=', CONVERT(varchar(32),@cnt_alt),
        N' req>=', CONVERT(varchar(32),@count_min), N'); ',
        N'hit_ok=', CASE WHEN @hit_ok_alt=1 THEN N'Y' ELSE N'N' END,
        N' (hit=', CONVERT(varchar(32),@hit_alt),
        N' req>=', CONVERT(varchar(32),@hit_min), N'); ',
        N'sum_ok=', CASE WHEN @sum_ok_alt=1 THEN N'Y' ELSE N'N' END,
        N' (sum=', CONVERT(varchar(32),@sum_alt), N' > 0)'
    );
    RAISERROR(@msg, 0, 1) WITH NOWAIT;

    /* [6] Decide side */
    IF @pass_net = 1 AND @pass_alt = 0
    BEGIN
        SET @accept = 1; SET @reason = N'accept_net';
        SET @accept_return_type = N'net_return'; SET @flip_trade = 0;

        SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
        SET @msg = CONCAT(@ts, N' sp_700 [6:decide] ACCEPT net_return (cnt=', CONVERT(varchar(32),@cnt_net),
                        N', hit=', CONVERT(varchar(32),@hit_net),
                        N', sum=', CONVERT(varchar(32),@sum_net), N')');
        RAISERROR(@msg, 0, 1) WITH NOWAIT;
    END
    ELSE IF @pass_alt = 1 AND @pass_net = 0
    BEGIN
        SET @accept = 1; SET @reason = N'accept_alt';
        SET @accept_return_type = N'alt_net_return'; SET @flip_trade = 1;

        SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
        SET @msg = CONCAT(@ts, N' sp_700 [6:decide] ACCEPT alt_net_return (cnt=', CONVERT(varchar(32),@cnt_alt),
                        N', hit=', CONVERT(varchar(32),@hit_alt),
                        N', sum=', CONVERT(varchar(32),@sum_alt), N')');
        RAISERROR(@msg, 0, 1) WITH NOWAIT;
    END
    ELSE IF @pass_net = 0 AND @pass_alt = 0
    BEGIN
        SET @accept = 0;
        SET @reason = N'no_side_meets_thresholds';
        SET @accept_return_type = NULL; SET @flip_trade = NULL;

        SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
        SET @msg = CONCAT(
            @ts, N' sp_700 [6:decide] FAIL: no_side_meets_thresholds ',
            N'NET{cnt=', CONVERT(varchar(32),@cnt_net),
            N', hit=', CONVERT(varchar(32),@hit_net),
            N', sum=', CONVERT(varchar(32),@sum_net), N'} ',
            N'ALT{cnt=', CONVERT(varchar(32),@cnt_alt),
            N', hit=', CONVERT(varchar(32),@hit_alt),
            N', sum=', CONVERT(varchar(32),@sum_alt), N'}'
        );
        RAISERROR(@msg, 0, 1) WITH NOWAIT;

        IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
        MERGE dbo.sp_700_gate_outbox AS t
        USING (SELECT @guid AS guid) s ON t.guid = s.guid
        WHEN MATCHED     THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                         entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
        WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                                  VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
        RETURN;
    END
    ELSE /* both pass */
    BEGIN
        SET @accept = 0;
        SET @reason = N'ambiguous_both_sides_positive';
        SET @accept_return_type = NULL; SET @flip_trade = NULL;

        SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
        SET @msg = CONCAT(
            @ts, N' sp_700 [6:decide] FAIL: ambiguous_both_sides_positive ',
            N'NET(hit=', CONVERT(varchar(32),@hit_net),
            N', sum=', CONVERT(varchar(32),@sum_net), N') ',
            N'ALT(hit=', CONVERT(varchar(32),@hit_alt),
            N', sum=', CONVERT(varchar(32),@sum_alt), N')'
        );
        RAISERROR(@msg, 0, 1) WITH NOWAIT;

        IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
        MERGE dbo.sp_700_gate_outbox AS t
        USING (SELECT @guid AS guid) s ON t.guid = s.guid
        WHEN MATCHED     THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                         entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
        WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                                  VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
        RETURN;
    END;

    /* ========================================================================
       [7] RISK GATES (serialize, caps, kill switch)
       ======================================================================== */
    SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
    BEGIN TRY
        BEGIN TRAN;

        /* [7.0] applock */
        DECLARE @lockname sysname = N'sp700:' + LOWER(@product) + N':' + ISNULL(CONVERT(nvarchar(10), @sesskey), N'-1');
        DECLARE @lockres int;
        EXEC @lockres = sp_getapplock
            @Resource = @lockname,
            @LockMode = 'Exclusive',
            @LockOwner = 'Transaction',
            @LockTimeout = 0;

        IF @lockres < 0
        BEGIN
            ROLLBACK; SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
            SET @accept = 0; SET @reason = N'lock_conflict';
            SET @accept_return_type = NULL; SET @flip_trade = NULL;

            SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
            SET @msg = CONCAT(@ts, N' sp_700 [7.0:risk-lock] FAIL: lock_conflict res=',
                              CONVERT(varchar(12),@lockres));
            RAISERROR(@msg, 0, 1) WITH NOWAIT;

            IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
            MERGE dbo.sp_700_gate_outbox AS t
            USING (SELECT @guid AS guid) s ON t.guid = s.guid
            WHEN MATCHED     THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                             entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
            WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                                      VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
            RETURN;
        END;

        SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
        SET @msg = CONCAT(@ts, N' sp_700 [7.0:risk-lock] PASS res=',
                          CONVERT(varchar(12),@lockres), N' name=', @lockname);
        RAISERROR(@msg, 0, 1) WITH NOWAIT;

        /* [7.1] ensure & read today risk state */
        MERGE dbo.tbl_700_risk_state WITH (HOLDLOCK) AS t
        USING (SELECT @today AS trade_date) AS s
        ON t.trade_date = s.trade_date
        WHEN NOT MATCHED THEN
            INSERT (trade_date, open_positions, realized_pnl) VALUES (s.trade_date, 0, 0);

        DECLARE @open INT, @realized DECIMAL(19,4);
        SELECT @open = open_positions, @realized = realized_pnl
        FROM dbo.tbl_700_risk_state WITH (UPDLOCK, HOLDLOCK)
        WHERE trade_date = @today;

        SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
        SET @msg = CONCAT(@ts, N' sp_700 [7.1:risk-state] open_today=',
                          CONVERT(varchar(12),@open), N' realized=', CONVERT(varchar(32),@realized));
        RAISERROR(@msg, 0, 1) WITH NOWAIT;

        /* [7.2] kill switch */
        IF @realized <= @kill_level
        BEGIN
            ROLLBACK; SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
            SET @accept = 0; SET @reason = N'kill_switch';
            SET @accept_return_type = NULL; SET @flip_trade = NULL;

            SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
            SET @msg = CONCAT(@ts, N' sp_700 [7.2:kill] FAIL realized=',
                              CONVERT(varchar(32),@realized), N' <= kill=',
                              CONVERT(varchar(32),@kill_level));
            RAISERROR(@msg, 0, 1) WITH NOWAIT;

            IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
            MERGE dbo.sp_700_gate_outbox AS t
            USING (SELECT @guid AS guid) s ON t.guid = s.guid
            WHEN MATCHED     THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                             entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
            WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                                      VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
            RETURN;
        END;
        SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
        SET @msg = N'' + @ts + N' sp_700 [7.2:kill] PASS';
        RAISERROR(@msg, 0, 1) WITH NOWAIT;

        /* [7.3] per-product cap */
        DECLARE @open_prod INT;
        SELECT @open_prod = COUNT(*)
        FROM dbo.tbl_700_open_trades_log WITH (UPDLOCK, HOLDLOCK)
        WHERE product = @product
          AND decision = 'accepted'
          AND (@session IS NULL OR session = @session);

        SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
        SET @msg = CONCAT(@ts, N' sp_700 [7.3:cap-product] open_prod=',
                          CONVERT(varchar(12),@open_prod), N' max=',
                          CONVERT(varchar(12),@max_per_product));
        RAISERROR(@msg, 0, 1) WITH NOWAIT;

        IF @open_prod >= @max_per_product
        BEGIN
            ROLLBACK; SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
            SET @accept = 0; SET @reason = N'no_product_slot';
            SET @accept_return_type = NULL; SET @flip_trade = NULL;

            SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
            SET @msg = N'' + @ts + N' sp_700 [7.3:cap-product] FAIL: no_product_slot';
            RAISERROR(@msg, 0, 1) WITH NOWAIT;

            IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
            MERGE dbo.sp_700_gate_outbox AS t
            USING (SELECT @guid AS guid) s ON t.guid = s.guid
            WHEN MATCHED     THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                             entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
            WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                                      VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
            RETURN;
        END;
        SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
        SET @msg = N'' + @ts + N' sp_700 [7.3:cap-product] PASS';
        RAISERROR(@msg, 0, 1) WITH NOWAIT;

        /* [7.4] global slots */
        IF @open >= @max_open
        BEGIN
            ROLLBACK; SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
            SET @accept = 0; SET @reason = N'no_global_slots';
            SET @accept_return_type = NULL; SET @flip_trade = NULL;

            SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
            SET @msg = CONCAT(@ts, N' sp_700 [7.4:cap-global] FAIL: open=',
                              CONVERT(varchar(12),@open), N' max=',
                              CONVERT(varchar(12),@max_open));
            RAISERROR(@msg, 0, 1) WITH NOWAIT;

            IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
            MERGE dbo.sp_700_gate_outbox AS t
            USING (SELECT @guid AS guid) s ON t.guid = s.guid
            WHEN MATCHED     THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                             entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
            WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                                      VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
            RETURN;
        END;
        SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
        SET @msg = N'' + @ts + N' sp_700 [7.4:cap-global] PASS';
        RAISERROR(@msg, 0, 1) WITH NOWAIT;

        /* [7.5] reserve slot + persist accepted log */
        UPDATE dbo.tbl_700_risk_state
           SET open_positions = open_positions + 1
         WHERE trade_date = @today;

        INSERT dbo.tbl_700_open_trades_log
            (guid, product, signal, created_ts, entry_price, entry_bucket, time_bin, session, decision, size, created_at)
        VALUES
            (@guid, @product, @signal, @created, @entry_price, @eb, @tb, @session, 'accepted', NULL, GETDATE());

        COMMIT;
        SET TRANSACTION ISOLATION LEVEL READ COMMITTED;

        SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
        SET @msg = N'' + @ts + N' sp_700 [7.5:commit] PASS accepted logged & slot reserved';
        RAISERROR(@msg, 0, 1) WITH NOWAIT;

    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK;
        SET TRANSACTION ISOLATION LEVEL READ COMMITTED;

        SET @accept = 0; SET @reason = N'error';
        SET @accept_return_type = NULL; SET @flip_trade = NULL;

        SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
        SET @msg = CONCAT(@ts, N' sp_700 [7:error] ', ERROR_MESSAGE());
        RAISERROR(@msg, 0, 1) WITH NOWAIT;

        IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
        MERGE dbo.sp_700_gate_outbox AS t
        USING (SELECT @guid AS guid) s ON t.guid = s.guid
        WHEN MATCHED     THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                         entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
        WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                              VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());

        DECLARE @err_msg nvarchar(2048) = ERROR_MESSAGE();
        DECLARE @err_sev int = ERROR_SEVERITY();
        DECLARE @err_state int = ERROR_STATE();
        RAISERROR(@err_msg, @err_sev, @err_state);
        RETURN;
    END CATCH;

    /* [8] Publish to outbox (post-commit success) */
    IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
    MERGE dbo.sp_700_gate_outbox AS t
    USING (SELECT @guid AS guid) s ON t.guid = s.guid
    WHEN MATCHED     THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                     entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
    WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                          VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());

    SET @ts = CONVERT(VARCHAR(23), GETDATE(), 121);
    SET @msg = CONCAT(
        @ts, N' sp_700 [8:done] accept=', CONVERT(varchar(6),@accept),
        N' reason=', ISNULL(@reason,N'NULL'),
        N' return_type=', ISNULL(@accept_return_type,N'NULL'),
        N' flip=', ISNULL(CONVERT(varchar(12),@flip_trade),N'NULL')
    );
    RAISERROR(@msg, 0, 1) WITH NOWAIT;
END

CREATE   PROCEDURE dbo.sp_700_decide_open_cfg
  @guid        UNIQUEIDENTIFIER,
  @product     NVARCHAR(50),
  @signal      NVARCHAR(10),
  @created     DATETIME2(3),
  @entry_price DECIMAL(18,10),
  @session     SMALLINT = NULL
AS
BEGIN
  SET NOCOUNT ON;

  DECLARE
    @count_min        INT,
    @hit_min          DECIMAL(9,6),
    @alt_mean_min     DECIMAL(19,4),
    @max_open         INT,
    @kill_level       DECIMAL(19,4),
    @max_per_product  INT;

  SELECT @count_min       = TRY_CONVERT(INT,            (SELECT config_value FROM dbo.config WHERE config_name='700_count_min'));
  SELECT @hit_min         = TRY_CONVERT(DECIMAL(9,6),   (SELECT config_value FROM dbo.config WHERE config_name='700_hit_min'));
  SELECT @alt_mean_min    = TRY_CONVERT(DECIMAL(19,4),  (SELECT config_value FROM dbo.config WHERE config_name='700_alt_mean_min'));
  SELECT @max_open        = TRY_CONVERT(INT,            (SELECT config_value FROM dbo.config WHERE config_name='700_max_open'));
  SELECT @kill_level      = TRY_CONVERT(DECIMAL(19,4),  (SELECT config_value FROM dbo.config WHERE config_name='700_kill_level'));
  SELECT @max_per_product = TRY_CONVERT(INT,            (SELECT config_value FROM dbo.config WHERE config_name='700_max_per_product'));

  -- CSV-baseline fallbacks
  SET @count_min       = ISNULL(@count_min, 5);
  SET @hit_min         = ISNULL(@hit_min, 0.55);
  SET @alt_mean_min    = ISNULL(@alt_mean_min, 5);
  SET @max_open        = ISNULL(@max_open, 3);
  SET @kill_level      = ISNULL(@kill_level, -750);
  SET @max_per_product = ISNULL(@max_per_product, 1);

  -- Pass through the same result set as sp_700_decide_open
  EXEC dbo.sp_700_decide_open
       @guid=@guid,
       @product=@product,
       @signal=@signal,
       @created=@created,
       @entry_price=@entry_price,
       @count_min=@count_min,
       @hit_min=@hit_min,
       @alt_mean_min=@alt_mean_min,
       @max_open=@max_open,
       @kill_level=@kill_level,
       @max_per_product=@max_per_product,
       @session=@session;
END

create   PROCEDURE [dbo].[sp_700_decide_open_v0]
    @guid                UNIQUEIDENTIFIER,
    @product             NVARCHAR(50),
    @signal              NVARCHAR(10),
    @created             DATETIME2(3),
    @entry_price         DECIMAL(18,10),

    -- thresholds
    @count_min           INT            = 5,
    @hit_min             DECIMAL(9,6)   = 0.52,
    @alt_mean_min        DECIMAL(19,4)  = 0.0,     -- kept for backward-compat (not used by sums gate)

    -- risk gates
    @max_open            INT            = 3,
    @kill_level          DECIMAL(19,4)  = -750.0,
    @max_per_product     INT            = 1,

    -- optional session (NULL => no session dimension)
    @session             SMALLINT       = NULL,

    -- decision outputs
    @accept              BIT            OUTPUT,
    @reason              NVARCHAR(32)   OUTPUT,
    @entry_bucket        INT            OUTPUT,
    @time_bin            INT            OUTPUT,
    @accept_return_type  NVARCHAR(20)   OUTPUT,  -- 'net_return' | 'alt_net_return'
    @flip_trade          BIT            OUTPUT   -- 0 = net focus, 1 = alt focus
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    /* -------- Derive buckets / keys -------- */
    DECLARE @eb INT = dbo.fn_700_choose_bucket(@product, @entry_price);
    DECLARE @tb INT = dbo.fn_700_time_bin(@created);
    IF @eb IS NULL SET @eb = 0;
    IF @tb IS NULL SET @tb = 0;

    SET @entry_bucket = @eb;
    SET @time_bin     = @tb;

    DECLARE @today   DATE     = CONVERT(date, @created AT TIME ZONE 'GMT Standard Time');
    DECLARE @sesskey SMALLINT = CONVERT(SMALLINT, ISNULL(@session, -1));

    /* -------- Priors (closed-only), pivot by return_type -------- */
    DECLARE
        @cnt     INT            = 0,
        @wins    DECIMAL(19,4)  = 0,
        @net_sum DECIMAL(19,4)  = 0,  -- sum for rows where return_type='net_return'
        @alt_sum DECIMAL(19,4)  = 0;  -- sum for rows where return_type='alt_net_return'

    ;WITH pri AS (
        SELECT
            p.return_type,
            p.prior_count,
            p.prior_win_sum,
            p.prior_alt_sum
        FROM dbo.tbl_700_priors AS p
        WHERE p.product      = @product
          AND p.signal       = @signal
          AND p.entry_bucket = @eb
          AND p.time_bin     = @tb
          AND p.session_key  = @sesskey
    )
    SELECT
        @cnt     = ISNULL(SUM(prior_count), 0),
        @wins    = ISNULL(SUM(prior_win_sum), 0),
        @net_sum = ISNULL(SUM(CASE WHEN return_type = N'net_return'      THEN prior_win_sum ELSE 0 END), 0),
        @alt_sum = ISNULL(SUM(CASE WHEN return_type = N'alt_net_return'  THEN prior_alt_sum  ELSE 0 END), 0)
    FROM pri;

    DECLARE @hit DECIMAL(19,6) = CASE WHEN @cnt > 0 THEN CAST(@wins AS DECIMAL(19,6)) / NULLIF(@cnt,0) ELSE 0 END;

    /* -------- Threshold gates: support + hit -------- */
    IF @entry_bucket = 0 OR @time_bin = 0
    BEGIN
        SET @accept = 0; SET @reason = N'700_bucket_or_timebin_null';
        SET @accept_return_type = NULL; SET @flip_trade = NULL;

        INSERT dbo.tbl_700_open_trades_log
            (guid, product, signal, created_ts, entry_price, entry_bucket, time_bin, session, decision, size, created_at)
        VALUES
            (@guid, @product, @signal, @created, @entry_price, @eb, @tb, @session, @reason, NULL, SYSUTCDATETIME());

        IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
        MERGE dbo.sp_700_gate_outbox AS t
        USING (SELECT @guid AS guid) s ON t.guid = s.guid
        WHEN MATCHED THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                     entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
        WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                              VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
        RETURN;
    END

    IF @cnt < @count_min
    BEGIN
        SET @accept = 0; SET @reason = N'low_support';
        SET @accept_return_type = NULL; SET @flip_trade = NULL;

        INSERT dbo.tbl_700_open_trades_log
            (guid, product, signal, created_ts, entry_price, entry_bucket, time_bin, session, decision, size, created_at)
        VALUES
            (@guid, @product, @signal, @created, @entry_price, @eb, @tb, @session, @reason, NULL, SYSUTCDATETIME());

        IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
        MERGE dbo.sp_700_gate_outbox AS t
        USING (SELECT @guid AS guid) s ON t.guid = s.guid
        WHEN MATCHED THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                     entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
        WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                              VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
        RETURN;
    END

    IF @hit < @hit_min
    BEGIN
        SET @accept = 0; SET @reason = N'low_hit_rate';
        SET @accept_return_type = NULL; SET @flip_trade = NULL;

        INSERT dbo.tbl_700_open_trades_log
            (guid, product, signal, created_ts, entry_price, entry_bucket, time_bin, session, decision, size, created_at)
        VALUES
            (@guid, @product, @signal, @created, @entry_price, @eb, @tb, @session, @reason, NULL, SYSUTCDATETIME());

        IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
        MERGE dbo.sp_700_gate_outbox AS t
        USING (SELECT @guid AS guid) s ON t.guid = s.guid
        WHEN MATCHED THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                     entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
        WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                              VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
        RETURN;
    END

    /* -------- NEW: sums-driven flip decision (replaces alt_mean gate) --------
       net_sum > 0 and alt_sum <= 0 → net focus (flip=0)
       alt_sum > 0 and net_sum <= 0 → alt focus (flip=1)
       else (both <= 0 OR both > 0) → reject (ambiguous or negative)
    */
    DECLARE @pre_accept BIT = 0;
    DECLARE @pre_reason NVARCHAR(32) = NULL;

    IF (@net_sum > 0 AND @alt_sum <= 0)
    BEGIN
        SET @pre_accept = 1;
        SET @pre_reason = N'accept_net';
        SET @accept_return_type = N'net_return';
        SET @flip_trade = 0;
    END
    ELSE IF (@alt_sum > 0 AND @net_sum <= 0)
    BEGIN
        SET @pre_accept = 1;
        SET @pre_reason = N'accept_alt';
        SET @accept_return_type = N'alt_net_return';
        SET @flip_trade = 1;
    END
    ELSE
    BEGIN
        SET @accept = 0; 
        SET @reason = CASE 
                        WHEN @net_sum <= 0 AND @alt_sum <= 0 THEN N'both_negative'
                        ELSE N'ambiguous_dual_positive'   -- both > 0 → ambiguous; keep explicit reason
                      END;
        SET @accept_return_type = NULL; 
        SET @flip_trade = NULL;

        INSERT dbo.tbl_700_open_trades_log
            (guid, product, signal, created_ts, entry_price, entry_bucket, time_bin, session, decision, size, created_at)
        VALUES
            (@guid, @product, @signal, @created, @entry_price, @eb, @tb, @session, @reason, NULL, SYSUTCDATETIME());

        IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
        MERGE dbo.sp_700_gate_outbox AS t
        USING (SELECT @guid AS guid) s ON t.guid = s.guid
        WHEN MATCHED THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                     entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
        WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                              VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
        RETURN;
    END

    /* -------- Risk gates + atomic accept -------- */
    SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
    BEGIN TRY
        BEGIN TRAN;

        -- serialize by product/session
        DECLARE @lockname sysname = CONCAT(N'sp700:', LOWER(@product), N':', ISNULL(CONVERT(nvarchar(10), @sesskey), N'-1'));
        DECLARE @lockres int;
        EXEC @lockres = sp_getapplock
            @Resource = @lockname,
            @LockMode = 'Exclusive',
            @LockOwner = 'Transaction',
            @LockTimeout = 0;
        IF @lockres < 0
        BEGIN
            ROLLBACK;
            SET @accept = 0; SET @reason = N'lock_conflict';
            SET @accept_return_type = NULL; SET @flip_trade = NULL;

            INSERT dbo.tbl_700_open_trades_log
                (guid, product, signal, created_ts, entry_price, entry_bucket, time_bin, session, decision, size, created_at)
            VALUES
                (@guid, @product, @signal, @created, @entry_price, @eb, @tb, @session, @reason, NULL, SYSUTCDATETIME());

            IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
            MERGE dbo.sp_700_gate_outbox AS t
            USING (SELECT @guid AS guid) s ON t.guid = s.guid
            WHEN MATCHED THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                         entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
            WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                                  VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
            RETURN;
        END

        -- ensure today's risk row exists & lock it
        MERGE dbo.tbl_700_risk_state WITH (HOLDLOCK) AS t
        USING (SELECT @today AS trade_date) AS s
        ON t.trade_date = s.trade_date
        WHEN NOT MATCHED THEN
            INSERT (trade_date, open_positions, realized_pnl) VALUES (s.trade_date, 0, 0);

        DECLARE @open INT, @realized DECIMAL(19,4);
        SELECT @open = open_positions, @realized = realized_pnl
        FROM dbo.tbl_700_risk_state WITH (UPDLOCK, HOLDLOCK)
        WHERE trade_date = @today;

        -- kill switch
        IF @realized <= @kill_level
        BEGIN
            ROLLBACK;
            SET @accept = 0; SET @reason = N'kill_switch';
            SET @accept_return_type = NULL; SET @flip_trade = NULL;

            INSERT dbo.tbl_700_open_trades_log
                (guid, product, signal, created_ts, entry_price, entry_bucket, time_bin, session, decision, size, created_at)
            VALUES
                (@guid, @product, @signal, @created, @entry_price, @eb, @tb, @session, @reason, NULL, SYSUTCDATETIME());

            IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
            MERGE dbo.sp_700_gate_outbox AS t
            USING (SELECT @guid AS guid) s ON t.guid = s.guid
            WHEN MATCHED THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                         entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
            WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                                  VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
            RETURN;
        END

        -- per-product cap (accepted)
        DECLARE @open_prod INT = (
            SELECT COUNT(*)
            FROM dbo.tbl_700_open_trades_log WITH (UPDLOCK, HOLDLOCK)
            WHERE product = @product
              AND decision = 'accepted'
              AND (@session IS NULL OR session = @session)
        );
        IF @open_prod >= @max_per_product
        BEGIN
            ROLLBACK;
            SET @accept = 0; SET @reason = N'no_product_slot';
            SET @accept_return_type = NULL; SET @flip_trade = NULL;

            INSERT dbo.tbl_700_open_trades_log
                (guid, product, signal, created_ts, entry_price, entry_bucket, time_bin, session, decision, size, created_at)
            VALUES
                (@guid, @product, @signal, @created, @entry_price, @eb, @tb, @session, @reason, NULL, SYSUTCDATETIME());

            IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
            MERGE dbo.sp_700_gate_outbox AS t
            USING (SELECT @guid AS guid) s ON t.guid = s.guid
            WHEN MATCHED THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                         entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
            WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                                  VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
            RETURN;
        END

        -- global concurrency
        IF @open >= @max_open
        BEGIN
            ROLLBACK;
            SET @accept = 0; SET @reason = N'no_global_slots';
            SET @accept_return_type = NULL; SET @flip_trade = NULL;

            INSERT dbo.tbl_700_open_trades_log
                (guid, product, signal, created_ts, entry_price, entry_bucket, time_bin, session, decision, size, created_at)
            VALUES
                (@guid, @product, @signal, @created, @entry_price, @eb, @tb, @session, @reason, NULL, SYSUTCDATETIME());

            IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
            MERGE dbo.sp_700_gate_outbox AS t
            USING (SELECT @guid AS guid) s ON t.guid = s.guid
            WHEN MATCHED THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                         entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
            WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                                  VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
            RETURN;
        END

        -- reserve slot + write accepted log INSIDE txn
        UPDATE dbo.tbl_700_risk_state
           SET open_positions = open_positions + 1
         WHERE trade_date = @today;

        SET @accept = 1;
        SET @reason = ISNULL(@pre_reason, N'accepted');

        INSERT dbo.tbl_700_open_trades_log
            (guid, product, signal, created_ts, entry_price, entry_bucket, time_bin, session, decision, size, created_at)
        VALUES
            (@guid, @product, @signal, @created, @entry_price, @eb, @tb, @session, @reason, NULL, SYSUTCDATETIME());

        COMMIT;
        SET TRANSACTION ISOLATION LEVEL READ COMMITTED;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK;
        SET TRANSACTION ISOLATION LEVEL READ COMMITTED;

        SET @accept = 0; SET @reason = N'error';
        SET @accept_return_type = NULL; SET @flip_trade = NULL;

        INSERT dbo.tbl_700_open_trades_log
            (guid, product, signal, created_ts, entry_price, entry_bucket, time_bin, session, decision, size, created_at)
        VALUES
            (@guid, @product, @signal, @created, @entry_price, @eb, @tb, @session, @reason, NULL, SYSUTCDATETIME());

        IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
        MERGE dbo.sp_700_gate_outbox AS t
        USING (SELECT @guid AS guid) s ON t.guid = s.guid
        WHEN MATCHED THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                     entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
        WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                              VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
        RETURN;
    END CATCH

    -- publish to outbox (post-commit)
    IF OBJECT_ID('dbo.sp_700_gate_outbox','U') IS NOT NULL
    MERGE dbo.sp_700_gate_outbox AS t
    USING (SELECT @guid AS guid) s ON t.guid = s.guid
    WHEN MATCHED THEN UPDATE SET product=@product, signal=@signal, accept=@accept, reason=@reason,
                                 entry_bucket=@entry_bucket, time_bin=@time_bin, created=GETDATE()
    WHEN NOT MATCHED THEN INSERT (guid,product,signal,accept,reason,entry_bucket,time_bin,created)
                          VALUES (@guid,@product,@signal,@accept,@reason,@entry_bucket,@time_bin,GETDATE());
END

CREATE   PROCEDURE dbo.sp_700_ingest_vwCombined_trades_closed
AS
BEGIN
  SET NOCOUNT ON;

  DECLARE @last_ts DATETIME2(3);

  SELECT @last_ts = last_close_ts
  FROM dbo.tbl_700_etl_state WITH (UPDLOCK, HOLDLOCK)
  WHERE source_name = 'vwCombined_trades_closed';

  IF @last_ts IS NULL
  BEGIN
    SET @last_ts = '1900-01-01T00:00:00.000';
    MERGE dbo.tbl_700_etl_state AS T
    USING (SELECT 'vwCombined_trades_closed' AS source_name) AS S
    ON T.source_name = S.source_name
    WHEN NOT MATCHED THEN
      INSERT (source_name, last_close_ts) VALUES (S.source_name, @last_ts);
  END

  DECLARE @rows dbo.tt_700_ClosedTradeTVP;

  INSERT @rows (guid, product, signal, created, entry_price, last_update,
                alt_net_return, net_return, session, is_closed)
  SELECT
    v.guid, v.product, v.signal, v.created, v.entry_price, v.last_update,
    v.alt_net_return, v.net_return, NULL AS session, 1 AS is_closed
  FROM dbo.vwCombined_trades_closed AS v
  WHERE v.last_update > @last_ts;

  -- Nothing new? Bail fast.
  IF NOT EXISTS (SELECT 1 FROM @rows) RETURN;

  EXEC dbo.sp_700_bulk_on_close_update @rows = @rows;

  -- Advance checkpoint to the max last_update we just processed
  DECLARE @new_last_ts DATETIME2(3) =
    (SELECT MAX(last_update) FROM @rows);

  UPDATE dbo.tbl_700_etl_state
    SET last_close_ts = @new_last_ts
  WHERE source_name = 'vwCombined_trades_closed';
END

CREATE   PROCEDURE dbo.sp_700_on_close_update
  @guid            UNIQUEIDENTIFIER,
  @product         NVARCHAR(50),
  @signal          NVARCHAR(10),
  @created         DATETIME2(3),
  @entry_price     DECIMAL(18,10),
  @last_update     DATETIME2(3),
  @alt_net_return  DECIMAL(19,4) = NULL,
  @net_return      DECIMAL(19,4) = NULL,
  @session         SMALLINT      = NULL,
  @is_closed       BIT           = 1   -- NEW: must be 1 to update priors
AS
BEGIN
  SET NOCOUNT ON;

  IF (@is_closed <> 1)
  BEGIN
    -- Reject any attempt to feed priors from an open trade
    ;THROW 51001, 'sp_700_on_close_update called with @is_closed=0. Priors are CLOSED-only.', 1;
  END

  DECLARE @entry_bucket INT, @time_bin INT, @pnl DECIMAL(19,4);
  SELECT @entry_bucket=entry_bucket, @time_bin=time_bin
  FROM dbo.tbl_700_open_trades_log WHERE guid=@guid;

  IF @entry_bucket IS NULL OR @time_bin IS NULL
  BEGIN
    -- Fallback (discouraged): recompute from current cutpoints
    SET @entry_bucket = dbo.fn_700_choose_bucket(@product, @entry_price);
    SET @time_bin     = dbo.fn_700_time_bin(@created);
  END

  SET @pnl = COALESCE(@alt_net_return, @net_return, 0);
  DECLARE @sess_key SMALLINT = CONVERT(SMALLINT, ISNULL(@session, -1));

  MERGE dbo.tbl_700_priors WITH (HOLDLOCK) AS T
  USING (SELECT @product AS product, @signal AS signal, @entry_bucket AS entry_bucket,
                @time_bin AS time_bin, @sess_key AS session_key) AS S
  ON (T.product=S.product AND T.signal=S.signal AND T.entry_bucket=S.entry_bucket
      AND T.time_bin=S.time_bin AND T.session_key=S.session_key)
  WHEN MATCHED THEN
    UPDATE SET prior_count   = T.prior_count + 1,
               prior_win_sum = T.prior_win_sum + CASE WHEN @pnl > 0 THEN 1 ELSE 0 END,
               prior_alt_sum = T.prior_alt_sum + @pnl
  WHEN NOT MATCHED THEN
    INSERT (product,signal,entry_bucket,time_bin,session,prior_count,prior_win_sum,prior_alt_sum)
    VALUES (S.product,S.signal,S.entry_bucket,S.time_bin, NULLIF(@sess_key,-1),
            1, CASE WHEN @pnl>0 THEN 1 ELSE 0 END, @pnl);

  DECLARE @close_date DATE = CONVERT(date, @last_update AT TIME ZONE 'GMT Standard Time');

  MERGE dbo.tbl_700_risk_state WITH (HOLDLOCK) AS t
  USING (SELECT @close_date AS trade_date) AS s
  ON t.trade_date = s.trade_date
  WHEN NOT MATCHED THEN
    INSERT (trade_date, open_positions, realized_pnl) VALUES (s.trade_date, 0, 0);

  UPDATE dbo.tbl_700_risk_state
     SET open_positions = CASE WHEN open_positions > 0 THEN open_positions - 1 ELSE 0 END,
         realized_pnl   = realized_pnl + @pnl
   WHERE trade_date = @close_date;

  UPDATE dbo.tbl_700_open_trades_log SET decision='closed' WHERE guid=@guid;
END

CREATE PROCEDURE dbo.sp_700_RebuildPriors_7d_nomodel
  @window_days int = 7
AS
BEGIN
  SET NOCOUNT ON;

  DECLARE @asof datetime2(3) = GETDATE();

  BEGIN TRY
    BEGIN TRAN;

    /* Full refresh */
    TRUNCATE TABLE dbo.tbl_700_priors_7d_nomodel;

    /* Build priors from archive in a single scan */
    ;WITH Base AS (
      SELECT
        t.product,
        t.signal,
        entry_bucket = dbo.fn_700_entry_bucket(t.entry_price),
        time_bin     = dbo.fn_700_time_bin(t.created),  -- 1-arg version
        t.net_return,
        t.alt_net_return
      FROM dbo.combined_trades_closed_arc AS t
      WHERE t.created >= DATEADD(day, -@window_days, @asof)
    ),
    Unpiv AS (
      SELECT product, signal, entry_bucket, time_bin,
             return_type  = N'net_return',
             return_value = CAST(net_return AS float)
      FROM Base
      UNION ALL
      SELECT product, signal, entry_bucket, time_bin,
             return_type  = N'alt_net_return',
             return_value = CAST(alt_net_return AS float)
      FROM Base
    ),
    Agg AS (
      SELECT
        product,
        signal,
        entry_bucket,
        time_bin,
        return_type,
        trade_count = COUNT(*),
        win_count   = SUM(CASE WHEN return_value > 0 THEN 1 ELSE 0 END),
        loss_count  = SUM(CASE WHEN return_value <= 0 THEN 1 ELSE 0 END),
        return_sum  = SUM(return_value)
      FROM Unpiv
      GROUP BY product, signal, entry_bucket, time_bin, return_type
    )
    INSERT INTO dbo.tbl_700_priors_7d_nomodel
      (product, signal, entry_bucket, time_bin, return_type,
       trade_count, win_count, loss_count, return_sum, avg_return, hit_rate, last_updated)
    SELECT
      product,
      signal,
      entry_bucket,
      time_bin,
      return_type,
      trade_count,
      win_count,
      loss_count,
      return_sum,
      avg_return = return_sum / NULLIF(CAST(trade_count AS float), 0),
      hit_rate   = CAST(win_count AS float) / NULLIF(CAST(trade_count AS float), 0),
      @asof
    FROM Agg;

    COMMIT TRAN;
  END TRY
  BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRAN;

    DECLARE
      @errnum  int        = ERROR_NUMBER(),
      @errsev  int        = ERROR_SEVERITY(),
      @errst   int        = ERROR_STATE(),
      @errproc sysname    = ERROR_PROCEDURE(),
      @errline int        = ERROR_LINE(),
      @errmsg  nvarchar(4000) = ERROR_MESSAGE();

    RAISERROR('[sp_700_RebuildPriors_7d_nomodel] %s (num=%d, sev=%d, state=%d, proc=%s, line=%d)',
              @errsev, 1,
              @errmsg, @errnum, @errsev, @errst, @errproc, @errline);
    RETURN;
  END CATCH
END

CREATE PROCEDURE dbo.sp_700_RebuildPriors_v2
AS
BEGIN
  SET NOCOUNT ON;
  BEGIN TRAN;
    TRUNCATE TABLE dbo.tbl_700_priors_v2;
    INSERT INTO dbo.tbl_700_priors_v2
