CREATE   PROCEDURE dbo.sp_700_run_workflow
  @do_ingest BIT=1, @do_buckets BIT=NULL, @do_rebuild_priors BIT=0,
  @priors_days_back INT=45, @priors_cap_per_key INT=NULL, @bucket_quantiles_N INT=20
AS
BEGIN
  SET NOCOUNT ON;

  DECLARE @source SYSNAME = N'combined_trades_closed';  -- << key name in etl_state
  DECLARE @utcnow DATETIME2(3)=SYSUTCDATETIME(),
          @n_ingested INT=0, @sum_pnl DECIMAL(19,4)=0,
          @last_before DATETIME2(3), @last_after DATETIME2(3),
          @did_buckets BIT=0, @did_priors BIT=0;

  -- checkpoint row
  IF NOT EXISTS (SELECT 1 FROM dbo.tbl_700_etl_state WHERE source_name=@source)
    INSERT dbo.tbl_700_etl_state(source_name,last_close_ts) VALUES (@source,'1900-01-01');

  SELECT @last_before = last_close_ts
  FROM dbo.tbl_700_etl_state WITH (UPDLOCK, HOLDLOCK)
  WHERE source_name=@source;

  IF @do_ingest=1
  BEGIN
    DECLARE @rows dbo.tt_700_ClosedTradeTVP;
    INSERT @rows (guid,product,signal,created,entry_price,last_update,alt_net_return,net_return,session,is_closed)
    SELECT v.guid, v.product, v.signal, v.created, v.entry_price, v.last_update,
           v.alt_net_return, v.net_return, NULL, 1
    FROM dbo.combined_trades_closed v            -- << now using the table
    WHERE v.last_update > ISNULL(@last_before,'1900-01-01');

    SELECT @n_ingested = COUNT(*),
           @sum_pnl    = COALESCE(SUM(COALESCE(alt_net_return,net_return,0)),0),
           @last_after = MAX(last_update)
    FROM @rows;

    IF @n_ingested > 0
    BEGIN
      EXEC dbo.sp_700_bulk_on_close_update @rows=@rows;
      UPDATE dbo.tbl_700_etl_state SET last_close_ts=@last_after WHERE source_name=@source;
    END
    ELSE
      SET @last_after=@last_before;
  END

  -- buckets (unchanged): uses vw_700_closed_trades which now points to history
  IF @do_buckets IS NULL
    SET @do_buckets = CASE WHEN CONVERT(date,(SELECT extra_dt FROM dbo.tbl_700_etl_state WHERE source_name='buckets')) 
                                 <> CONVERT(date,@utcnow) THEN 1 ELSE 0 END;
  IF @do_buckets=1
  BEGIN
    EXEC dbo.sp_700_recompute_bucket_boundaries @N=@bucket_quantiles_N;
    MERGE dbo.tbl_700_etl_state AS T USING (SELECT 'buckets' n) S ON T.source_name=S.n
    WHEN MATCHED THEN UPDATE SET extra_dt=@utcnow
    WHEN NOT MATCHED THEN INSERT(source_name,extra_dt) VALUES ('buckets',@utcnow);
    SET @did_buckets=1;
  END

  -- optional rolling priors rebuild
  IF @do_rebuild_priors=1
  BEGIN
    IF @priors_cap_per_key IS NULL
      EXEC dbo.sp_700_rebuild_priors_from_window @days_back=@priors_days_back;
    ELSE
      EXEC dbo.sp_700_rebuild_priors_capped @days_back=@priors_days_back, @max_per_key=@priors_cap_per_key;

    MERGE dbo.tbl_700_etl_state AS T USING (SELECT 'priors_rebuild' n) S ON T.source_name=S.n
    WHEN MATCHED THEN UPDATE SET extra_dt=@utcnow
    WHEN NOT MATCHED THEN INSERT(source_name,extra_dt) VALUES ('priors_rebuild',@utcnow);
    SET @did_priors=1;
  END

  SELECT @n_ingested AS ingested_closed_rows,
         @sum_pnl AS ingested_sum_alt_pnl,
         @last_before AS last_close_ts_before,
         @last_after AS last_close_ts_after,
         @did_buckets AS buckets_recomputed,
         @bucket_quantiles_N AS buckets_N_used,
         @did_priors AS priors_rebuilt,
         @priors_days_back AS priors_days_back_used,
         @priors_cap_per_key AS priors_cap_per_key_used;
END

CREATE   PROCEDURE [dbo].[sp_701_cum_positive]
  @product nvarchar(50),
  @model   nvarchar(50),
  @signal  nvarchar(50),         -- 'buy' | 'sell'
  @rt      char(3) = NULL,       -- 'ALT' | 'NET' | NULL
  @ok      bit OUTPUT,
  @reason  nvarchar(32) OUTPUT,
  @debug   bit = 0               -- NEW: print step-by-step details if 1
AS
BEGIN
  SET NOCOUNT ON;

  /* ---- ensure log table exists ---- */
  IF OBJECT_ID('dbo.sp_701_log','U') IS NULL
  BEGIN
    CREATE TABLE dbo.sp_701_log
    (
      log_id               bigint IDENTITY(1,1) PRIMARY KEY,
      log_time             datetime2(3) NOT NULL CONSTRAINT DF_sp701log_time DEFAULT (SYSDATETIME()),
      product              nvarchar(50) NOT NULL,
      model                nvarchar(50) NOT NULL,
      signal               nvarchar(50) NOT NULL,
      forced_rt            char(3)      NULL,         -- 'ALT' | 'NET' | NULL
      min_return           decimal(38,8) NULL,
      topN                 int           NULL,
      cum_net              decimal(38,8) NULL,
      cum_alt              decimal(38,8) NULL,
      inTopNet             bit           NULL,
      inTopAlt             bit           NULL,
      pass_net             bit           NULL,
      pass_alt             bit           NULL,
      ok                   bit           NULL,
      reason               nvarchar(32)  NULL
    );
  END

  /* ---- global skip ---- */
  DECLARE @skip_701 INT =
    TRY_CAST((SELECT config_value FROM dbo.config WHERE config_name='skip_701') AS INT);
  IF ISNULL(@skip_701,0) = 1
  BEGIN
    SET @ok = 1; SET @reason = N'skip_701';
    IF @debug = 1 PRINT CONCAT('[701] SKIP for ', @product, '/', @model, '/', @signal, ' (skip_701=1)');
    INSERT dbo.sp_701_log(product, model, signal, forced_rt, ok, reason)
    VALUES(@product, @model, @signal, @rt, @ok, @reason);
    RETURN;
  END

  /* ---- thresholds ---- */
  DECLARE @min_return DECIMAL(38,8) =
    TRY_CAST((SELECT config_value FROM dbo.config WHERE config_name='701_min_return') AS DECIMAL(38,8));
  IF @min_return IS NULL SET @min_return = 0;

  DECLARE @topN INT =
    TRY_CAST((SELECT config_value FROM dbo.config WHERE config_name='701_top_return_range') AS INT);
  IF @topN IS NULL OR @topN <= 0 SET @topN = 5;  -- strict first-N

  IF @debug = 1
  BEGIN
    PRINT CONCAT('[701] Start product=', @product, ' model=', @model, ' signal=', @signal, ' rt=', COALESCE(@rt,'NULL'));
    PRINT CONCAT('[701] Config: min_return=', FORMAT(@min_return,'0.########'), ' topN=', @topN);
  END

  /* ---- build reusable latest-snapshot set into a temp table ---- */
  IF OBJECT_ID('tempdb..#L') IS NOT NULL DROP TABLE #L;

  ;WITH latest AS (
    SELECT
        t.product, t.model, t.signal,
        t.net_return_sum, t.alt_net_return_sum, t.update_time,
        ROW_NUMBER() OVER (
          PARTITION BY t.product, t.model, t.signal
          ORDER BY t.update_time DESC
        ) AS rn
    FROM dbo.tbl_model_signal_net AS t
    WHERE t.product = @product
      AND t.signal  = @signal
  )
  SELECT
      product, model, signal,
      net_return_sum, alt_net_return_sum
  INTO #L
  FROM latest
  WHERE rn = 1;

  /* ---- fetch current model’s cum values ---- */
  DECLARE @cum_net DECIMAL(38,8) = NULL,
          @cum_alt DECIMAL(38,8) = NULL;

  SELECT
      @cum_net = l.net_return_sum,
      @cum_alt = l.alt_net_return_sum
  FROM #L AS l
  WHERE l.model = @model;

  IF @debug = 1
  BEGIN
    PRINT CONCAT('[701] Cum values: net=', COALESCE(FORMAT(@cum_net,'0.########'), 'NULL'),
                 ' alt=', COALESCE(FORMAT(@cum_alt,'0.########'), 'NULL'));
  END

  IF @cum_net IS NULL AND @cum_alt IS NULL
  BEGIN
    SET @ok = 0; SET @reason = N'cum_missing';
    IF @debug = 1 PRINT '[701] FAIL: no snapshot row for model';
    INSERT dbo.sp_701_log(product, model, signal, forced_rt, min_return, topN,
                          cum_net, cum_alt, ok, reason)
    VALUES(@product, @model, @signal, @rt, @min_return, @topN,
           @cum_net, @cum_alt, @ok, @reason);
    RETURN;
  END

  /* ---- strict TOP(@topN) membership flags ---- */
  DECLARE @inTopAlt bit, @inTopNet bit;

  SET @inTopAlt =
    CASE WHEN EXISTS (
      SELECT 1
      FROM (
        SELECT TOP (@topN) l2.model
        FROM #L AS l2
        WHERE l2.alt_net_return_sum > @min_return
        ORDER BY l2.alt_net_return_sum DESC, l2.model ASC   -- tie-breaker
      ) AS topALT
      WHERE topALT.model = @model
    ) THEN 1 ELSE 0 END;

  SET @inTopNet =
    CASE WHEN EXISTS (
      SELECT 1
      FROM (
        SELECT TOP (@topN) l3.model
        FROM #L AS l3
        WHERE l3.net_return_sum > @min_return
        ORDER BY l3.net_return_sum DESC, l3.model ASC       -- tie-breaker
      ) AS topNET
      WHERE topNET.model = @model
    ) THEN 1 ELSE 0 END;

  /* ---- side pass flags (threshold + strict topN membership) ---- */
  DECLARE @pass_alt bit, @pass_net bit;
  SET @pass_alt = CASE WHEN @cum_alt IS NOT NULL AND @cum_alt > @min_return AND @inTopAlt = 1 THEN 1 ELSE 0 END;
  SET @pass_net = CASE WHEN @cum_net IS NOT NULL AND @cum_net > @min_return AND @inTopNet = 1 THEN 1 ELSE 0 END;

  IF @debug = 1
  BEGIN
    PRINT CONCAT('[701] Membership: inTopNET=', @inTopNet, ' inTopALT=', @inTopAlt);
    PRINT CONCAT('[701] Pass flags: pass_net=', @pass_net, ' pass_alt=', @pass_alt);
  END

  /* ---- forced side ---- */
  IF @rt = 'ALT'
  BEGIN
    IF @pass_alt = 1
    BEGIN
      SET @ok = 1; SET @reason = N'alt_topN';
      IF @debug = 1 PRINT '[701] PASS (forced ALT)';
      INSERT dbo.sp_701_log(product, model, signal, forced_rt, min_return, topN,
                            cum_net, cum_alt, inTopNet, inTopAlt, pass_net, pass_alt, ok, reason)
      VALUES(@product, @model, @signal, @rt, @min_return, @topN,
             @cum_net, @cum_alt, @inTopNet, @inTopAlt, @pass_net, @pass_alt, @ok, @reason);
      RETURN;
    END
    ELSE
    BEGIN
      IF NOT (@cum_alt > @min_return) SET @reason = N'cum_alt<=min';
      ELSE IF @inTopAlt = 0          SET @reason = N'alt_not_in_topN';
      ELSE                           SET @reason = N'alt_fail';
      SET @ok = 0;
      IF @debug = 1 PRINT CONCAT('[701] FAIL (forced ALT): ', @reason);
      INSERT dbo.sp_701_log(product, model, signal, forced_rt, min_return, topN,
                            cum_net, cum_alt, inTopNet, inTopAlt, pass_net, pass_alt, ok, reason)
      VALUES(@product, @model, @signal, @rt, @min_return, @topN,
             @cum_net, @cum_alt, @inTopNet, @inTopAlt, @pass_net, @pass_alt, @ok, @reason);
      RETURN;
    END
  END

  IF @rt = 'NET'
  BEGIN
    IF @pass_net = 1
    BEGIN
      SET @ok = 1; SET @reason = N'net_topN';
      IF @debug = 1 PRINT '[701] PASS (forced NET)';
      INSERT dbo.sp_701_log(product, model, signal, forced_rt, min_return, topN,
                            cum_net, cum_alt, inTopNet, inTopAlt, pass_net, pass_alt, ok, reason)
      VALUES(@product, @model, @signal, @rt, @min_return, @topN,
             @cum_net, @cum_alt, @inTopNet, @inTopAlt, @pass_net, @pass_alt, @ok, @reason);
      RETURN;
    END
    ELSE
    BEGIN
      IF NOT (@cum_net > @min_return) SET @reason = N'cum_net<=min';
      ELSE IF @inTopNet = 0           SET @reason = N'net_not_in_topN';
      ELSE                            SET @reason = N'net_fail';
      SET @ok = 0;
      IF @debug = 1 PRINT CONCAT('[701] FAIL (forced NET): ', @reason);
      INSERT dbo.sp_701_log(product, model, signal, forced_rt, min_return, topN,
                            cum_net, cum_alt, inTopNet, inTopAlt, pass_net, pass_alt, ok, reason)
      VALUES(@product, @model, @signal, @rt, @min_return, @topN,
             @cum_net, @cum_alt, @inTopNet, @inTopAlt, @pass_net, @pass_alt, @ok, @reason);
      RETURN;
    END
  END

  /* ---- auto-pick: pass if either side qualifies; prefer higher cum ---- */
  IF (@pass_alt = 1 OR @pass_net = 1)
  BEGIN
    SET @ok = 1;
    IF @pass_alt = 1 AND (@pass_net = 0 OR @cum_alt >= @cum_net)
      SET @reason = N'alt_topN(auto)';
    ELSE
      SET @reason = N'net_topN(auto)';

    IF @debug = 1 PRINT CONCAT('[701] PASS (auto): ', @reason);

    INSERT dbo.sp_701_log(product, model, signal, forced_rt, min_return, topN,
                          cum_net, cum_alt, inTopNet, inTopAlt, pass_net, pass_alt, ok, reason)
    VALUES(@product, @model, @signal, @rt, @min_return, @topN,
           @cum_net, @cum_alt, @inTopNet, @inTopAlt, @pass_net, @pass_alt, @ok, @reason);
    RETURN;
  END

  SET @ok = 0; SET @reason = N'no_top_side';
  IF @debug = 1 PRINT '[701] FAIL (auto): no_top_side';

  INSERT dbo.sp_701_log(product, model, signal, forced_rt, min_return, topN,
                        cum_net, cum_alt, inTopNet, inTopAlt, pass_net, pass_alt, ok, reason)
  VALUES(@product, @model, @signal, @rt, @min_return, @topN,
         @cum_net, @cum_alt, @inTopNet, @inTopAlt, @pass_net, @pass_alt, @ok, @reason);
END

CREATE   PROCEDURE [dbo].[sp_703_preview_tag_trade]
  @product    nvarchar(50),
  @model      nvarchar(50),
  @signal     nvarchar(50),          -- 'buy' | 'sell'
  @created    datetime2(3),          -- intended creation time
  @tradeable  int           OUTPUT,  -- 1/0
  @flip_trade int           OUTPUT,  -- 0=NET, 1=ALT, NULL=not tradeable
  @reason     nvarchar(32)  OUTPUT   -- reason code
AS
BEGIN
  SET NOCOUNT ON;

  /* ── logging helpers ───────────────────────────────────────────── */
  DECLARE @ts  varchar(23);
  DECLARE @msg nvarchar(4000);
  DECLARE @TAG nvarchar(16) = '''sp_703''';  -- literal quotes included

  /* start */
  SET @ts = CONVERT(varchar(23), GETDATE(), 121);
  SET @msg = @ts + N' ' + @TAG + N' start product=' + ISNULL(@product,N'<NULL>')
           + N' model=' + ISNULL(@model,N'<NULL>')
           + N' signal=' + ISNULL(@signal,N'<NULL>')
           + N' created=' + CONVERT(nvarchar(23), @created, 121);
  RAISERROR(@msg, 10, 1) WITH NOWAIT;

  /* defaults */
  SET @tradeable = 0;
  SET @flip_trade = NULL;
  SET @reason = N'init';

  /* ---- single kill switch ---- */
  DECLARE @skip_703 int =
    TRY_CAST((SELECT config_value FROM dbo.config WITH (NOLOCK)
              WHERE config_name='skip_703') AS int);

  IF ISNULL(@skip_703,0)=1
  BEGIN
    SET @tradeable=0; SET @flip_trade=NULL; SET @reason=N'skip_703';

    SET @ts = CONVERT(varchar(23), GETDATE(), 121);
    SET @msg = @ts + N' ' + @TAG + N' kill-switch active: skip_703=1 → not tradeable';
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    RETURN;
  END

  /* ---- config: threshold & Top-N ---- */
  DECLARE @threshold decimal(38,8) =
    TRY_CAST((SELECT config_value FROM dbo.config WITH (NOLOCK)
              WHERE config_name='701_min_return') AS decimal(38,8));
  IF @threshold IS NULL SET @threshold = 0;

  DECLARE @topN int =
    TRY_CAST((SELECT config_value FROM dbo.config WITH (NOLOCK)
              WHERE config_name='701_top_return_range') AS int);
  IF @topN IS NULL OR @topN <= 0 SET @topN = 5;

  SET @ts = CONVERT(varchar(23), GETDATE(), 121);
  SET @msg = @ts + N' ' + @TAG + N' config threshold='
           + CONVERT(nvarchar(64), @threshold) + N' topN='
           + CONVERT(nvarchar(32), @topN);
  RAISERROR(@msg, 10, 1) WITH NOWAIT;

  /* ---- as-of returns for THIS model at @created ---- */
  DECLARE @net_at decimal(38,8), @alt_at decimal(38,8);

  SELECT TOP (1)
         @net_at = msn.net_return_sum,
         @alt_at = msn.alt_net_return_sum
  FROM dbo.tbl_model_signal_net AS msn WITH (NOLOCK)
  WHERE msn.product=@product AND msn.model=@model AND msn.signal=@signal
    AND msn.update_time <= @created
  ORDER BY msn.update_time DESC;

  SET @ts = CONVERT(varchar(23), GETDATE(), 121);
  SET @msg = @ts + N' ' + @TAG + N' as-of net_at='
           + COALESCE(CONVERT(nvarchar(64), @net_at), N'<NULL>')
           + N' alt_at=' + COALESCE(CONVERT(nvarchar(64), @alt_at), N'<NULL>');
  RAISERROR(@msg, 10, 1) WITH NOWAIT;

  IF @net_at IS NULL AND @alt_at IS NULL
  BEGIN
    SET @tradeable=0; SET @flip_trade=NULL; SET @reason=N'no_snapshot';

    SET @ts = CONVERT(varchar(23), GETDATE(), 121);
    SET @msg = @ts + N' ' + @TAG + N' decision: no_snapshot → not tradeable';
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    RETURN;
  END

  /* ---- get latest values for ALL models (same product+signal) as-of @created ---- */
  DECLARE @latest TABLE(
    model   nvarchar(50) NOT NULL PRIMARY KEY,
    val_net decimal(38,8) NULL,
    val_alt decimal(38,8) NULL
  );

  INSERT INTO @latest(model, val_net, val_alt)
  SELECT m.model,
         (SELECT TOP (1) x.net_return_sum
            FROM dbo.tbl_model_signal_net x WITH (NOLOCK)
           WHERE x.product=@product AND x.signal=@signal AND x.model=m.model
             AND x.update_time <= @created
           ORDER BY x.update_time DESC) AS val_net,
         (SELECT TOP (1) y.alt_net_return_sum
            FROM dbo.tbl_model_signal_net y WITH (NOLOCK)
           WHERE y.product=@product AND y.signal=@signal AND y.model=m.model
             AND y.update_time <= @created
           ORDER BY y.update_time DESC) AS val_alt
  FROM (SELECT DISTINCT model
          FROM dbo.tbl_model_signal_net WITH (NOLOCK)
         WHERE product=@product AND signal=@signal) AS m;

  /* ---- rank by NET and ALT (only values > threshold) ---- */
  DECLARE @ranked TABLE(
    model   nvarchar(50) NOT NULL PRIMARY KEY,
    val_net decimal(38,8) NULL,
    val_alt decimal(38,8) NULL,
    rn_net  int NULL,
    rn_alt  int NULL
  );

  INSERT INTO @ranked(model, val_net, val_alt, rn_net, rn_alt)
  SELECT
    l.model,
    l.val_net,
    l.val_alt,
    CASE WHEN l.val_net IS NOT NULL AND l.val_net > @threshold
         THEN ROW_NUMBER() OVER (ORDER BY l.val_net DESC) END AS rn_net,
    CASE WHEN l.val_alt IS NOT NULL AND l.val_alt > @threshold
         THEN ROW_NUMBER() OVER (ORDER BY l.val_alt DESC) END AS rn_alt
  FROM @latest AS l;

  /* ---- eligibility decision (NET/ALT) ---- */
  DECLARE @is_top_net bit = CAST(CASE WHEN EXISTS (
      SELECT 1 FROM @ranked r
      WHERE r.model=@model AND r.rn_net IS NOT NULL AND r.rn_net <= @topN
  ) THEN 1 ELSE 0 END AS bit);

  DECLARE @is_top_alt bit = CAST(CASE WHEN EXISTS (
      SELECT 1 FROM @ranked r
      WHERE r.model=@model AND r.rn_alt IS NOT NULL AND r.rn_alt <= @topN
  ) THEN 1 ELSE 0 END AS bit);

  DECLARE @pass_net bit = CASE WHEN @net_at IS NOT NULL AND @net_at > @threshold AND @is_top_net=1 THEN 1 ELSE 0 END;
  DECLARE @pass_alt bit = CASE WHEN @alt_at IS NOT NULL AND @alt_at > @threshold AND @is_top_alt=1 THEN 1 ELSE 0 END;

  SET @ts = CONVERT(varchar(23), GETDATE(), 121);
  SET @msg = @ts + N' ' + @TAG + N' ranking pass_net='
           + CONVERT(nvarchar(10), @pass_net) + N' pass_alt=' + CONVERT(nvarchar(10), @pass_alt)
           + N' is_top_net=' + CONVERT(nvarchar(10), @is_top_net)
           + N' is_top_alt=' + CONVERT(nvarchar(10), @is_top_alt);
  RAISERROR(@msg, 10, 1) WITH NOWAIT;

  IF @pass_net=0 AND @pass_alt=0
  BEGIN
    IF (ISNULL(@net_at,-1e38) <= @threshold) AND (ISNULL(@alt_at,-1e38) <= @threshold)
      SET @reason = N'below_threshold';
    ELSE
      SET @reason = N'not_in_topN';
    SET @tradeable = 0;
    SET @flip_trade = NULL;

    SET @ts = CONVERT(varchar(23), GETDATE(), 121);
    SET @msg = @ts + N' ' + @TAG + N' decision: tradeable=0 reason=' + @reason;
    RAISERROR(@msg, 10, 1) WITH NOWAIT;

    RETURN;
  END

  /* one or both sides passed → pick side + set reason */
  IF @pass_net=1 AND @pass_alt=0
  BEGIN
    SET @tradeable = 1;
    SET @flip_trade = 0;            -- NET
    SET @reason = N'topN_NET';
  END
  ELSE IF @pass_net=0 AND @pass_alt=1
  BEGIN
    SET @tradeable = 1;
    SET @flip_trade = 1;            -- ALT
    SET @reason = N'topN_ALT';
  END
  ELSE
  BEGIN
    -- both passed: pick stronger as-of value
    SET @tradeable = 1;
    IF ISNULL(@net_at,-1e38) >= ISNULL(@alt_at,-1e38)
    BEGIN
      SET @flip_trade = 0;
      SET @reason = N'topN_BOTH_NET';
    END
    ELSE
    BEGIN
      SET @flip_trade = 1;
      SET @reason = N'topN_BOTH_ALT';
    END
  END

  SET @ts = CONVERT(varchar(23), GETDATE(), 121);
  SET @msg = @ts + N' ' + @TAG + N' decision pre-cap: tradeable='
           + CONVERT(nvarchar(10), @tradeable)
           + N' flip_trade=' + COALESCE(CONVERT(nvarchar(10), @flip_trade), N'<NULL>')
           + N' reason=' + @reason;
  RAISERROR(@msg, 10, 1) WITH NOWAIT;

  /* ===========================================================
     CAPS: only apply if currently tradeable
     =========================================================== */
  IF @tradeable = 1
  BEGIN
    /* per product+signal cap */
    DECLARE @cap_ps int =
      TRY_CAST((SELECT config_value FROM dbo.config WITH (NOLOCK)
                WHERE config_name='703_cap_open_per_product_signal') AS int);
    IF @cap_ps IS NULL SET @cap_ps = 0;  -- 0 = disabled

    IF @cap_ps > 0
    BEGIN
      DECLARE @open_ps int =
        (SELECT COUNT(*)
         FROM dbo.combined_trades_open WITH (NOLOCK)
         WHERE product = @product
           AND signal  = @signal
           AND tradeable <> 0              -- ONLY CHANGE MADE HERE
           AND trade_reason = @reason);

      SET @ts = CONVERT(varchar(23), GETDATE(), 121);
      SET @msg = @ts + N' ' + @TAG + N' cap_ps check: open_ps='
               + CONVERT(nvarchar(32), @open_ps) + N' cap_ps=' + CONVERT(nvarchar(32), @cap_ps);
      RAISERROR(@msg, 10, 1) WITH NOWAIT;

      IF @open_ps >= @cap_ps
      BEGIN
        SET @tradeable  = 0;
        SET @flip_trade = NULL;
        SET @reason     = N'cap_reached_ps';

        SET @ts = CONVERT(varchar(23), GETDATE(), 121);
        SET @msg = @ts + N' ' + @TAG + N' decision: product+signal cap reached → tradeable=0';
        RAISERROR(@msg, 10, 1) WITH NOWAIT;

        RETURN;
      END
    END

    /* per model+signal cap */
    DECLARE @cap_ms int =
      TRY_CAST((SELECT config_value FROM dbo.config WITH (NOLOCK)
                WHERE config_name='703_cap_open_per_model_signal') AS int);
    IF @cap_ms IS NULL SET @cap_ms = 0;  -- 0 = disabled

    IF @cap_ms > 0
    BEGIN
      DECLARE @open_ms int =
        (SELECT COUNT(*)
         FROM dbo.combined_trades_open WITH (NOLOCK)
         WHERE product = @product
           AND model   = @model
           AND signal  = @signal
           AND tradeable <> 0              -- ONLY CHANGE MADE HERE
           AND trade_reason = @reason);

      SET @ts = CONVERT(varchar(23), GETDATE(), 121);
      SET @msg = @ts + N' ' + @TAG + N' cap_ms check: open_ms='
               + CONVERT(nvarchar(32), @open_ms) + N' cap_ms=' + CONVERT(nvarchar(32), @cap_ms);
      RAISERROR(@msg, 10, 1) WITH NOWAIT;

      IF @open_ms >= @cap_ms
      BEGIN
        SET @tradeable  = 0;
        SET @flip_trade = NULL;
        SET @reason     = N'cap_reached_ms';

        SET @ts = CONVERT(varchar(23), GETDATE(), 121);
        SET @msg = @ts + N' ' + @TAG + N' decision: model+signal cap reached → tradeable=0';
        RAISERROR(@msg, 10, 1) WITH NOWAIT;

        RETURN;
      END
    END
  END

  /* final log */
  SET @ts = CONVERT(varchar(23), GETDATE(), 121);
  SET @msg = @ts + N' ' + @TAG + N' end tradeable='
           + CONVERT(nvarchar(10), @tradeable)
           + N' flip_trade=' + COALESCE(CONVERT(nvarchar(10), @flip_trade), N'<NULL>')
           + N' reason=' + @reason;
  RAISERROR(@msg, 10, 1) WITH NOWAIT;
END

create   PROCEDURE [dbo].[sp_703_preview_tag_trade_old]
  @product    nvarchar(50),
  @model      nvarchar(50),
  @signal     nvarchar(50),          -- 'buy' | 'sell'
  @created    datetime2(3),          -- intended creation time
  @tradeable  int           OUTPUT,  -- 1/0
  @flip_trade int           OUTPUT,  -- 0=NET, 1=ALT, NULL=not tradeable
  @reason     nvarchar(32)  OUTPUT   -- reason code
AS
BEGIN
  SET NOCOUNT ON;

  /* defaults */
  SET @tradeable = 0;
  SET @flip_trade = NULL;
  SET @reason = N'init';

  /* ---- single kill switch ---- */
  DECLARE @skip_703 int =
    TRY_CAST((SELECT config_value FROM dbo.config WITH (NOLOCK)
              WHERE config_name='skip_703') AS int);

  IF ISNULL(@skip_703,0)=1
  BEGIN
    SET @tradeable=0; SET @flip_trade=NULL; SET @reason=N'skip_703';
    RETURN;
  END

  /* ---- config: threshold & Top-N ---- */
  DECLARE @threshold decimal(38,8) =
    TRY_CAST((SELECT config_value FROM dbo.config WITH (NOLOCK)
              WHERE config_name='701_min_return') AS decimal(38,8));
  IF @threshold IS NULL SET @threshold = 0;

  DECLARE @topN int =
    TRY_CAST((SELECT config_value FROM dbo.config WITH (NOLOCK)
              WHERE config_name='701_top_return_range') AS int);
  IF @topN IS NULL OR @topN <= 0 SET @topN = 5;

  /* ---- as-of returns for THIS model at @created ---- */
  DECLARE @net_at decimal(38,8), @alt_at decimal(38,8);

  SELECT TOP (1)
         @net_at = msn.net_return_sum,
         @alt_at = msn.alt_net_return_sum
  FROM dbo.tbl_model_signal_net AS msn WITH (NOLOCK)
  WHERE msn.product=@product AND msn.model=@model AND msn.signal=@signal
    AND msn.update_time <= @created
  ORDER BY msn.update_time DESC;

  IF @net_at IS NULL AND @alt_at IS NULL
  BEGIN
    SET @tradeable=0; SET @flip_trade=NULL; SET @reason=N'no_snapshot';
    RETURN;
  END

  /* ---- rank all models (same product+signal) as-of @created ---- */
  ;WITH models AS (
      SELECT DISTINCT m.model
      FROM dbo.tbl_model_signal_net AS m WITH (NOLOCK)
      WHERE m.product=@product AND m.signal=@signal
  ),
  latest_vals AS (
      SELECT 
        m.model,
        (SELECT TOP (1) x.net_return_sum
         FROM dbo.tbl_model_signal_net x WITH (NOLOCK)
         WHERE x.product=@product AND x.signal=@signal AND x.model=m.model
           AND x.update_time <= @created
         ORDER BY x.update_time DESC) AS val_net,
        (SELECT TOP (1) y.alt_net_return_sum
         FROM dbo.tbl_model_signal_net y WITH (NOLOCK)
         WHERE y.product=@product AND y.signal=@signal AND y.model=m.model
           AND y.update_time <= @created
         ORDER BY y.update_time DESC) AS val_alt
      FROM models m
  ),
  ranked AS (
      SELECT
        lv.model,
        lv.val_net,
        lv.val_alt,
        CASE WHEN lv.val_net IS NOT NULL AND lv.val_net > @threshold
             THEN ROW_NUMBER() OVER (ORDER BY lv.val_net DESC) END AS rn_net,
        CASE WHEN lv.val_alt IS NOT NULL AND lv.val_alt > @threshold
             THEN ROW_NUMBER() OVER (ORDER BY lv.val_alt DESC) END AS rn_alt
      FROM latest_vals lv
  )
  SELECT 1 WHERE 1=1; -- no-op to terminate the CTE

  /* ---- eligibility decision (NET/ALT) ---- */
  DECLARE @is_top_net bit = CAST(CASE WHEN EXISTS (
      SELECT 1 FROM ranked r
      WHERE r.model=@model AND r.rn_net IS NOT NULL AND r.rn_net <= @topN
  ) THEN 1 ELSE 0 END AS bit);

  DECLARE @is_top_alt bit = CAST(CASE WHEN EXISTS (
      SELECT 1 FROM ranked r
      WHERE r.model=@model AND r.rn_alt IS NOT NULL AND r.rn_alt <= @topN
  ) THEN 1 ELSE 0 END AS bit);

  DECLARE @pass_net bit = CASE WHEN @net_at IS NOT NULL AND @net_at > @threshold AND @is_top_net=1 THEN 1 ELSE 0 END;
  DECLARE @pass_alt bit = CASE WHEN @alt_at IS NOT NULL AND @alt_at > @threshold AND @is_top_alt=1 THEN 1 ELSE 0 END;

  IF @pass_net=0 AND @pass_alt=0
  BEGIN
    IF (ISNULL(@net_at,-1e38) <= @threshold) AND (ISNULL(@alt_at,-1e38) <= @threshold)
      SET @reason = N'below_threshold';
    ELSE
      SET @reason = N'not_in_topN';
    SET @tradeable = 0;
    SET @flip_trade = NULL;
    RETURN;
  END

  /* one or both sides passed → pick side + set reason */
  IF @pass_net=1 AND @pass_alt=0
  BEGIN
    SET @tradeable = 1;
    SET @flip_trade = 0;            -- NET
    SET @reason = N'topN_NET';
  END
  ELSE IF @pass_net=0 AND @pass_alt=1
  BEGIN
    SET @tradeable = 1;
    SET @flip_trade = 1;            -- ALT
    SET @reason = N'topN_ALT';
  END
  ELSE
  BEGIN
    -- both passed: pick stronger as-of value
    SET @tradeable = 1;
    IF ISNULL(@net_at,-1e38) >= ISNULL(@alt_at,-1e38)
    BEGIN
      SET @flip_trade = 0;
      SET @reason = N'topN_BOTH_NET';
    END
    ELSE
    BEGIN
      SET @flip_trade = 1;
      SET @reason = N'topN_BOTH_ALT';
    END
  END

  /* ===========================================================
     CAPS: only apply if currently tradeable
     Counts are filtered by product + signal + trade_reason.
     (Model-cap also filters by model.)
     If open < cap  => keep tradeable=1
     If open >= cap => force tradeable=0, reason=cap_reached_*
     =========================================================== */
  IF @tradeable = 1
  BEGIN
    /* per product+signal cap */
    DECLARE @cap_ps int =
      TRY_CAST((SELECT config_value FROM dbo.config WITH (NOLOCK)
                WHERE config_name='703_cap_open_per_product_signal') AS int);
    IF @cap_ps IS NULL SET @cap_ps = 0;  -- 0 = disabled

    IF @cap_ps > 0
    BEGIN
      DECLARE @open_ps int =
        (SELECT COUNT(*)
         FROM dbo.combined_trades_open WITH (NOLOCK)
         WHERE product = @product
           AND signal  = @signal
           AND tradeable = 1
           AND trade_reason = @reason);

      IF @open_ps >= @cap_ps
      BEGIN
        SET @tradeable  = 0;
        SET @flip_trade = NULL;
        SET @reason     = N'cap_reached_ps';
        RETURN;
      END
    END

    /* per model+signal cap */
    DECLARE @cap_ms int =
      TRY_CAST((SELECT config_value FROM dbo.config WITH (NOLOCK)
                WHERE config_name='703_cap_open_per_model_signal') AS int);
    IF @cap_ms IS NULL SET @cap_ms = 0;  -- 0 = disabled

    IF @cap_ms > 0
    BEGIN
      DECLARE @open_ms int =
        (SELECT COUNT(*)
         FROM dbo.combined_trades_open WITH (NOLOCK)
         WHERE product = @product
           AND model   = @model
           AND signal  = @signal
           AND tradeable = 1
           AND trade_reason = @reason);

      IF @open_ms >= @cap_ms
      BEGIN
        SET @tradeable  = 0;
        SET @flip_trade = NULL;
        SET @reason     = N'cap_reached_ms';
        RETURN;
      END
    END
  END
END

CREATE PROCEDURE [dbo].[sp_800_exec_all]
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ts  NVARCHAR(23);
    DECLARE @msg NVARCHAR(4000);

    BEGIN TRY
        EXEC dbo.sp_800_ghost_close_by_reason;
    END TRY
    BEGIN CATCH
        SET @ts  = CONVERT(NVARCHAR(23), GETDATE(), 121);
        SET @msg = @ts + N' sp_800_ghost_close_by_reason ERROR'
                 + N' num='   + CONVERT(NVARCHAR(20), ERROR_NUMBER())
                 + N' sev='   + CONVERT(NVARCHAR(20), ERROR_SEVERITY())
                 + N' state=' + CONVERT(NVARCHAR(20), ERROR_STATE())
                 + N' line='  + CONVERT(NVARCHAR(20), ERROR_LINE())
                 + N' proc='  + ISNULL(ERROR_PROCEDURE(), N'NULL')
                 + N' msg='   + ERROR_MESSAGE();
        RAISERROR(@msg, 16, 1) WITH NOWAIT;
        RETURN;
    END CATCH;


    SET @ts  = CONVERT(NVARCHAR(23), GETDATE(), 121);
    SET @msg = @ts + N' sp_800_exec_all completed';
    RAISERROR(@msg, 10, 1) WITH NOWAIT;
END;

CREATE PROCEDURE [dbo].[sp_800_ghost_close_by_reason]
AS
BEGIN
    SET NOCOUNT ON;

    -- 1. Get the list of trade_reasons from the config table
    DECLARE @GhostCloseList NVARCHAR(MAX);
    SELECT @GhostCloseList = config_value
    FROM dbo.config
    WHERE config_name = 'ghost_close_list'; -- Reverted to config_name

    IF @GhostCloseList IS NULL OR LTRIM(RTRIM(@GhostCloseList)) = ''
    BEGIN
        PRINT 'No trade reasons found in config for key ''ghost_close_list''.';
        RETURN;
    END

    -- 2. Parse the comma-delimited list into a table variable
    DECLARE @TradeReasons TABLE (trade_reason NVARCHAR(255));
    INSERT INTO @TradeReasons (trade_reason)
    SELECT LTRIM(RTRIM(value))
    FROM STRING_SPLIT(@GhostCloseList, ',');

    -- 3. Get a list of GUIDs to be ghost-closed
    DECLARE @TradesToClose TABLE (guid UNIQUEIDENTIFIER);
    INSERT INTO @TradesToClose (guid)
    SELECT o.guid
    FROM dbo.combined_trades_open o
    INNER JOIN @TradeReasons tr ON o.trade_reason = tr.trade_reason
    WHERE o.tradeable > 0
      AND o.g_close_time IS NULL;

    -- 4. Loop through the GUIDs, check for flipped trades, and then execute the helper SP
    DECLARE @CurrentGUID UNIQUEIDENTIFIER;
    DECLARE @GuidStr NVARCHAR(36);
    DECLARE @FlippedTradeCount INT;

    -- Temp table to hold the result from the SP
    DECLARE @FlippedCountResult TABLE (FlippedTradeCount INT, Status VARCHAR(100));

    DECLARE cur CURSOR FOR
    SELECT guid FROM @TradesToClose;

    OPEN cur;
    FETCH NEXT FROM cur INTO @CurrentGUID;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @GuidStr = CONVERT(NVARCHAR(36), @CurrentGUID);
        PRINT 'Processing GUID: ' + @GuidStr;

        -- Clear the temp table and get the flipped trade count
        DELETE FROM @FlippedCountResult;
        INSERT INTO @FlippedCountResult (FlippedTradeCount, Status)
        EXEC dbo.sp_800_GetFlippedTradeCountByGUID @InputGUID = @CurrentGUID;

        SELECT @FlippedTradeCount = FlippedTradeCount FROM @FlippedCountResult;

        PRINT '... Flipped trade count: ' + CAST(@FlippedTradeCount AS VARCHAR(10));

        -- Only execute ghost close if there are profitable flipped trades
        IF @FlippedTradeCount > 0
        BEGIN
            PRINT '... Condition met. Executing sp_helper_ghost_close for GUID: ' + @GuidStr;
            BEGIN TRY
                EXEC dbo.sp_helper_ghost_close @trade_guid = @CurrentGUID;
                PRINT '... Successfully executed for GUID: ' + @GuidStr;
            END TRY
            BEGIN CATCH
                PRINT '... Error executing sp_helper_ghost_close for GUID: ' + @GuidStr;
                PRINT ERROR_MESSAGE();
            END CATCH
        END
        ELSE
        BEGIN
            PRINT '... Condition not met (FlippedTradeCount <= 0). Skipping ghost close.';
        END

        FETCH NEXT FROM cur INTO @CurrentGUID;
    END

    CLOSE cur;
    DEALLOCATE cur;

    PRINT 'Ghost close process completed.';
END

CREATE PROCEDURE dbo.sp_9000_GetTradeable_by_alt_net_return
    @model                   NVARCHAR(50),
    @signal                  NVARCHAR(10),
    @product                 NVARCHAR(50),
    @currentPrice            FLOAT,
    @use_top_performer_logic BIT         = 1,
    @IsTradeable             TINYINT     OUTPUT,
    @flip_trade              TINYINT     OUTPUT,
    @trade_reason            NVARCHAR(50) OUTPUT     -- NEW
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @modeFlag    TINYINT;
    SELECT @modeFlag = tradeable
      FROM dbo.product_forex
     WHERE model = @model;
    IF @modeFlag IS NULL SET @modeFlag = 0;

    SET @IsTradeable = 0;
    SET @flip_trade  = 0;
    SET @trade_reason = NULL;       -- initialize

    -- Mode 0: never tradeable
    IF @modeFlag = 0
        RETURN;

    -- Top-Performer (Mode 1 & 2)
    DECLARE @tp_avg_entry DECIMAL(18,6), @openCount INT;
    SELECT TOP 1
        @tp_avg_entry = avg_profitable_entry_price
    FROM dbo.vw_106_ModelPerformance_alt
    WHERE product = @product
    ORDER BY profitable_percent DESC, total_return DESC;

    IF @tp_avg_entry IS NOT NULL
       AND (
           (@signal = 'buy'  AND @currentPrice > @tp_avg_entry)
        OR (@signal = 'sell' AND @currentPrice < @tp_avg_entry)
       )
    BEGIN
        SELECT @openCount = COUNT(*)
          FROM dbo.combined_trades_open
         WHERE model     = @model
           AND signal    = @signal
           AND tradeable > 0;

        IF @openCount = 0
        BEGIN
            SET @IsTradeable = 1;
            SET @flip_trade  = 1;
            SET @trade_reason = N'TopPerformer';
        END
    END

    -- Fallback only in Mode 1 if still non-tradeable
    IF @modeFlag = 1
       AND @IsTradeable = 0
    BEGIN
        DECLARE
          @useCount     TINYINT,
          @latestAlt    FLOAT,
          @latestSignal NVARCHAR(10),
          @openCount2   INT;

        SELECT @useCount = use_trade_count
          FROM dbo.product_forex
         WHERE model = @model;

        IF @useCount = 1
        BEGIN
            SELECT TOP 1
                @latestAlt    = alt_net_return,
                @latestSignal = signal
            FROM dbo.combined_trades_closed
            WHERE model = @model
            ORDER BY last_update DESC;

            SELECT @openCount2 = COUNT(*)
              FROM dbo.combined_trades_open
             WHERE model     = @model
               AND signal    = @signal
               AND tradeable > 0;

            IF @latestSignal = @signal
               AND @latestAlt   > 0
               AND @openCount2  = 0
            BEGIN
                SET @IsTradeable = 1;
                SET @trade_reason = N'UseTradeCount';
            END
        END
    END
END;

CREATE PROCEDURE dbo.sp_9001_Helper_TradeSignal
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @TB0           INT,  -- TotalBuyClosed in latest block
        @PBC0          INT,  -- PositiveBuyClosed in latest block
        @TS0           INT,  -- TotalSellClosed in latest block
        @PSC0          INT,  -- PositiveSellClosed in latest block
        @TB1           INT,  -- TotalBuyClosed in prior block
        @PBC1          INT,  -- PositiveBuyClosed in prior block
        @TS1           INT,  -- TotalSellClosed in prior block
        @PSC1          INT,  -- PositiveSellClosed in prior block
        @TradeDirection VARCHAR(10);

    ;WITH Ranked AS (
        SELECT
            TotalBuyClosed,
            PositiveBuyClosed,
            TotalSellClosed,
            PositiveSellClosed,
            ROW_NUMBER() OVER (ORDER BY SnapshotTimestamp DESC) AS RN
        FROM dbo.vw_002_pos_buy_sell_count_gbp_tradepoint_signal_50
    )
    SELECT
        @TB0  = TotalBuyClosed,
        @PBC0 = PositiveBuyClosed,
        @TS0  = TotalSellClosed,
        @PSC0 = PositiveSellClosed
    FROM Ranked
    WHERE RN = 1;

    SELECT
        @TB1  = TotalBuyClosed,
        @PBC1 = PositiveBuyClosed,
        @TS1  = TotalSellClosed,
        @PSC1 = PositiveSellClosed
    FROM Ranked
    WHERE RN = 2;

    IF @TS1   > 0 
       AND @PSC1 = 0 
       AND @TB0  > 0 
       AND CAST(@PBC0 AS FLOAT)/@TB0 >= 0.8
    BEGIN
        SET @TradeDirection = 'BUY';
    END
    ELSE IF @TB1   > 0 
         AND @PBC1 = 0 
         AND @TS0  > 0 
         AND CAST(@PSC0 AS FLOAT)/@TS0 >= 0.8
    BEGIN
        SET @TradeDirection = 'SELL';
    END
    ELSE
    BEGIN
        SET @TradeDirection = 'HOLD';
    END

    SELECT @TradeDirection AS TradeDirection;
END

CREATE PROCEDURE [dbo].[sp_9004_SetTrailingStopLossOnProfit]
    @Model NVARCHAR(128)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @RowsAffected INT = 0;
    DECLARE @sp_name SYSNAME = N'sp_9004_SetTrailingStopLossOnProfit';
    DECLARE @nowtxt VARCHAR(23) = CONVERT(VARCHAR(23), GETDATE(), 121);

    IF @Model IS NULL OR LTRIM(RTRIM(@Model)) = N''
    BEGIN
        RAISERROR(N'[%s] %s: Parameter @Model is required.', 10, 1, @nowtxt, @sp_name) WITH NOWAIT;
        RETURN;
    END;

    -- 2025-10-29: NEXT VERSION NUMBER - Load configuration values
    DECLARE @ProfitProtectPercent DECIMAL(18, 8);
    DECLARE @ProfitProtectTrigger DECIMAL(18, 8);
    DECLARE @ProfitProtectionListRaw NVARCHAR(MAX);

    SELECT @ProfitProtectPercent = TRY_CAST(config_value AS DECIMAL(18, 8)) FROM dbo.config WHERE config_name = 'profit_protect_percent';
    SELECT @ProfitProtectTrigger = TRY_CAST(config_value AS DECIMAL(18, 8)) FROM dbo.config WHERE config_name = 'profit_protect_trigger';
    SELECT @ProfitProtectionListRaw = config_value FROM dbo.config WHERE config_name = 'profit_protection_list';

    DECLARE @ProtectPercentText NVARCHAR(32) = CONVERT(NVARCHAR(32), @ProfitProtectPercent);
    DECLARE @ProtectTriggerText NVARCHAR(32) = CONVERT(NVARCHAR(32), @ProfitProtectTrigger);

    IF @ProfitProtectPercent IS NULL OR @ProfitProtectPercent <= 0
    BEGIN
        RAISERROR(N'[%s] %s: Configuration ''profit_protect_percent'' is missing or invalid. Aborting.', 10, 1, @nowtxt, @sp_name) WITH NOWAIT;
        RETURN;
    END;

    IF @ProfitProtectTrigger IS NULL OR @ProfitProtectTrigger <= 0
    BEGIN
        RAISERROR(N'[%s] %s: Configuration ''profit_protect_trigger'' is missing or invalid. Aborting.', 10, 1, @nowtxt, @sp_name) WITH NOWAIT;
        RETURN;
    END;

    IF @ProfitProtectionListRaw IS NULL OR LTRIM(RTRIM(@ProfitProtectionListRaw)) = N''
    BEGIN
        RAISERROR(N'[%s] %s: Configuration ''profit_protection_list'' is missing or empty. Aborting.', 10, 1, @nowtxt, @sp_name) WITH NOWAIT;
        RETURN;
    END;

    -- Parse profit_protection_list into a temporary table
    IF OBJECT_ID('tempdb..#ProfitProtectionTradeReasons') IS NOT NULL DROP TABLE #ProfitProtectionTradeReasons;
    CREATE TABLE #ProfitProtectionTradeReasons (trade_reason NVARCHAR(64) PRIMARY KEY);

    INSERT INTO #ProfitProtectionTradeReasons (trade_reason)
    SELECT TRIM(REPLACE(value, '''', '')) -- Trim whitespace and remove single quotes for robust matching
    FROM STRING_SPLIT(@ProfitProtectionListRaw, ',')
    WHERE LTRIM(RTRIM(value)) <> '';

    IF NOT EXISTS (SELECT 1 FROM #ProfitProtectionTradeReasons)
    BEGIN
        RAISERROR(N'[%s] %s: No valid trade reasons found in ''profit_protection_list''. Aborting.', 10, 1, @nowtxt, @sp_name) WITH NOWAIT;
        RETURN;
    END;

    RAISERROR(N'[%s] %s: Config loaded for model ''%s'': Percent=%s, Trigger=%s, List=''%s''.', 10, 1, @nowtxt, @sp_name, @Model, @ProtectPercentText, @ProtectTriggerText, @ProfitProtectionListRaw) WITH NOWAIT;

    -- Update target_loss for open trades that meet the criteria
    UPDATE cto
    SET
        cto.target_loss = (cto.max_net_return * @ProfitProtectPercent / 100) -- 2025-10-31: Corrected logic to set floor directly
    FROM

        dbo.combined_trades_open cto
    INNER JOIN
        #ProfitProtectionTradeReasons pptr ON cto.trade_reason = pptr.trade_reason
    WHERE

        cto.model = @Model

        AND cto.max_net_return >= @ProfitProtectTrigger -- 2025-10-31: Changed trigger to use max_net_return
        AND cto.max_net_return IS NOT NULL AND cto.max_net_return > 0 -- Ensure max_net_return is valid
        AND (
            cto.target_loss IS NULL
            OR
            -- Only trail up: new calculated target_loss must be HIGHER than current
            (cto.max_net_return * @ProfitProtectPercent / 100) > cto.target_loss -- 2025-10-31: Updated trailing check
        );

    SET @RowsAffected = @@ROWCOUNT;

    RAISERROR(N'[%s] %s: Adjusted trailing target_loss for %d open trade(s) for model ''%s''.', 10, 1, @nowtxt, @sp_name, @RowsAffected, @Model) WITH NOWAIT;



    IF OBJECT_ID('tempdb..#ProfitProtectionTradeReasons') IS NOT NULL DROP TABLE #ProfitProtectionTradeReasons;

END

CREATE PROCEDURE [dbo].[sp_9006_DeleteOutlierCombinedTradesClosed]
    @ReturnLimit DECIMAL(18,2) = 5000   -- absolute net_return cut-off; adjust if required
AS
BEGIN
    SET NOCOUNT ON;

    DELETE FROM tradedb.dbo.combined_trades_closed
    WHERE net_return >  @ReturnLimit
       OR net_return < -@ReturnLimit;
END;

CREATE PROCEDURE [dbo].[sp_9008_DeleteOldTradesOpen]
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    BEGIN TRY
        -----------------------------------------------------------------
        -- Delete from combined_trades_open
        -----------------------------------------------------------------
        DELETE
          FROM dbo.combined_trades_open
         WHERE created < CAST(GETDATE() AS DATE);

        DECLARE @deletedOpen INT = @@ROWCOUNT;
