END;

CREATE PROCEDURE [dbo].[sp_9009_ScanOpenTradeableProfitAndClose]
    -- @Signal NVARCHAR(10),        -- 'Buy' | 'Sell' | 'B' | 'S' | 'B/S' -- Removed as it was not used in the procedure logic. (2025-11-12)
    @ShouldClose BIT = 0      -- 1 = close trades, 0 = do nothing (now an input parameter with default)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @threshold     DECIMAL(19,4),
        @total_profit  DECIMAL(19,4),
        @logproc       NVARCHAR(32) = N'sp_003_Close',
        @nowtxt        VARCHAR(23)  = CONVERT(VARCHAR(23), GETDATE(), 121);

    SET @ShouldClose = 0;

    /* 1) Threshold from config */
    SELECT @threshold = TRY_CONVERT(DECIMAL(19,4), config_value)
    FROM dbo.config
    WHERE config_name = 'scan_open_tradeable_profit_and_close';

    /* 2) If config <= 0, exit */
    IF ISNULL(@threshold, 0) <= 0
        GOTO EndProcedure; -- Jump to the end to return result set

    /* 3) Build contributions (flip_trade -> net_return vs alt_net_return) */
    WITH src AS (
        SELECT
            o.guid,
            signal = UPPER(o.signal),
            actual_net =
                CASE
                    WHEN o.flip_trade IS NULL THEN NULL
                    WHEN o.flip_trade = 0     THEN TRY_CONVERT(DECIMAL(19,4), o.net_return)
                    WHEN o.flip_trade = 1     THEN TRY_CONVERT(DECIMAL(19,4), o.alt_net_return)
                END
        FROM dbo.combined_trades_open AS o
        WHERE o.tradeable > 0
          AND UPPER(o.signal) IN ('B','BUY','S','SELL')
    )
    SELECT @total_profit = SUM(actual_net)
    FROM src
    WHERE actual_net IS NOT NULL;

    /* 4) Compare to threshold */
    IF ISNULL(@total_profit, 0) > @threshold
    BEGIN
        SET @ShouldClose = 1;

        /* Logging: trigger summary */
        IF OBJECT_ID('dbo.proc_log','U') IS NOT NULL
        BEGIN
            INSERT INTO dbo.proc_log (ts,[proc],details)
            VALUES (
                GETDATE(), @logproc,
                CONCAT(@nowtxt,' ',@logproc,' profit_scan BOTH_SIDES total=',
                       TRY_CONVERT(varchar(32),@total_profit),
                       ' threshold=',TRY_CONVERT(varchar(32),@threshold),
                       ' should_close=1')
            );
        END
        ELSE
        BEGIN
            SELECT CONCAT(@nowtxt,' ',@logproc,' profit_scan BOTH_SIDES total=',
                          TRY_CONVERT(varchar(32),@total_profit),
                          ' threshold=',TRY_CONVERT(varchar(32),@threshold),
                          ' should_close=1') AS log_line;
        END

    END
    ELSE
    BEGIN
        /* Logging: no trigger */
        IF OBJECT_ID('dbo.proc_log','U') IS NOT NULL
        BEGIN
            INSERT INTO dbo.proc_log (ts,[proc],details)
            VALUES (
                GETDATE(), @logproc,
                CONCAT(@nowtxt,' ',@logproc,' profit_scan BOTH_SIDES total=',
                       TRY_CONVERT(varchar(32),ISNULL(@total_profit,0)),
                       ' threshold=',TRY_CONVERT(varchar(32),@threshold),
                       ' should_close=0')
            );
        END
        ELSE
        BEGIN
            SELECT CONCAT(@nowtxt,' ',@logproc,' profit_scan BOTH_SIDES total=',
                          TRY_CONVERT(varchar(32),ISNULL(@total_profit,0)),
                          ' threshold=',TRY_CONVERT(varchar(32),@threshold),
                          ' should_close=0') AS log_line;
        END

    END

EndProcedure:
    SELECT @ShouldClose AS ShouldCloseResult;

END;

-- Takes a snapshot of vw_200_zone_distribution_latest every run
CREATE   PROCEDURE dbo.sp_9101_snapshot_zone_distribution
AS
BEGIN
    SET NOCOUNT ON;

    ----------------------------------------------------------------------
    -- 1) Ensure destination table exists (with latest layout)
    ----------------------------------------------------------------------
    IF NOT EXISTS (
        SELECT 1
        FROM sys.tables
        WHERE name = 'zone_distribution_snapshots'
          AND schema_id = SCHEMA_ID('dbo')
    )
    BEGIN
        CREATE TABLE dbo.zone_distribution_snapshots
        (
            snapshot_time   DATETIME2      NOT NULL DEFAULT SYSUTCDATETIME(),
            product         NVARCHAR(50)   NOT NULL,

            -- SELL zones first
            s_R9 INT NULL, s_R5 INT NULL, s_R4 INT NULL, s_R3 INT NULL, s_R2 INT NULL, s_R1 INT NULL,
            s_G1 INT NULL, s_G2 INT NULL, s_G3 INT NULL, s_G4 INT NULL, s_G5 INT NULL, s_G9 INT NULL,

            -- Mid price (from latest quote)
            latest_price    DECIMAL(18,9)  NULL,

            -- BUY zones
            b_R9 INT NULL, b_R5 INT NULL, b_R4 INT NULL, b_R3 INT NULL, b_R2 INT NULL, b_R1 INT NULL,
            b_G1 INT NULL, b_G2 INT NULL, b_G3 INT NULL, b_G4 INT NULL, b_G5 INT NULL, b_G9 INT NULL
        );

        CREATE INDEX IX_zone_snapshots_time_product
            ON dbo.zone_distribution_snapshots (snapshot_time, product);
    END
    ELSE
    BEGIN
        -- Add any missing columns to align with the latest view layout
        IF COL_LENGTH('dbo.zone_distribution_snapshots','s_R9') IS NULL  ALTER TABLE dbo.zone_distribution_snapshots ADD s_R9 INT NULL;
        IF COL_LENGTH('dbo.zone_distribution_snapshots','s_R5') IS NULL  ALTER TABLE dbo.zone_distribution_snapshots ADD s_R5 INT NULL;
        IF COL_LENGTH('dbo.zone_distribution_snapshots','s_R4') IS NULL  ALTER TABLE dbo.zone_distribution_snapshots ADD s_R4 INT NULL;
        IF COL_LENGTH('dbo.zone_distribution_snapshots','s_R3') IS NULL  ALTER TABLE dbo.zone_distribution_snapshots ADD s_R3 INT NULL;
        IF COL_LENGTH('dbo.zone_distribution_snapshots','s_R2') IS NULL  ALTER TABLE dbo.zone_distribution_snapshots ADD s_R2 INT NULL;
        IF COL_LENGTH('dbo.zone_distribution_snapshots','s_R1') IS NULL  ALTER TABLE dbo.zone_distribution_snapshots ADD s_R1 INT NULL;

