        IF COL_LENGTH('dbo.zone_distribution_snapshots','b_G5') IS NULL  ALTER TABLE dbo.zone_distribution_snapshots ADD b_G5 INT NULL;
        IF COL_LENGTH('dbo.zone_distribution_snapshots','b_G9') IS NULL  ALTER TABLE dbo.zone_distribution_snapshots ADD b_G9 INT NULL;
    END

    ----------------------------------------------------------------------
    -- 2) Append snapshot (UTC timestamp) from the latest view
    ----------------------------------------------------------------------
    INSERT INTO dbo.zone_distribution_snapshots
    (
        snapshot_time,
        product,
        s_R9, s_R5, s_R4, s_R3, s_R2, s_R1,
        s_G1, s_G2, s_G3, s_G4, s_G5, s_G9,
