        b_G1, b_G2, b_G3, b_G4, b_G5, b_G9
    FROM dbo.vw_200_zone_distribution_latest;

    PRINT CONCAT('Zone snapshot appended at ', CONVERT(VARCHAR(23), SYSUTCDATETIME(), 121));
END

	CREATE PROCEDURE dbo.sp_alterdiagram
	(
		@diagramname 	sysname,
		@owner_id	int	= null,
		@version 	int,
		@definition 	varbinary(max)
	)
	WITH EXECUTE AS 'dbo'
	AS
	BEGIN
		set nocount on
	
		declare @theId 			int
		declare @retval 		int
		declare @IsDbo 			int
		
		declare @UIDFound 		int
		declare @DiagId			int
		declare @ShouldChangeUID	int
	
		if(@diagramname is null)
		begin
			RAISERROR ('Invalid ARG', 16, 1)
			return -1
		end
	
		execute as caller;
		select @theId = DATABASE_PRINCIPAL_ID();	 
		select @IsDbo = IS_MEMBER(N'db_owner'); 
		if(@owner_id is null)
			select @owner_id = @theId;
		revert;
	
		select @ShouldChangeUID = 0
		select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
		
		if(@DiagId IS NULL or (@IsDbo = 0 and @theId <> @UIDFound))
		begin
			RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1);
			return -3
		end
	
		if(@IsDbo <> 0)
		begin
			if(@UIDFound is null or USER_NAME(@UIDFound) is null) -- invalid principal_id
			begin
				select @ShouldChangeUID = 1 ;
			end
		end

		-- update dds data			
		update dbo.sysdiagrams set definition = @definition where diagram_id = @DiagId ;

		-- change owner
		if(@ShouldChangeUID = 1)
			update dbo.sysdiagrams set principal_id = @theId where diagram_id = @DiagId ;

		-- update dds version
		if(@version is not null)
			update dbo.sysdiagrams set version = @version where diagram_id = @DiagId ;

		return 0
	END

CREATE   PROCEDURE dbo.sp_backfill_snapshot_pos_net_return_all
    @date_from DATE = NULL,
    @date_to   DATE = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @snapshots TABLE (snapshotTime DATETIME)
    INSERT INTO @snapshots
    SELECT DISTINCT snapshotTime
    FROM dbo.combined_trades_open_snapshot
    WHERE CAST(snapshotTime AS DATE) != CAST(GETDATE() AS DATE)
      AND (@date_from IS NULL OR CAST(snapshotTime AS DATE) >= @date_from)
      AND (@date_to   IS NULL OR CAST(snapshotTime AS DATE) <= @date_to)
    ORDER BY snapshotTime;

    DECLARE @t DATETIME;
    DECLARE @cnt INT = 0;

    DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
        SELECT snapshotTime FROM @snapshots ORDER BY snapshotTime;

    OPEN cur;
    FETCH NEXT FROM cur INTO @t;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        UPDATE s
        SET
            s.pos_net_return_buy  = agg.buy_win_pct,
            s.pos_net_return_sell = agg.sell_win_pct,
            s.buy_count           = agg.buy_cnt,
            s.sell_count          = agg.sell_cnt
        FROM dbo.combined_trades_open_snapshot s
        JOIN (
            SELECT product,
                SUM(CASE WHEN signal = 'BUY'  THEN 1 ELSE 0 END) AS buy_cnt,
                SUM(CASE WHEN signal = 'SELL' THEN 1 ELSE 0 END) AS sell_cnt,
                CAST(ROUND(100.0 * SUM(CASE WHEN signal = 'BUY'  AND net_return > 0 THEN 1.0 ELSE 0 END)
                    / NULLIF(SUM(CASE WHEN signal = 'BUY'  THEN 1.0 ELSE 0 END), 0), 0) AS TINYINT) AS buy_win_pct,
                CAST(ROUND(100.0 * SUM(CASE WHEN signal = 'SELL' AND net_return > 0 THEN 1.0 ELSE 0 END)
                    / NULLIF(SUM(CASE WHEN signal = 'SELL' THEN 1.0 ELSE 0 END), 0), 0) AS TINYINT) AS sell_win_pct
            FROM dbo.combined_trades_open_snapshot
            WHERE snapshotTime = @t
            GROUP BY product
        ) agg ON agg.product = s.product
        WHERE s.snapshotTime = @t;

        SET @cnt = @cnt + 1;
        IF @cnt % 1000 = 0
            RAISERROR('Processed %d snapshots...', 10, 1, @cnt) WITH NOWAIT;

        FETCH NEXT FROM cur INTO @t;
    END

    CLOSE cur;
    DEALLOCATE cur;

    RAISERROR('Backfill complete. Total snapshot ticks processed: %d', 10, 1, @cnt) WITH NOWAIT;
END

CREATE   PROCEDURE dbo.sp_CaptureProductSignalSnapshot
    @BlockSizeMinutes INT = 5,
    @ModelName VARCHAR(100) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @BlockEndTime DATETIME;
    DECLARE @BlockStartTime DATETIME;
    DECLARE @OverallBlockLatestPrice DECIMAL(18, 5);
    DECLARE @CurrentSnapshotTime DATETIME = GETDATE();

    IF OBJECT_ID('tempdb..#BlockDataTemp') IS NOT NULL
        DROP TABLE #BlockDataTemp;

    BEGIN TRY
        SELECT @BlockEndTime = MAX(CombinedLastUpdate)
        FROM (
            SELECT MAX(last_update) AS CombinedLastUpdate
            FROM dbo.combined_trades_open
            WHERE
               (@ModelName IS NULL OR CAST(model AS VARCHAR(MAX)) = @ModelName)
               AND CAST(model AS VARCHAR(MAX)) NOT LIKE 'DNA[_]%'
            UNION ALL
            SELECT MAX(last_update) AS CombinedLastUpdate
            FROM dbo.combined_trades_closed
            WHERE
               (@ModelName IS NULL OR CAST(model AS VARCHAR(MAX)) = @ModelName)
               AND CAST(model AS VARCHAR(MAX)) NOT LIKE 'DNA[_]%'
        ) AS MaxTimeFinder
        WHERE CombinedLastUpdate IS NOT NULL;

        IF @BlockEndTime IS NULL
        BEGIN
            PRINT 'Could not determine BlockEndTime. No matching trades found in open or closed tables for the specified filters. No snapshot taken.';
             IF OBJECT_ID('tempdb..#BlockDataTemp') IS NOT NULL DROP TABLE #BlockDataTemp;
            RETURN 0;
        END
        SET @BlockStartTime = DATEADD(minute, -@BlockSizeMinutes, @BlockEndTime);

        ;WITH BlockDataCTE AS (
             SELECT
                'open' AS trade_status, signal, net_return, entry_price, last_update, latest_price, product, model
            FROM dbo.combined_trades_open
            WHERE last_update >= @BlockStartTime AND last_update < @BlockEndTime
              AND (@ModelName IS NULL OR CAST(model AS VARCHAR(MAX)) = @ModelName)
              AND CAST(model AS VARCHAR(MAX)) NOT LIKE 'DNA[_]%'
            UNION ALL
            SELECT
                'closed' AS trade_status, signal, net_return, entry_price, last_update, latest_price, product, model
            FROM dbo.combined_trades_closed
            WHERE last_update >= @BlockStartTime AND last_update < @BlockEndTime
              AND (@ModelName IS NULL OR CAST(model AS VARCHAR(MAX)) = @ModelName)
              AND CAST(model AS VARCHAR(MAX)) NOT LIKE 'DNA[_]%'
        )
        SELECT
            trade_status, signal, net_return, entry_price, last_update, latest_price,
            CAST(product AS VARCHAR(MAX)) AS product,
            CAST(model AS VARCHAR(MAX)) AS model
        INTO #BlockDataTemp
        FROM BlockDataCTE;

        IF EXISTS (SELECT 1 FROM #BlockDataTemp)
        BEGIN
            SELECT TOP 1 @OverallBlockLatestPrice = latest_price
            FROM #BlockDataTemp
            ORDER BY last_update DESC;
        END
        ELSE
        BEGIN
            SET @OverallBlockLatestPrice = NULL;
            PRINT 'No trade data found within the calculated block window. Snapshot will contain zeros.';
        END

        INSERT INTO dbo.product_signal_snapshot (
            SnapshotTimestamp, Product, BlockStartTime, BlockEndTime, BlockLatestPrice,
            TotalBuyOpen, PositiveBuyOpen, PositiveValueBuyOpen, AvgPriceBuyOpen,
            TotalSellOpen, PositiveSellOpen, PositiveValueSellOpen, AvgPriceSellOpen,
            TotalBuyClosed, PositiveBuyClosed, PositiveValueBuyClosed, AvgPriceBuyClosed,
            TotalSellClosed, PositiveSellClosed, PositiveValueSellClosed, AvgPriceSellClosed
        )
        SELECT
            @CurrentSnapshotTime,
            product,
            @BlockStartTime,
            @BlockEndTime,
            ISNULL(@OverallBlockLatestPrice, (SELECT TOP 1 entry_price FROM #BlockDataTemp ORDER BY last_update DESC)),

            SUM(CASE WHEN trade_status = 'open' AND LOWER(TRIM(ISNULL(signal,''))) = 'buy' THEN 1 ELSE 0 END),
            SUM(CASE WHEN trade_status = 'open' AND LOWER(TRIM(ISNULL(signal,''))) = 'buy' AND net_return > 0 THEN 1 ELSE 0 END),
            ISNULL(SUM(CASE WHEN trade_status = 'open' AND LOWER(TRIM(ISNULL(signal,''))) = 'buy' AND net_return > 0 THEN net_return ELSE 0 END), 0),
            AVG(CASE WHEN trade_status = 'open' AND LOWER(TRIM(ISNULL(signal,''))) = 'buy' AND net_return > 0 THEN entry_price ELSE NULL END),

            SUM(CASE WHEN trade_status = 'open' AND LOWER(TRIM(ISNULL(signal,''))) = 'sell' THEN 1 ELSE 0 END),
            SUM(CASE WHEN trade_status = 'open' AND LOWER(TRIM(ISNULL(signal,''))) = 'sell' AND net_return > 0 THEN 1 ELSE 0 END),
            ISNULL(SUM(CASE WHEN trade_status = 'open' AND LOWER(TRIM(ISNULL(signal,''))) = 'sell' AND net_return > 0 THEN net_return ELSE 0 END), 0),
            AVG(CASE WHEN trade_status = 'open' AND LOWER(TRIM(ISNULL(signal,''))) = 'sell' AND net_return > 0 THEN entry_price ELSE NULL END),

            SUM(CASE WHEN trade_status = 'closed' AND LOWER(TRIM(ISNULL(signal,''))) = 'buy' THEN 1 ELSE 0 END),
            SUM(CASE WHEN trade_status = 'closed' AND LOWER(TRIM(ISNULL(signal,''))) = 'buy' AND net_return > 0 THEN 1 ELSE 0 END),
            ISNULL(SUM(CASE WHEN trade_status = 'closed' AND LOWER(TRIM(ISNULL(signal,''))) = 'buy' AND net_return > 0 THEN net_return ELSE 0 END), 0),
            AVG(CASE WHEN trade_status = 'closed' AND LOWER(TRIM(ISNULL(signal,''))) = 'buy' AND net_return > 0 THEN entry_price ELSE NULL END),

            SUM(CASE WHEN trade_status = 'closed' AND LOWER(TRIM(ISNULL(signal,''))) = 'sell' THEN 1 ELSE 0 END),
            SUM(CASE WHEN trade_status = 'closed' AND LOWER(TRIM(ISNULL(signal,''))) = 'sell' AND net_return > 0 THEN 1 ELSE 0 END),
            ISNULL(SUM(CASE WHEN trade_status = 'closed' AND LOWER(TRIM(ISNULL(signal,''))) = 'sell' AND net_return > 0 THEN net_return ELSE 0 END), 0),
            AVG(CASE WHEN trade_status = 'closed' AND LOWER(TRIM(ISNULL(signal,''))) = 'sell' AND net_return > 0 THEN entry_price ELSE NULL END)
        FROM #BlockDataTemp
        GROUP BY product;

        DECLARE @RowCount INT = @@ROWCOUNT;
        PRINT CONCAT('Snapshot captured successfully at ', FORMAT(@CurrentSnapshotTime, 'yyyy-MM-dd HH:mm:ss'), '. ', @RowCount, ' product rows inserted into product_signal_snapshot.');

        DROP TABLE #BlockDataTemp;
        RETURN 0;

    END TRY
    BEGIN CATCH
        PRINT CONCAT('ERROR: An error occurred while capturing the snapshot. Error Number: ', ERROR_NUMBER(), ', Message: ', ERROR_MESSAGE());

        IF OBJECT_ID('tempdb..#BlockDataTemp') IS NOT NULL
            DROP TABLE #BlockDataTemp;

        RETURN -1;
    END CATCH;

END;

CREATE PROCEDURE dbo.sp_creatediagram
(
	@diagramname 	sysname,
	@owner_id		int	= null, 	
	@version 		int,
	@definition 	varbinary(max)
)
WITH EXECUTE AS 'dbo'
AS
BEGIN
	set nocount on

	declare @theId int
	declare @retval int
	declare @IsDbo	int
	declare @userName sysname
	if(@version is null or @diagramname is null)
	begin
		RAISERROR (N'E_INVALIDARG', 16, 1);
		return -1
	end

	execute as caller;
	select @theId = DATABASE_PRINCIPAL_ID(); 
	select @IsDbo = IS_MEMBER(N'db_owner');
	revert; 
	
	if @owner_id is null
	begin
		select @owner_id = @theId;
	end
	else
	begin
		if @theId <> @owner_id
		begin
			if @IsDbo = 0
			begin
				RAISERROR (N'E_INVALIDARG', 16, 1);
				return -1
			end
			select @theId = @owner_id
		end
	end
	-- next 2 line only for test, will be removed after define name unique
	if EXISTS(select diagram_id from dbo.sysdiagrams where principal_id = @theId and name = @diagramname)
	begin
		RAISERROR ('The name is already used.', 16, 1);
		return -2
	end

	insert into dbo.sysdiagrams(name, principal_id , version, definition)
			VALUES(@diagramname, @theId, @version, @definition) ;
	
	select @retval = @@IDENTITY 
	return @retval
END

