CREATE PROCEDURE [dbo].[sp_helper_ghost_close]
    @trade_guid UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    -- Check if the trade exists and is not already ghost-closed
    IF NOT EXISTS (SELECT 1 FROM dbo.combined_trades_open WHERE guid = @trade_guid AND ISNULL(tradeable, 0) <> 5)
    BEGIN
        DECLARE @guid_str NVARCHAR(36) = CONVERT(NVARCHAR(36), @trade_guid);
        RAISERROR('Trade with GUID %s not found or already ghost-closed.', 16, 1, @guid_str);
        RETURN;
    END

    BEGIN TRY
        BEGIN TRANSACTION;

        -- 1. Update the open trade to mark it as ghost-closed
        UPDATE dbo.combined_trades_open
        SET
            g_close_time = GETUTCDATE(),
            g_net_return = net_return,
            g_alt_net_return = alt_net_return,
            tradeable = 5 -- Mark as ghost-closed
        WHERE
            guid = @trade_guid;

        -- 2. Prepare the details for the external notification
        DECLARE @trade_details NVARCHAR(1000);
        DECLARE @product_type VARCHAR(255);
        DECLARE @signal VARCHAR(255);
        DECLARE @product VARCHAR(255);
        DECLARE @trade_reason NVARCHAR(MAX);
        DECLARE @flip_trade BIT;
        DECLARE @trade_time DATETIME;

        -- Get the details from the trade we just updated
        SELECT
            @trade_details = CONCAT(
                o.product, ',',
                ISNULL(fp.secType, 'CASH'), ',',
                ISNULL(fp.exchange, 'IDEALPRO'), ',',
                ISNULL(fp.exchange, 'IDEALPRO'), ',',
                ISNULL(fp.currency, 'USD'), ',',
                'MKT', ',',
                CAST(o.trade_quantity AS VARCHAR(50)), ',',
                -- Reverse the signal for closing
                CASE WHEN UPPER(o.signal) IN ('BUY', 'B') THEN 'SELL' ELSE 'BUY' END
            ),
            @product_type = o.product_type,
            -- The signal for the close action is the reverse
            @signal = CASE WHEN UPPER(o.signal) IN ('BUY', 'B') THEN 'SELL' ELSE 'BUY' END,
            @product = o.product,
            @trade_reason = 'Ghost Close',
            @flip_trade = o.flip_trade,
            @trade_time = o.g_close_time
        FROM
            dbo.combined_trades_open o
        OUTER APPLY (
            SELECT TOP (1)
                fp.secType,
                fp.currency,
                fp.exchange
            FROM dbo.forex_products AS fp
            WHERE UPPER(fp.symbol) = o.product
            ORDER BY fp.id -- Simple deterministic selection
        ) AS fp
        WHERE
            o.guid = @trade_guid;

        -- 3. Insert into tbl_rt_trades to trigger external process
        INSERT INTO dbo.tbl_rt_trades (
            trade_time,
            trade_guid,
            trade_details,
            trade_status,
            execution_status,
            product_type,
            signal,
            product,
            trade_reason,
            flip_trade
        )
        VALUES (
            @trade_time,
            @trade_guid,
            @trade_details,
            'close', -- Explicitly a close signal
            'pending',
            @product_type,
            @signal,
            @product,
            @trade_reason,
            @flip_trade
        );

        COMMIT TRANSACTION;

        -- 4. Return the notification record as JSON for confirmation
        SELECT
            trade_id,
            trade_time,
            trade_guid,
            trade_details,
            trade_status,
            execution_status,
            product,
            signal
        FROM
            dbo.tbl_rt_trades
        WHERE
            trade_id = SCOPE_IDENTITY()
        FOR JSON PATH, WITHOUT_ARRAY_WRAPPER;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        -- Re-throw the error
        THROW;
    END CATCH;
END

