CREATE PROCEDURE dbo.sp_renamediagram
(
	@diagramname 		sysname,
	@owner_id		int	= null,
	@new_diagramname	sysname

)
WITH EXECUTE AS 'dbo'
AS
BEGIN
	set nocount on
	declare @theId 			int
	declare @IsDbo 			int
	
	declare @UIDFound 		int
	declare @DiagId			int
	declare @DiagIdTarg		int
	declare @u_name			sysname
	if((@diagramname is null) or (@new_diagramname is null))
	begin
		RAISERROR ('Invalid value', 16, 1);
		return -1
	end

	EXECUTE AS CALLER;
	select @theId = DATABASE_PRINCIPAL_ID();
	select @IsDbo = IS_MEMBER(N'db_owner'); 
	if(@owner_id is null)
		select @owner_id = @theId;
	REVERT;

	select @u_name = USER_NAME(@owner_id)

	select @DiagId = diagram_id, @UIDFound = principal_id from dbo.sysdiagrams where principal_id = @owner_id and name = @diagramname 
	if(@DiagId IS NULL or (@IsDbo = 0 and @UIDFound <> @theId))
	begin
		RAISERROR ('Diagram does not exist or you do not have permission.', 16, 1)
		return -3
	end

	-- if((@u_name is not null) and (@new_diagramname = @diagramname))	-- nothing will change
	--	return 0;

	if(@u_name is null)
		select @DiagIdTarg = diagram_id from dbo.sysdiagrams where principal_id = @theId and name = @new_diagramname
	else
		select @DiagIdTarg = diagram_id from dbo.sysdiagrams where principal_id = @owner_id and name = @new_diagramname

	if((@DiagIdTarg is not null) and  @DiagId <> @DiagIdTarg)
	begin
		RAISERROR ('The name is already used.', 16, 1);
		return -2
	end		

	if(@u_name is null)
		update dbo.sysdiagrams set [name] = @new_diagramname, principal_id = @theId where diagram_id = @DiagId
	else
		update dbo.sysdiagrams set [name] = @new_diagramname where diagram_id = @DiagId
	return 0
END

CREATE   PROCEDURE [dbo].[sp_seed_product_forex_dna]
    @base_product NVARCHAR(50) = N'gbp',
    @start_model_id_param INT = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    -- GEMINI: 2025-10-10 - NEXT VERSION NUMBER - Created for scalable seeding of product_forex with DNA models.

    -- GEMINI: 2025-11-26 - NEXT VERSION NUMBER - Configuration for profit capping, now fetched from dbo.config.
    DECLARE @max_profit_cap DECIMAL(18, 2);
    SELECT @max_profit_cap = ISNULL(TRY_CAST(config_value AS DECIMAL(18, 2)), 300.00) FROM dbo.config WHERE config_name = 'seed_max_profit_cap';

    -- GEMINI: 2025-11-26 - NEXT VERSION NUMBER - Configuration for minimum profit, fetched from dbo.config.
    DECLARE @min_profit DECIMAL(18, 2);
    SELECT @min_profit = ISNULL(TRY_CAST(config_value AS DECIMAL(18, 2)), 0.00) FROM dbo.config WHERE config_name = 'seed_min_profit';


    DECLARE @num_models_from_config INT;
    SELECT @num_models_from_config = TRY_CAST(config_value AS INT) FROM dbo.config WHERE config_name = 'number_of_seed_model';
    IF @num_models_from_config IS NULL OR @num_models_from_config <= 0 SET @num_models_from_config = 10; -- Default if config is missing or invalid

    DECLARE @current_model_id INT;
    DECLARE @max_existing_model_id INT;
    DECLARE @counter INT = 0;
    DECLARE @dna_json NVARCHAR(MAX);
    DECLARE @model_name NVARCHAR(50);

    -- Determine starting model ID
    SELECT @max_existing_model_id = MAX(TRY_CAST(SUBSTRING(model, 5, LEN(model) - 4) AS INT))
    FROM dbo.product_forex
    WHERE model LIKE 'DNA_%';

    SET @current_model_id = ISNULL(@max_existing_model_id, 100000);
    IF @start_model_id_param IS NOT NULL AND @start_model_id_param > @current_model_id
        SET @current_model_id = @start_model_id_param;

    SET @current_model_id = @current_model_id + 1; -- Start from the next available ID

    RAISERROR(N'Starting seeding from model ID %d', 0, 1, @current_model_id) WITH NOWAIT;

    -- Fetch the bias configuration
    DECLARE @seed_target_bias DECIMAL(18, 4);
    SELECT @seed_target_bias = ISNULL(TRY_CAST(config_value AS DECIMAL(18, 4)), 0.0) FROM dbo.config WHERE config_name = 'seed_target_bias';

    DECLARE @bias_as_string NVARCHAR(50) = CAST(@seed_target_bias AS NVARCHAR(50));
    RAISERROR(N'Using seed_target_bias: %s', 0, 1, @bias_as_string) WITH NOWAIT;

    DECLARE @attempt_counter INT = 0;
    DECLARE @max_attempts INT = @num_models_from_config * 200; -- Safeguard against impossible conditions

    WHILE @counter < @num_models_from_config AND @attempt_counter < @max_attempts
    BEGIN
        -- Always increment attempt counter
        SET @attempt_counter = @attempt_counter + 1;

        -- Generate random DNA_JSON
        DECLARE @temp_dna_json NVARCHAR(MAX);
        SET @temp_dna_json = JSON_QUERY((
            SELECT
                signal = (SELECT TOP 1 value FROM (VALUES ('BUY'), ('SELL'), ('BOTH')) AS s(value) ORDER BY NEWID()),
                leg_qty = (SELECT TOP 1 value FROM (VALUES (100000)) AS l(value) ORDER BY NEWID()),
                max_legs = (SELECT TOP 1 value FROM (VALUES (1), (2), (3)) AS m(value) ORDER BY NEWID()),
                execute_mode = (SELECT TOP 1 value FROM (VALUES ('every_minutes'), ('price_move'), ('clock_bucket'), ('event_gate')) AS em(value) ORDER BY NEWID()),
                execute_value_code = (SELECT TOP 1 value FROM (VALUES (1), (2), (3), (4), (5)) AS ev(value) ORDER BY NEWID()),
                stagger_type = (SELECT TOP 1 value FROM (VALUES ('none'), ('time'), ('price')) AS st(value) ORDER BY NEWID()),
                stagger_value_code = (SELECT TOP 1 value FROM (VALUES (1), (2), (3), (4)) AS sv(value) ORDER BY NEWID()),
                trailing_mode = (SELECT TOP 1 value FROM (VALUES ('off'), ('percent'), ('pips')) AS tm(value) ORDER BY NEWID()),
                trailing_value_code = (SELECT TOP 1 value FROM (VALUES (1), (2), (3), (4), (5), (6)) AS tv(value) ORDER BY NEWID()),
                profit_protect_enabled = (SELECT TOP 1 value FROM (VALUES (CAST(1 AS BIT)), (CAST(0 AS BIT))) AS ppe(value) ORDER BY NEWID()),
                pp_trigger_code = (SELECT TOP 1 value FROM (VALUES (1), (2), (3), (4), (5)) AS ppt(value) ORDER BY NEWID()),
                pp_lock_code = (SELECT TOP 1 value FROM (VALUES (1), (2), (3), (4), (5)) AS ppl(value) ORDER BY NEWID()),
                exit_rule = (SELECT TOP 1 value FROM (VALUES ('none'), ('max_duration'), ('flip'), ('breakeven_then_tp_sl')) AS er(value) ORDER BY NEWID()),
                exit_value_code = (SELECT TOP 1 value FROM (VALUES (1), (2), (3)) AS evc(value) ORDER BY NEWID())
            FOR JSON PATH
        ), '$[0]');

        -- GEMINI: 2025-12-14 - NEXT VERSION NUMBER - Generate pip values as random decimals directly to increase variety.
        -- Using RAND() which returns a float between 0 and 1. Formula: min + (max - min) * RAND()
        DECLARE @min_tp_pips DECIMAL(18, 2) = 3.0;
        DECLARE @max_tp_pips DECIMAL(18, 2) = 100.0;
        DECLARE @min_sl_pips DECIMAL(18, 2) = 5.0;
        DECLARE @max_sl_pips DECIMAL(18, 2) = 100.0;
        DECLARE @check_tp_pips DECIMAL(18, 2) = @min_tp_pips + (@max_tp_pips - @min_tp_pips) * RAND();
        DECLARE @check_sl_pips DECIMAL(18, 2) = @min_sl_pips + (@max_sl_pips - @min_sl_pips) * RAND();

        -- GEMINI: 2025-11-19 - NEXT VERSION NUMBER - Modified bias check to support configurable risk-reward ratios.
        -- Check if the generated DNA meets the bias criteria
        DECLARE @is_valid_bias BIT = 0;
        IF @seed_target_bias = 0 -- No Bias
            SET @is_valid_bias = 1;
        ELSE IF @seed_target_bias > 0 AND @check_tp_pips >= @seed_target_bias * @check_sl_pips -- Profit Bias
            SET @is_valid_bias = 1;
        ELSE IF @seed_target_bias < 0 AND @check_sl_pips >= ABS(@seed_target_bias) * @check_tp_pips -- Safety Bias
            SET @is_valid_bias = 1;

        -- If valid, proceed with insertion
        IF @is_valid_bias = 1
        BEGIN
            -- GEMINI: 2025-11-26 - NEXT VERSION NUMBER - Add check to cap max profit.
            -- This filters out DNA combinations that would result in a target profit greater than the cap.
            -- GEMINI: 2025-12-14 - NEXT VERSION NUMBER - Also check for uniqueness of target_profit/target_loss combination for the product.
            DECLARE @calculated_profit DECIMAL(18, 2) = @check_tp_pips * (10 * CAST(JSON_VALUE(@temp_dna_json, '$.leg_qty') AS DECIMAL(18,2)) / 100000.0);
            DECLARE @calculated_loss DECIMAL(18, 2) = -1 * @check_sl_pips * (10 * CAST(JSON_VALUE(@temp_dna_json, '$.leg_qty') AS DECIMAL(18,2)) / 100000.0);

            IF @calculated_profit >= @min_profit AND @calculated_profit <= @max_profit_cap
               AND NOT EXISTS (SELECT 1 FROM dbo.product_forex WHERE product = @base_product AND target_profit = @calculated_profit AND target_loss = @calculated_loss)
            BEGIN
                SET @model_name = CONCAT('DNA_', @current_model_id);
                SET @dna_json = @temp_dna_json;

                -- Derive product_forex columns from the validated DNA_JSON
                DECLARE @derived_leg_qty BIGINT = JSON_VALUE(@dna_json, '$.leg_qty');
                DECLARE @derived_commission TINYINT = (@derived_leg_qty / 10000) * 2; -- Dynamic commission
                DECLARE @derived_use_target_exit_only BIT = CASE WHEN JSON_VALUE(@dna_json, '$.exit_rule') = 'none' THEN 1 ELSE 0 END;

                -- Insert into product_forex
                INSERT INTO dbo.product_forex (
                    product, min_val, contract_size, commission, model, target_profit, target_loss, trade_qty,
                    product_type, tradeable, trade_freq, rl_action, add_to_blog, tradeable_daily, mapto_tradezone,
                    full_target, use_trade_count, flip_trade, use_target_exit_only, multi_close_option,
                    dna_array, dna_json
                )
                VALUES (
                    @base_product, 10, 100000, @derived_commission, @model_name,
                    @calculated_profit,
                    @calculated_loss, 
                    @derived_leg_qty,
                    'forex', 0, 99, 1, 1, 1, 0, -- 99 is placeholder for 'dna' trade_freq
                    NULL, 0, NULL, @derived_use_target_exit_only, 'none', -- full_target, use_trade_count, flip_trade, use_target_exit_only, multi_close_option
                    NULL, @dna_json -- dna_array is NULL for now, dna_json is populated
                );

                -- Increment success counter and model ID only on successful insertion
                SET @counter = @counter + 1;
                SET @current_model_id = @current_model_id + 1;

                RAISERROR(N'Seeded model %s (%d/%d)', 0, 1, @model_name, @counter, @num_models_from_config) WITH NOWAIT;
            END
        END
    END

    -- Add a warning if the loop exited due to max attempts
    IF @counter < @num_models_from_config
    BEGIN
        RAISERROR(N'Warning: Seeding stopped after %d attempts. Only %d of %d requested models were generated.', 10, 1, @attempt_counter, @counter, @num_models_from_config) WITH NOWAIT;
    END

    RAISERROR(N'Seeding complete. Total models: %d', 0, 1, @num_models_from_config) WITH NOWAIT;
END

