CREATE   PROCEDURE [dbo].[usp_ArchiveCombinedTradesClosedByDate]
    @ArchiveBefore DATE,
    @BatchSize INT = 1000
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @ArchiveBefore IS NULL
        THROW 50001, 'ArchiveBefore is required.', 1;
    IF @BatchSize < 1 OR @BatchSize > 10000
        THROW 50002, 'BatchSize must be between 1 and 10000.', 1;

    DECLARE @RowCount INT = 1;
    DECLARE @ArchivedRows BIGINT = 0;

    WHILE @RowCount > 0
    BEGIN
        BEGIN TRANSACTION;

        DELETE TOP (@BatchSize)
        FROM dbo.combined_trades_closed WITH (READPAST, ROWLOCK)
        OUTPUT
            DELETED.guid,
            DELETED.model,
            DELETED.product,
            DELETED.signal,
            DELETED.created,
            DELETED.last_update,
            DELETED.entry_price,
            DELETED.latest_price,
            DELETED.net_return,
            DELETED.alt_net_return
        INTO dbo.combined_trades_closed_arc
        (
            guid, model, product, signal, created, last_update,
            entry_price, latest_price, net_return, alt_net_return
        )
        WHERE created < @ArchiveBefore
        OPTION (MAXDOP 1);

        SET @RowCount = @@ROWCOUNT;
        SET @ArchivedRows += @RowCount;
        COMMIT TRANSACTION;
    END;

    SELECT @ArchiveBefore AS archive_before,
           @ArchivedRows AS archived_rows,
           COUNT_BIG(*) AS remaining_rows
    FROM dbo.combined_trades_closed;
END;

CREATE   PROCEDURE dbo.usp_auto_deactivate_flat_matrix_children
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @run_id BIGINT, @started DATETIME2 = SYSUTCDATETIME();
    DECLARE @deactivated INT = 0;

    INSERT INTO dbo.auto_deactivate_flat_children_run_log(started_at, status) VALUES (@started, 'running');
    SET @run_id = SCOPE_IDENTITY();

    BEGIN TRY
        UPDATE pf
        SET pf.trade_freq = 0
        FROM dbo.product_forex pf
        WHERE pf.model LIKE 'DNA[_]%[_]0[0-9][0-9][0-9]'
          AND pf.trade_freq <> 0
          AND NOT EXISTS (
              SELECT 1 FROM dbo.combined_trades_open o WITH (NOLOCK)
              WHERE o.model = pf.model
          );

        SET @deactivated = @@ROWCOUNT;

        UPDATE dbo.auto_deactivate_flat_children_run_log
        SET completed_at = SYSUTCDATETIME(), status = 'success', models_deactivated = @deactivated
        WHERE run_id = @run_id;
    END TRY
    BEGIN CATCH
        UPDATE dbo.auto_deactivate_flat_children_run_log
        SET completed_at = SYSUTCDATETIME(), status = 'failed', error_message = ERROR_MESSAGE()
        WHERE run_id = @run_id;
        THROW;
    END CATCH
END

