CREATE   PROCEDURE dbo.usp_ep051_capture_strategy_rank_history
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @run_id bigint, @started datetime2 = sysutcdatetime();
    DECLARE @captured_at datetime2 = CAST(SYSUTCDATETIME() AS datetime2(0));
    DECLARE @today date = CAST(SYSUTCDATETIME() AS date);
    DECLARE @today_start datetime2 = CAST(@today AS datetime2);
    DECLARE @today_end datetime2 = DATEADD(day, 1, @today_start);
    DECLARE @row_count int;
    DECLARE @basis varchar(32) = 'current_day_v1';
    DECLARE @wm_closed_at datetime2, @wm_guid nvarchar(64);

    INSERT INTO dbo.ep051_rank_capture_run_log(started_at, status) VALUES (@started, 'running');
    SET @run_id = SCOPE_IDENTITY();

    BEGIN TRY
        -- Day rollover: start today's running totals and watermark fresh.
        IF NOT EXISTS (SELECT 1 FROM dbo.ep051_rank_capture_watermark WHERE id = 1 AND for_date = @today)
        BEGIN
            DELETE FROM dbo.ep051_strategy_rank_running_totals WHERE for_date <> @today;
            DELETE FROM dbo.ep051_rank_capture_watermark WHERE id = 1;
            INSERT INTO dbo.ep051_rank_capture_watermark (id, for_date, last_closed_at, last_guid)
            VALUES (1, @today, @today_start, N'');
        END

        SELECT @wm_closed_at = last_closed_at, @wm_guid = last_guid
        FROM dbo.ep051_rank_capture_watermark WHERE id = 1;

        WITH new_trades AS (
            SELECT CASE WHEN RIGHT(model,2) IN ('_B','_S') THEN LEFT(model,LEN(model)-2) ELSE model END strategy_id,
                   CAST(net_return AS float) net_return,
                   COALESCE(g_close_time,last_update,created) closed_at, guid
            FROM dbo.combined_trades_closed WITH (NOLOCK)
            WHERE model_ix LIKE 'DNA[_]%' AND net_return IS NOT NULL
              AND created >= @today_start AND created < @today_end
              AND (COALESCE(g_close_time,last_update,created) > @wm_closed_at
                   OR (COALESCE(g_close_time,last_update,created) = @wm_closed_at AND guid > @wm_guid))
        ),
        deltas AS (
            SELECT strategy_id, SUM(net_return) delta_net_return, COUNT(*) delta_trades
            FROM new_trades GROUP BY strategy_id
        )
        MERGE dbo.ep051_strategy_rank_running_totals AS target
        USING deltas AS source
        ON target.for_date = @today AND target.strategy_id = source.strategy_id
        WHEN MATCHED THEN
            UPDATE SET total_net_return = target.total_net_return + source.delta_net_return,
                       total_trades = target.total_trades + source.delta_trades,
                       updated_at = sysutcdatetime()
        WHEN NOT MATCHED THEN
            INSERT (for_date, strategy_id, total_net_return, total_trades, updated_at)
            VALUES (@today, source.strategy_id, source.delta_net_return, source.delta_trades, sysutcdatetime())
        OPTION (MAXDOP 1);

        -- Advance the watermark past every trade just folded in (no-op if there were none).
        UPDATE dbo.ep051_rank_capture_watermark
        SET last_closed_at = new_max.closed_at, last_guid = new_max.guid
        FROM dbo.ep051_rank_capture_watermark wm
        CROSS APPLY (
            SELECT TOP 1 closed_at, guid
            FROM (
                SELECT COALESCE(g_close_time,last_update,created) closed_at, guid
                FROM dbo.combined_trades_closed WITH (NOLOCK)
                WHERE model_ix LIKE 'DNA[_]%' AND net_return IS NOT NULL
                  AND created >= @today_start AND created < @today_end
                  AND (COALESCE(g_close_time,last_update,created) > @wm_closed_at
                       OR (COALESCE(g_close_time,last_update,created) = @wm_closed_at AND guid > @wm_guid))
            ) t
            ORDER BY closed_at DESC, guid DESC
        ) new_max
        WHERE wm.id = 1;

        INSERT INTO dbo.ep051_strategy_rank_history (captured_at, strategy_id, total_net_return, total_trades, rank_position, basis)
        SELECT @captured_at, strategy_id, total_net_return, total_trades,
               RANK() OVER (ORDER BY total_net_return DESC), @basis
        FROM dbo.ep051_strategy_rank_running_totals
        WHERE for_date = @today
        OPTION (MAXDOP 1);

        SET @row_count = @@ROWCOUNT;

        UPDATE dbo.ep051_rank_capture_run_log
        SET completed_at = sysutcdatetime(), strategy_rows = @row_count, status = 'success'
        WHERE run_id = @run_id;
    END TRY
    BEGIN CATCH
        UPDATE dbo.ep051_rank_capture_run_log
        SET completed_at = sysutcdatetime(), status = 'failed', error_message = ERROR_MESSAGE()
        WHERE run_id = @run_id;
        THROW;
    END CATCH
END

CREATE   PROCEDURE dbo.usp_ep052_manage_dna_matrix
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @run_id BIGINT, @started DATETIME2 = SYSUTCDATETIME();
    DECLARE @today DATE = CAST(SYSUTCDATETIME() AS DATE);
    DECLARE @today_start DATETIME2 = CAST(@today AS DATETIME2);
    DECLARE @today_end DATETIME2 = DATEADD(DAY, 1, @today_start);
    DECLARE @threshold INT;
    DECLARE @models_created INT = 0, @models_reactivated INT = 0, @models_deactivated INT = 0;

    SELECT @threshold = TRY_CAST(config_value AS INT) FROM dbo.config WHERE config_name = 'ep052_dna_matrix_hot_streak_threshold';
    IF @threshold IS NULL SET @threshold = 5;

    INSERT INTO dbo.ep052_dna_matrix_run_log(started_at, status) VALUES (@started, 'running');
    SET @run_id = SCOPE_IDENTITY();

    BEGIN TRY
        -- Hot base models: strictly model_ix LIKE 'DNA[_]%' (base series only -
        -- excludes DNA_xxxxxx_000N matrix children so a child can never trigger
        -- its own matrix), all of today's closed trades on that model are wins.
        DECLARE @hot TABLE (model VARCHAR(64) PRIMARY KEY, trades INT);
        INSERT INTO @hot (model, trades)
        SELECT model, COUNT(*)
        FROM dbo.combined_trades_closed WITH (NOLOCK)
        WHERE model_ix LIKE 'DNA[_]%'
          AND model NOT LIKE 'DNA[_]%[_]0[0-9][0-9][0-9]'
          AND net_return IS NOT NULL
          AND created >= @today_start AND created < @today_end
        GROUP BY model
        HAVING COUNT(*) >= @threshold AND SUM(CASE WHEN net_return <= 0 THEN 1 ELSE 0 END) = 0;

        -- Short-circuit: nothing hot this iteration AND no currently-active
        -- matrix children exist to potentially deactivate - skip the
        -- reactivation UPDATE, the create-matrix cursor, and the
        -- deactivation UPDATE entirely rather than running all three every
        -- single loop iteration regardless of outcome.
        IF NOT EXISTS (SELECT 1 FROM @hot)
           AND NOT EXISTS (
               SELECT 1 FROM dbo.product_forex
               WHERE model LIKE 'DNA[_]%[_]0[0-9][0-9][0-9]' AND trade_freq <> 0
           )
        BEGIN
            UPDATE dbo.ep052_dna_matrix_run_log
            SET completed_at = SYSUTCDATETIME(), status = 'success',
                models_created = 0, models_reactivated = 0, models_deactivated = 0
            WHERE run_id = @run_id;
            RETURN;
        END

        -- Reactivate matrices that already exist for a hot model.
        UPDATE pf_child
        SET pf_child.trade_freq = pf_parent.trade_freq
        FROM dbo.product_forex pf_child
        JOIN dbo.product_forex pf_parent ON pf_child.model LIKE pf_parent.model + '[_]0[0-9][0-9][0-9]'
        JOIN @hot h ON h.model = pf_parent.model
        WHERE pf_child.trade_freq <> pf_parent.trade_freq;
        SET @models_reactivated = @@ROWCOUNT;

        -- Create matrices for hot models that have none yet - one full copy of
        -- the parent's own product_forex row per offset, only target_profit/
        -- target_loss/tp_pips/sl_pips/strategy_name/strategy_params/model changed.
        DECLARE @offsets TABLE (suffix CHAR(4), tp_delta INT);
        INSERT INTO @offsets (suffix, tp_delta) VALUES
            ('0001', 1), ('0002', 2), ('0003', 3), ('0004', 4), ('0005', 5),
            ('0006', -1), ('0007', -2), ('0008', -3), ('0009', -4), ('0010', -5);

        DECLARE needs_matrix CURSOR LOCAL FAST_FORWARD FOR
            SELECT pf.product, pf.min_val, pf.contract_size, pf.commission, pf.model,
                   pf.target_profit, pf.target_loss, pf.trade_qty, pf.product_type,
                   pf.tradeable, pf.trade_freq, pf.rl_action, pf.add_to_blog, pf.tradeable_daily,
                   pf.mapto_tradezone, pf.full_target, pf.use_trade_count, pf.flip_trade,
                   pf.use_target_exit_only, pf.multi_close_option, pf.dna_json, pf.strategy_name,
                   JSON_VALUE(pf.dna_json, '$.tp_pips') AS tp_pips,
                   JSON_VALUE(pf.dna_json, '$.sl_pips') AS sl_pips
            FROM dbo.product_forex pf
            JOIN @hot h ON h.model = pf.model
            WHERE NOT EXISTS (
                SELECT 1 FROM dbo.product_forex child
                WHERE child.model LIKE pf.model + '[_]0[0-9][0-9][0-9]'
            );

        DECLARE @product VARCHAR(32), @min_val INT, @contract_size INT, @commission INT,
                @model VARCHAR(64), @target_profit INT, @target_loss INT, @trade_qty INT,
                @product_type VARCHAR(32), @tradeable INT, @trade_freq INT, @rl_action INT,
                @add_to_blog BIT, @tradeable_daily BIT, @mapto_tradezone BIT, @full_target INT,
                @use_trade_count BIT, @flip_trade BIT, @use_target_exit_only BIT,
                @multi_close_option VARCHAR(32), @dna_json NVARCHAR(MAX), @strategy_name VARCHAR(128),
                @tp_pips INT, @sl_pips INT;

        OPEN needs_matrix;
        FETCH NEXT FROM needs_matrix INTO @product, @min_val, @contract_size, @commission, @model,
            @target_profit, @target_loss, @trade_qty, @product_type, @tradeable, @trade_freq,
            @rl_action, @add_to_blog, @tradeable_daily, @mapto_tradezone, @full_target,
            @use_trade_count, @flip_trade, @use_target_exit_only, @multi_close_option, @dna_json,
            @strategy_name, @tp_pips, @sl_pips;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            DECLARE @base_name VARCHAR(96) = LEFT(@strategy_name, LEN(@strategy_name) - LEN('tp' + CAST(@tp_pips AS VARCHAR) + '_sl' + CAST(@sl_pips AS VARCHAR)));

            INSERT INTO dbo.product_forex (
                product, min_val, contract_size, commission, model, target_profit, target_loss,
                trade_qty, product_type, tradeable, trade_freq, rl_action, add_to_blog,
                tradeable_daily, mapto_tradezone, full_target, use_trade_count, flip_trade,
                use_target_exit_only, multi_close_option, dna_array, dna_json, strategy_name, strategy_params
            )
            SELECT @product, @min_val, @contract_size, @commission,
                   @model + '_' + o.suffix,
                   (@tp_pips + o.tp_delta) * 10,
                   -((@sl_pips + o.tp_delta) * 10),
                   @trade_qty, @product_type, @tradeable, @trade_freq, @rl_action, @add_to_blog,
                   @tradeable_daily, @mapto_tradezone, @full_target, @use_trade_count, @flip_trade,
                   @use_target_exit_only, @multi_close_option, NULL,
                   JSON_MODIFY(JSON_MODIFY(@dna_json, '$.tp_pips', @tp_pips + o.tp_delta), '$.sl_pips', @sl_pips + o.tp_delta),
                   @base_name + 'tp' + CAST(@tp_pips + o.tp_delta AS VARCHAR) + '_sl' + CAST(@sl_pips + o.tp_delta AS VARCHAR),
                   'window=' + JSON_VALUE(@dna_json, '$.window_size') + ',tp=' + CAST(@tp_pips + o.tp_delta AS VARCHAR) + ',sl=' + CAST(@sl_pips + o.tp_delta AS VARCHAR)
            FROM @offsets o;
            SET @models_created += 10;

            FETCH NEXT FROM needs_matrix INTO @product, @min_val, @contract_size, @commission, @model,
                @target_profit, @target_loss, @trade_qty, @product_type, @tradeable, @trade_freq,
                @rl_action, @add_to_blog, @tradeable_daily, @mapto_tradezone, @full_target,
                @use_trade_count, @flip_trade, @use_target_exit_only, @multi_close_option, @dna_json,
                @strategy_name, @tp_pips, @sl_pips;
        END
        CLOSE needs_matrix;
        DEALLOCATE needs_matrix;

        -- End-of-day deactivation: any currently-active matrix child whose
        -- parent isn't in today's hot set gets switched off until it earns
        -- reactivation on a future hot day. Safe to run every cycle - a hot
        -- parent's own children were just reactivated above, so they're
        -- correctly excluded here.
        UPDATE child
        SET child.trade_freq = 0
        FROM dbo.product_forex child
        WHERE child.model LIKE 'DNA[_]%[_]0[0-9][0-9][0-9]'
          AND child.trade_freq <> 0
          AND NOT EXISTS (
              SELECT 1 FROM @hot h
              WHERE child.model LIKE h.model + '[_]0[0-9][0-9][0-9]'
          );
        SET @models_deactivated = @@ROWCOUNT;

        UPDATE dbo.ep052_dna_matrix_run_log
        SET completed_at = SYSUTCDATETIME(), status = 'success',
            models_created = @models_created, models_reactivated = @models_reactivated,
            models_deactivated = @models_deactivated
        WHERE run_id = @run_id;
    END TRY
    BEGIN CATCH
        IF CURSOR_STATUS('local', 'needs_matrix') >= -1
        BEGIN
            CLOSE needs_matrix;
            DEALLOCATE needs_matrix;
        END
        UPDATE dbo.ep052_dna_matrix_run_log
        SET completed_at = SYSUTCDATETIME(), status = 'failed', error_message = ERROR_MESSAGE()
        WHERE run_id = @run_id;
        THROW;
    END CATCH
END

-- =============================================
-- Author:      Roo (Generated based on Python script)
-- Create date: 2025-04-03
-- Description: Replicates the logic of algo_trade_open_link11.py
--              to find unlinked trades, check signals, and create
--              new linked trades while closing opposite ones.
--              Uses 'dbo.product_forex' for product information.
--
-- Prerequisites:
-- 1. Tables: dbo.product_forex, dbo.Trades (or equivalent for combined open/closed)
-- 2. Functions/SPs: dbo.udf_GetLatestTradeSignal, dbo.udf_GetLatestPrice,
--                    dbo.udf_IsModelSignalInLatestTimeslot, dbo.usp_CloseTrade (or similar logic)
-- =============================================
CREATE PROCEDURE [dbo].[usp_ProcessTradeLinks] -- Changed CREATE to ALTER
    @LinkValue INT = 11 -- Parameterize the link value, defaulting to 11 as per script
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON; -- Ensures transaction rollback on error

    -- Declare variables
    -- Adjusted variable names slightly to match assumed column names from product_forex
    DECLARE @Model VARCHAR(100), @ProductName VARCHAR(100), @ProductType VARCHAR(50);
    DECLARE @Signal VARCHAR(10);
    DECLARE @GeneratedSignal VARCHAR(10);
    DECLARE @CurrentBid DECIMAL(18, 5), @CurrentAsk DECIMAL(18, 5);
    DECLARE @LastTradeID INT;
    DECLARE @OppositeSignal VARCHAR(10);
    DECLARE @EntryPrice DECIMAL(18, 5), @LatestPrice DECIMAL(18, 5);
    DECLARE @EntryPrice2 DECIMAL(18, 5), @LatestPrice2 DECIMAL(18, 5);
    DECLARE @ExitPrice DECIMAL(18, 5), @ExitPrice2 DECIMAL(18, 5);
    DECLARE @IsCurrentlyTradeable BIT;
    DECLARE @TargetProfit DECIMAL(18, 2) = 1000; -- Default, consider fetching from config
    DECLARE @TargetLoss DECIMAL(18, 2) = -1000; -- Default, consider fetching from config
    DECLARE @CurrentTimestamp DATETIME2 = GETDATE();
    DECLARE @ErrorMessage NVARCHAR(MAX);
    DECLARE @ErrorSeverity INT;
    DECLARE @ErrorState INT;

    -- Temporary table for signals to iterate
    DECLARE @Signals TABLE (Signal VARCHAR(10) PRIMARY KEY);
    INSERT INTO @Signals (Signal) VALUES ('buy'), ('sell');

    -- Cursor to loop through tradeable models from dbo.product_forex
    DECLARE model_cursor CURSOR LOCAL FAST_FORWARD FOR
        -- *** MODIFIED THIS SECTION ***
        SELECT model, product, product_type -- Assuming these column names exist
        FROM dbo.product_forex -- Using the correct table name
        WHERE tradeable = 1; -- Assuming 'tradeable' column exists and 1 means tradeable
        -- *** END MODIFICATION ***

    OPEN model_cursor;
    -- *** MODIFIED THIS SECTION ***
    FETCH NEXT FROM model_cursor INTO @Model, @ProductName, @ProductType; -- Adjusted variables
    -- *** END MODIFICATION ***

    WHILE @@FETCH_STATUS = 0
    BEGIN
        -- Cursor to loop through signals ('buy', 'sell')
        DECLARE signal_cursor CURSOR LOCAL FAST_FORWARD FOR
            SELECT Signal FROM @Signals;

        OPEN signal_cursor;
        FETCH NEXT FROM signal_cursor INTO @Signal;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            BEGIN TRY
                -- Reset variables for this iteration
                SET @GeneratedSignal = NULL;
                SET @CurrentBid = NULL;
                SET @CurrentAsk = NULL;
                SET @LastTradeID = NULL;

                -- **********************************************************
                -- 1. Replicate analyze_trade_performance & Get Signal
                -- **********************************************************
                -- Fetch latest signal recommendation (Requires dbo.udf_GetLatestTradeSignal function)
                SELECT @GeneratedSignal = CalculatedSignal -- Adapt based on actual function output
                FROM dbo.udf_GetLatestTradeSignal(@ProductName); -- Pass ProductName from cursor

                -- Fetch current price (Requires dbo.udf_GetLatestPrice function)
                SELECT @CurrentBid = Bid, @CurrentAsk = Ask
                FROM dbo.udf_GetLatestPrice(@ProductName, @ProductType); -- Pass ProductName & ProductType

                -- **********************************************************
                -- 2. Check Signal Match and Price Availability
                -- **********************************************************
                IF @Signal = @GeneratedSignal AND @GeneratedSignal IS NOT NULL AND @GeneratedSignal <> 'No signal' AND @CurrentBid IS NOT NULL AND @CurrentAsk IS NOT NULL
                BEGIN
                    -- **********************************************************
                    -- 3. Find Last Unlinked Trade (Replicate get_last_trade_details)
                    -- **********************************************************
                    -- *** Assumes dbo.Trades table has a 'model' column matching the type in product_forex ***
                    SELECT TOP 1 @LastTradeID = TradeID
                    FROM dbo.Trades WITH (NOLOCK) -- Use NOLOCK cautiously
                    WHERE model = @Model -- Filter by model from cursor
                      AND Signal = @Signal
                      AND Status = 'Open'
                      AND LinkedValue IS NULL
                      AND (
                           (@Signal = 'buy' AND (ISNULL(BuyCount, 0) - ISNULL(SellCount, 0)) > 0) OR
                           (@Signal = 'sell' AND (ISNULL(BuyCount, 0) - ISNULL(SellCount, 0)) < 0)
                          )
                    ORDER BY CreatedTimestamp DESC;

                    -- **********************************************************
                    -- 4. Check for Existing Link (Replicate get_link_trade)
                    -- **********************************************************
                    IF @LastTradeID IS NOT NULL
                    BEGIN
                        IF NOT EXISTS (SELECT 1 FROM dbo.Trades WITH (NOLOCK)
                                       WHERE model = @Model -- Filter by model
                                         AND Signal = @Signal
                                         AND Product = @ProductName
                                         AND Status = 'Open'
                                         AND LinkedValue = @LinkValue)
                        BEGIN
                            -- **********************************************************
                            -- 5. Create/Update Link (Replicate create_or_update_trade_link)
                            -- **********************************************************
                            BEGIN TRANSACTION;

                            SET @OppositeSignal = CASE WHEN @Signal = 'buy' THEN 'sell' ELSE 'buy' END;

                            IF @Signal = 'buy'
                            BEGIN
                                SET @EntryPrice = @CurrentAsk; SET @LatestPrice = @CurrentBid;
                                SET @EntryPrice2 = @CurrentBid; SET @LatestPrice2 = @CurrentAsk;
                                SET @ExitPrice = @CurrentAsk; SET @ExitPrice2 = @CurrentBid;
                            END
                            ELSE -- Signal = 'sell'
                            BEGIN
                                SET @EntryPrice = @CurrentBid; SET @LatestPrice = @CurrentAsk;
                                SET @EntryPrice2 = @CurrentAsk; SET @LatestPrice2 = @CurrentBid;
                                SET @ExitPrice = @CurrentBid; SET @ExitPrice2 = @CurrentAsk;
                            END

                            -- Close opposite linked trade
                            UPDATE dbo.Trades
                            SET Status = 'Closed',
                                ClosedTimestamp = @CurrentTimestamp,
                                ExitPrice = @ExitPrice,
                                ExitPrice2 = @ExitPrice2
                            WHERE model = @Model -- Filter by model
                              AND Signal = @OppositeSignal
                              AND Status = 'Open'
                              AND LinkedValue = @LinkValue;

                            -- Check if model/signal is currently tradeable (Requires function: dbo.udf_IsModelSignalInLatestTimeslot)
                            SET @IsCurrentlyTradeable = dbo.udf_IsModelSignalInLatestTimeslot(@Model, @Signal, @LinkValue); -- Pass model

                            -- Insert the new linked trade record
                            INSERT INTO dbo.Trades (
                                model, Signal, Product, ProductType, Status, CreatedTimestamp, -- Use model column
                                EntryPrice, LatestPrice, EntryPrice2, LatestPrice2,
                                BuyCount, SellCount,
                                LinkedValue, IsTradeable, TargetProfit, TargetLoss
                            )
                            SELECT
                                @Model, @Signal, @ProductName, @ProductType, 'Open', @CurrentTimestamp, -- Insert model
                                @EntryPrice, @LatestPrice, @EntryPrice2, @LatestPrice2,
                                BuyCount, SellCount, -- Fetch counts from the source trade (@LastTradeID)
                                @LinkValue, @IsCurrentlyTradeable, @TargetProfit, @TargetLoss
                            FROM dbo.Trades WHERE TradeID = @LastTradeID;

                            COMMIT TRANSACTION;
                        END
                    END
                END

            END TRY
            BEGIN CATCH
                IF @@TRANCOUNT > 0
                    ROLLBACK TRANSACTION;

                SET @ErrorMessage = ERROR_MESSAGE();
                SET @ErrorSeverity = ERROR_SEVERITY();
                SET @ErrorState = ERROR_STATE();

                PRINT 'Error processing Model: ' + ISNULL(CAST(@Model AS VARCHAR), 'NULL') + ', Signal: ' + @Signal + ', Timestamp: ' + CONVERT(VARCHAR, GETDATE(), 121);
                PRINT 'Error Message: ' + @ErrorMessage;
                -- RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState); -- Optionally re-throw
            END CATCH

            FETCH NEXT FROM signal_cursor INTO @Signal;
        END;
        CLOSE signal_cursor;
        DEALLOCATE signal_cursor;

        -- *** MODIFIED THIS SECTION ***
        FETCH NEXT FROM model_cursor INTO @Model, @ProductName, @ProductType; -- Adjusted variables
        -- *** END MODIFICATION ***
    END;

    CLOSE model_cursor;
    DEALLOCATE model_cursor;

    SET NOCOUNT OFF;
END;

CREATE FUNCTION dbo.fn_800_classify_regime
(
    @metrics_id BIGINT,
    @prev_regime_state VARCHAR(32) = NULL
)
RETURNS @result TABLE
(
    regime_state      VARCHAR(32) NOT NULL,
    fast_side         VARCHAR(4)  NOT NULL,
    slow_side         VARCHAR(4)  NOT NULL,
    dur_ratio         DECIMAL(18,6) NULL,
    count_ratio       DECIMAL(18,6) NULL,
    fast_real_pnl     DECIMAL(19,4) NULL,
    slow_real_pnl     DECIMAL(19,4) NULL
)
AS
BEGIN
    DECLARE
        @buy_count INT,
        @sell_count INT,
        @buy_avg_duration DECIMAL(18,6),
        @sell_avg_duration DECIMAL(18,6),
        @buy_real_pnl DECIMAL(19,4),
        @sell_real_pnl DECIMAL(19,4),
        @dur_ratio DECIMAL(18,6),
        @count_ratio DECIMAL(18,6),
        @regime_state VARCHAR(32) = 'UNKNOWN',
        @fast_side VARCHAR(4) = 'NONE',
        @slow_side VARCHAR(4) = 'NONE';

    SELECT
        @buy_count = buy_trade_count,
        @sell_count = sell_trade_count,
        @buy_avg_duration = buy_avg_duration_minutes,
        @sell_avg_duration = sell_avg_duration_minutes,
        @buy_real_pnl = buy_real_pnl,
        @sell_real_pnl = sell_real_pnl,
        @dur_ratio = dur_ratio,
        @count_ratio = count_ratio
    FROM dbo.tbl_800_trade_metrics WITH (NOLOCK)
    WHERE metrics_id = @metrics_id;

    IF @buy_count IS NULL
    BEGIN
        INSERT INTO @result (regime_state, fast_side, slow_side, dur_ratio, count_ratio, fast_real_pnl, slow_real_pnl)
        VALUES ('UNKNOWN', 'NONE', 'NONE', NULL, NULL, NULL, NULL);
        RETURN;
    END;

    DECLARE
        @total_trades INT = ISNULL(@buy_count, 0) + ISNULL(@sell_count, 0),
        @min_trades_required INT = 3,
        @dur_ratio_trend_min DECIMAL(18,6) = 1.25,
        @count_ratio_trend_min DECIMAL(18,6) = 1.20,
        @fast_duration_cap DECIMAL(18,6) = 5.0,
        @compressed_count_tolerance INT = 1,
        @fast_real_pnl_min DECIMAL(19,4) = 0.0;

    IF @total_trades < @min_trades_required
    BEGIN
        SET @regime_state = 'UNKNOWN';
    END
    ELSE
    BEGIN
        DECLARE @candidate_fast VARCHAR(4) = 'BUY';
        DECLARE @candidate_slow VARCHAR(4) = 'SELL';

        IF ISNULL(@sell_avg_duration, 9999.0) < ISNULL(@buy_avg_duration, 9999.0)
        BEGIN
            SET @candidate_fast = 'SELL';
            SET @candidate_slow = 'BUY';
        END

        DECLARE @fast_avg_duration DECIMAL(18,6) = CASE WHEN @candidate_fast = 'BUY' THEN @buy_avg_duration ELSE @sell_avg_duration END;
        DECLARE @slow_avg_duration DECIMAL(18,6) = CASE WHEN @candidate_fast = 'BUY' THEN @sell_avg_duration ELSE @buy_avg_duration END;
        DECLARE @fast_real DECIMAL(19,4) = CASE WHEN @candidate_fast = 'BUY' THEN @buy_real_pnl ELSE @sell_real_pnl END;
        DECLARE @slow_real DECIMAL(19,4) = CASE WHEN @candidate_fast = 'BUY' THEN @sell_real_pnl ELSE @buy_real_pnl END;

        DECLARE @fast_count INT = CASE WHEN @candidate_fast = 'BUY' THEN @buy_count ELSE @sell_count END;
        DECLARE @slow_count INT = CASE WHEN @candidate_fast = 'BUY' THEN @sell_count ELSE @buy_count END;

        IF ISNULL(@dur_ratio, 0) < @dur_ratio_trend_min AND ISNULL(@count_ratio, 0) < @count_ratio_trend_min
        BEGIN
            SET @regime_state = 'CHOP';
        END
        ELSE IF ISNULL(@buy_avg_duration, 9999.0) <= @fast_duration_cap
             AND ISNULL(@sell_avg_duration, 9999.0) <= @fast_duration_cap
             AND ABS(ISNULL(@buy_count,0) - ISNULL(@sell_count,0)) <= @compressed_count_tolerance
        BEGIN
            SET @regime_state = 'COMPRESSED';
            SET @candidate_fast = 'NONE';
            SET @candidate_slow = 'NONE';
        END
        ELSE IF ISNULL(@fast_real, 0.0) < @fast_real_pnl_min
        BEGIN
            SET @regime_state = 'CHOP';
            SET @candidate_fast = 'NONE';
            SET @candidate_slow = 'NONE';
        END
        ELSE IF ISNULL(@dur_ratio, 0) >= @dur_ratio_trend_min AND ISNULL(@count_ratio, 0) >= @count_ratio_trend_min AND ISNULL(@fast_count, 0) > ISNULL(@slow_count, 0)
        BEGIN
            SET @regime_state = CASE WHEN @candidate_fast = 'BUY' THEN 'TREND_BUY' ELSE 'TREND_SELL' END;
        END
        ELSE IF @prev_regime_state IN ('TREND_BUY', 'TREND_SELL')
        BEGIN
            SET @regime_state = 'TRANSITION';
        END
        ELSE
        BEGIN
            SET @regime_state = 'UNKNOWN';
            SET @candidate_fast = 'NONE';
            SET @candidate_slow = 'NONE';
        END

        SET @fast_side = ISNULL(@candidate_fast, 'NONE');
        SET @slow_side = ISNULL(@candidate_slow, 'NONE');
    END

    DECLARE @fast_return DECIMAL(19,4) = CASE WHEN @fast_side = 'BUY' THEN @buy_real_pnl WHEN @fast_side = 'SELL' THEN @sell_real_pnl ELSE NULL END;
    DECLARE @slow_return DECIMAL(19,4) = CASE WHEN @slow_side = 'BUY' THEN @buy_real_pnl WHEN @slow_side = 'SELL' THEN @sell_real_pnl ELSE NULL END;

    INSERT INTO @result (regime_state, fast_side, slow_side, dur_ratio, count_ratio, fast_real_pnl, slow_real_pnl)
    VALUES (@regime_state, @fast_side, @slow_side, @dur_ratio, @count_ratio, @fast_return, @slow_return);

    RETURN;
END;

CREATE   FUNCTION dbo.fn_split_csv_with_index (@s NVARCHAR(MAX))
RETURNS @t TABLE (
  pos   INT              NOT NULL,
  value NVARCHAR(4000)   NOT NULL
)
AS
BEGIN
  IF @s IS NULL OR LTRIM(RTRIM(@s)) = '' RETURN;
  DECLARE @clean NVARCHAR(MAX) = REPLACE(REPLACE(@s, '{',''),'}','');

  DECLARE @xml XML = TRY_CAST('<x><i>' + REPLACE(@clean, ',', '</i><i>') + '</i></x>' AS XML);
  IF @xml IS NULL RETURN;

  INSERT INTO @t(pos, value)
  SELECT ROW_NUMBER() OVER (ORDER BY (SELECT 1)) AS pos,
         LTRIM(RTRIM(T.C.value('.', 'nvarchar(4000)'))) AS value
  FROM @xml.nodes('/x/i') AS T(C);

  RETURN;
END

-- Creates a function that splits a string based on a delimiter and returns items with their order.
CREATE FUNCTION dbo.fn_SplitString
(
    @String NVARCHAR(MAX),
    @Delimiter CHAR(1)
)
RETURNS @temptable TABLE
(
    Item NVARCHAR(MAX),
    ItemOrder INT
)
AS
BEGIN
    DECLARE @idx INT = -1;
    DECLARE @i INT = 0;
    DECLARE @tempString NVARCHAR(MAX) = @String;

    IF @String IS NULL RETURN; -- Handle NULL input

    WHILE (LEN(@tempString) > 0)
    BEGIN
        SET @idx = CHARINDEX(@Delimiter, @tempString);
        IF (@idx != 0)
        BEGIN
            SET @i = @i + 1;
            INSERT INTO @temptable (Item, ItemOrder) VALUES (LEFT(@tempString, @idx - 1), @i);
            SET @tempString = RIGHT(@tempString, LEN(@tempString) - @idx);
        END
        ELSE
        BEGIN
            SET @i = @i + 1;
            INSERT INTO @temptable (Item, ItemOrder) VALUES (@tempString, @i);
            SET @tempString = ''; -- Exit loop
        END
    END
    RETURN;
END;
